window.POEM_DB=window.POEM_DB||{};POEM_DB["song_013"]={"n":"王十朋","dyn":"宋","poems":[{"t":"夜听双瀑同刘方叔毛虞卿联句","f":"五言古诗","c":["夜静双瀑喧，遥闻疑雨来。","润壑生清风，襟宇捐纤埃。","飞鸣撼半空，暗想飘琼瑰。","前观阻步屧，侧耳成徘徊。","萧然山馆间，此兴何悠哉。","子晋不复见，月白空箫台。"]},{"t":"咏柳","f":"七言律诗","c":["东君于此最钟情，妆点村村入画屏。","向我无言眉自展，与人非故眼犹青。","萦牵别恨丝千尺，断送春光絮一亭。","叶底黄鹂音更好，隔溪烟雨醉时听。"]},{"t":"夜雨述怀","f":"七言律诗","c":["夜深风雨撼庭芭，唤起新愁似乱麻。","梦觉尚疑身是蝶，病苏方悟影非蛇。","浇肠竹叶频生晕，照眼银缸自结花。","我在故乡非逆旅，不烦杜宇唤归家。"]},{"t":"宿栖贤","f":"七言律诗","c":["瀑水声中夜不眠，星河影动半秋天。","谁云滟滪瞿唐远，只在洋澜左蠡边。","师子吼成方外法，石人参得定中禅。","住山五老知今古，借问曾栖几个贤。"]},{"t":"桃川","f":"七言律诗","c":["流水桃花世已非，石林烟草尚芳菲。","山中鸡黍聊炊午，眼底风尘且息机。","圣世难招秦晋隐，野心独爱芰荷衣。","寻真不遇空归去，笑指秋风绕翠微。"]},{"t":"韶美归舟过夔留半月语离作恶诗二章以送 其二","f":"七言律诗","c":["弱羽年来正倦飞，夔门邂逅故人归。","人生一笑难开口，世事多端合掩扉。","况是桑榆俱晚景，何曾富贵已危机。","明朝怅望仙舟远，百尺高楼上静晖。"]},{"t":"二郎神","f":"词","c":["深深院。","夜雨过，帘栊高卷。","正满槛、海棠开欲半。","仍朵朵、红深红浅。","遥认三千宫女面。","匀点点、胭脂未遍。","更微带、春醪宿醉，袅娜香肌娇艳。","日暖。","芳心暗吐，含羞轻颤。","笑繁杏夭桃争烂漫。","爱容易、出墙临岸。","子美当年游蜀苑。","又岂是、无心眷恋。","都只为、天然体态，难把诗工裁剪。"]},{"t":"点绛唇 其三 温香芍药","f":"词","c":["近侍盈盈，向人自笑还无语。","牡丹飘雨。","开作群芳主。","柔美温香，剪染劳天女。","青春去。","花间歌舞。","学个狂韩愈。"]},{"t":"点绛唇 其十五 南香含笑","f":"词","c":["南国名花，向人无语长含笑。","缘香囊小。","不肯全开了。","花笑何人，鹤相诗词好。","须知道。","一经品藻。","又压前诗倒。"]},{"t":"点绛唇 其十一 细香竹","f":"词","c":["秀色娟娟，最宜雨沐风梳际。","径幽香细。","草滴青襟袂。","一日才无，便觉生尘态。","轩窗外。","数竿相对。","不减王猷爱。"]},{"t":"点绛唇 其五 天香桂","f":"词","c":["仙友苍苍，西风吹散天香好。","暗飘龙脑。","金粟枝头小。","谁种丹霄，造化玄功妙。","真堪笑。","学仙疏谬。","有似西河老。"]},{"t":"点绛唇 其七 冷香菊","f":"词","c":["霜蕊鲜鲜，野人开径新栽植。","冷香佳色。","趁得重阳摘。","预约比邻，有酒须相觅。","东篱侧。","为花辞职。","古有陶彭泽。"]},{"t":"点绛唇 其十九 瑞香","f":"词","c":["阑槛阴沈，紫云呈瑞馀寒凛。","卷帘欹枕。","香逼幽人寝。","入梦何年，庐阜闻名稔。","风流甚。","阿谁题品。","唤作熏笼锦。"]},{"t":"点绛唇 其六 暗香梅","f":"词","c":["雪径深深，北枝贪睡南枝醒。","暗香疏影。","孤压群芳顶。","玉艳冰姿，妆点园林景。","凭阑咏。","月明溪静。","忆昔林和靖。"]},{"t":"点绛唇 其十二 嘉香海棠","f":"词","c":["丝蕊垂垂，嫣然一笑新妆就。","锦亭前后。","燕子来时候。","谁恨无香，试把花枝嗅。","风微透。","细熏锦袖。","不止嘉州有。"]},{"t":"点绛唇 其十八 素香丁香","f":"词","c":["落木萧萧，琉璃叶下琼葩吐。","素香柔树。","雅称幽人趣。","无意争先，梅蕊休相妒。","含春雨。","结愁千绪。","似忆江南主。"]},{"t":"点绛唇 其一 酴醾","f":"词","c":["野态芳姿，枝头占得春长久。","怕钩衣袖。","不放攀花手。","试问东山，花似当时否。","还依旧。","谪仙去后。","风月今谁有。"]},{"t":"点绛唇 其十四 艳香茉莉","f":"词","c":["畏日炎炎，梵香一炷熏亭院。","鼻根充满。","好利心殊浅。","贝叶书名，名义谁能辨。","西风远。","胜鬟不见。","喜见琼花面。"]},{"t":"点绛唇 其九 妙香檐卜","f":"词","c":["毗舍遥遥，异香一炷驰名久。","妙香稀有。","鼻观深参透。","问讯东来，知□谁先后。","称仙友。","十花为偶。","近有江西守。"]},{"t":"点绛唇 其十三 清香莲","f":"词","c":["十里西湖，淡妆浓抹如西子。","藕花簪水。","清净香无比。","记得曾游，短棹红云里。","聊相拟。","一盆池水。","十里西湖似。"]},{"t":"点绛唇 其八 韵香荼蘼","f":"词","c":["羽盖垂垂，玉英乱簇春光满。","韵香清远。","暖日烘庭院。","露浥琼枝，脸透何郎晕。","凝余恨。","古人不见。","谁与花公论。"]},{"t":"点绛唇 其十六 奇香蜡梅","f":"词","c":["蜡换梅姿，天然香韵初非俗。","蝶驰蜂逐。","蜜在花梢熟。","岩壑深藏，几载甘幽独。","因坡谷。","一标题目。","高价掀兰菊。"]},{"t":"点绛唇 其四 国香兰","f":"词","c":["芳友依依，结根遥向深林外。","国香风递。","始见殊萧艾。","雅操幽姿，不怕无人采。","堪纫佩。","灵均千载。","九畹遗芳在。"]},{"t":"先人旧题东山墓亭三绝 其一","f":"七言绝句","c":["入堂无复见双亲，建此来宁似在神。","天地深恩难以报，含悲唯有泪沾巾。"]},{"t":"对月同方叔联句","f":"五言律诗","c":["与君坐阶除，遥望海上月。","试举太白杯，借问几圆缺。","人生易分散，动作隔年别。","今宵对婵娟，莫放酣歌绝。"]},{"t":"癸未守岁","f":"五言绝句","c":["岁宜乡里守，杯共弟兄衔。","明日人相问，行年五十三。"]},{"t":"腊月二十八日与知宗提举分岁郡中啜茶于北楼赏梅于忠献堂知宗即席有诗次韵并简提舶","f":"七言律诗","c":["老病踰年卧晋江，耽诗性癖未能降。","园林牢落梅经眼，岁月峥嵘酒满缸。","堂上焚香敬勋德，楼头回首念家乡。","黄柑未拜萧嵩赐，乡味分珍谩一双。"]},{"t":"中秋对月用昌黎赠张功曹韵呈同官","f":"词","c":["水精为鉴金为波，挂空影写山与河。","清光此夜十分好，有酒有客宜高歌。","去年今日行役苦，浪叟溪边宿逢雨。","传闻蜀道如天高，崖悬壁绝哀猿号。","波横剑戟不易上，陆有虎豹何由逃。","江山旧恃白帝险，风俗犹带乌蛮臊。","驱驰两月到西塞，梦寐万里还东皋。","嗅梅踏雪巴子里，路入鬼门欣不死。","飞飞倦鸟惟思还，玉笋岂是粗官班。","馀生但愿闲及酒，虚名宁顾触与蛮。","良宵佳客十有五，云放月入尊罍间。","颓然老子兴不浅，韩诗坡句聊追攀。","君不见天宝云霓羽衣歌，人间乐舞难同科，遗音犹在悲凉多。","有酒且饮遑恤他，不饮如此良夜何。"]},{"t":"云安下岩","f":"七言律诗","c":["涛江翻雪卷湖滩，晚泊岩扉暂解颜。","夙有净缘逢寺喜，老无生理伴僧閒。","残云已断犹飞雨，落日将沉却照山。","半夜秋声惊客梦，一帘珠贝冷珊珊。"]},{"t":"书不欺室","f":"七言绝句","c":["室明室暗两何疑，方寸长存不可欺。","勿谓天高鬼神远，要须先畏自家知。"]},{"t":"知宗生日","f":"七言律诗","c":["天工未放二阳生，留得尧阶一荚蓂。","庆诞仙源贵公子，祥开南极老人星。","日垂宫线添无尽，貌比庄椿看更清。","岁岁华堂祝眉寿，笙歌声里雪梅馨。"]},{"t":"梁彭州与客登卧龙山送酒二尊 其一","f":"七言绝句","c":["五马携壶上卧龙，四夔连骑与游从。","山中古柏岁寒色，应为清流作意浓。"]},{"t":"岳阳楼","f":"七言律诗","c":["后乐先忧记饱观，兹楼今始得凭栏。","吐吞五水波涛阔，出纳三光境界宽。","黄帝乐声喧广宙，湘君山影侵晴澜。","江山何独助张说，收拾清诗上笔端。"]},{"t":"点绛唇 其二 咏十八香异香牡丹","f":"词","c":["庭院深深，异香一片来天上。","傲春迟放。","百卉皆推让。","忆昔西都，姚魏声名旺堪惆怅。","醉翁何往。","谁与花标榜。"]},{"t":"畎亩十首 其一","f":"五言律诗","c":["畎亩有遗士，妄怀葵藿心。","朝夕倾太阳，不耐氛秽侵。","肝胆有古剑，愿言决群阴。","兹志尚郁郁，抱膝成悲吟。"]},{"t":"畎亩十首 其二","f":"五言律诗","c":["古道日云邈，古意谁复知。","阳春漠无和，流水空含悲。","郢曲变新调，郑声入朱丝。","喟然三叹馀，默与羲皇期。"]},{"t":"畎亩十首 其三","f":"五言古诗","c":["读书不知道，言语徒自工。","求道匪云远，近在义命中。","吾儒有仲尼，道德无比崇。","传参十八章，入道知其宗。","后学昧极致，徒知授儿童。","孰识孝与弟，理与神明通。","为臣不知此，事上焉能忠。"]},{"t":"畎亩十首 其四","f":"五言古诗","c":["仲尼作春秋，垂训千万年。","古者父母雠，义不共戴天。","庄同父何在，乃与齐侯田。","鲁国无臣子，君亲义茫然。","齐纪不并立，诸儿得称贤。","善恶不可掩，笔削至今传。"]},{"t":"畎亩十首 其五","f":"五言律诗","c":["飞飞古帝魂，哀哀寄春怨。","异乡节物新，故国人事变。","诉亡谁肯怜，啼苦血空溅。","云安再拜人，伤哉不复见。"]},{"t":"畎亩十首 其六","f":"五言古诗","c":["彼微双鹡鸰，飞飞同一原。","急难喻兄弟，义著周雅篇。","周公代武王，大义今古传。","人孰无兄弟，急难斯见焉。","愿怀周公心，无愧诗人言。"]},{"t":"畎亩十首 其七","f":"五言古诗","c":["竹有君子节，青青贯四时。","桃李媚春光，千株弄妖姿。","世眼悦繁艳，畴能赏幽奇。","君看桃李蹊，蹄毂纷争驰。","君看竹林下，形影谁相随。","七贤久沦没，高躅犹可追。","吾家植千竿，风月足自怡。","岂不竞时好，聊为岁寒期。"]},{"t":"畎亩十首 其八","f":"五言古诗","c":["兀兀窗下士，笔耕志良苦。","黄卷对圣贤，慷慨深自许。","一朝出干禄，得失战匈宇。","曲意阿有司，谀言徇人主。","贪荣无百年，贻谤有千古。","丈夫宜自贵，清议重刀斧。"]},{"t":"畎亩十首 其九","f":"五言律诗","c":["我岂不欲仕，时命不吾与。","曷不枉尺求，权门正旁午。","非道吾弗由，兹心已先许。","愿言安贫贱，顺命为出处。"]},{"t":"畎亩十首 其十","f":"五言律诗","c":["儒冠误身世，偃蹇二十年。","岂不怀明主，富贵乃在天。","平生学忠孝，自致无由前。","青灯照夜长，感激徒自怜。"]},{"t":"观国朝故事 其一","f":"五言古诗","c":["昔在景德初，胡虏犯中原。","朝廷用莱公，决策幸澶渊。","高琼虽武夫，能发忠义言。","咏诗退虏骑，用丑枢相颜。","銮舆至北城，断桥示不还。","一箭毙挞览，夜半却腥膻。","至仁不忍杀，和好垂百年。","伟哉澶渊功，天子能用贤。"]},{"t":"观国朝故事 其二","f":"五言古诗","c":["昔在康定初，元昊叛西陲。","朝廷起韩范，节制阃外师。","二公人中龙，材略超等夷。","匈中百万兵，对面千里机。","不比大老子，而令虏能欺。","深期复灵夏，重勒燕然碑。","军中果兴谣，西贼心胆隳。","逆节遂称臣，战士解甲归。","社稷安泰山，四海绝疮痍。","堂堂宁复有，为作思贤诗。"]},{"t":"观国朝故事 其三","f":"五言古诗","c":["昔在元祐初，朝廷用老成。","元恶首窜殛，贤隽皆汇征。","帘帏八年政，内外咸清明。","四夷各自守，天下几太平。","绍圣党论起，宵人坏典刑。","二蔡唱继述，曲学尊金陵。","忠良投海岛，党籍编姓名。","春秋亦获罪，学者专三经。","心术遂大坏，风俗从此倾。","养成前日祸，中原厌膻腥。","我欲著一书，善恶深劝惩。","奸谀诛朽骨，潜德发幽馨。","六贼未足罪，祸端首熙宁。"]},{"t":"观国朝故事 其四","f":"五言古诗","c":["富公昔使虏，厉色争献纳。","臣节安敢亏，君恩以死答。","煌煌中国尊，忍为豺狼屈。","堂堂汉使者，刚气不可折。","斯人嗟已亡，英风复谁接。","衔命虏庭人，偷生真婢妾。"]},{"t":"㶁㶁岸下水","f":"五言古诗","c":["㶁㶁岸下水，汝流欲何之。","但见日东注，宁有还源期。","尼父川上叹，逝者亦如斯。","人生百年间，扰扰无已时。","利名役初心，百欢无一追。","待汝后知悔，桑榆景堪悲。","感此盍悟彼，毋为浪吁嘻。"]},{"t":"宣和乙巳冬大雪次表叔贾元实韵","f":"七言律诗","c":["天公昨夜屑琼花，三尺深深晓更加。","柳不待春先起絮，梅非因笛自飞华。","牧羊大窖人何在，驻马蓝关路更赊。","安得晴天开万里，行人愁思渺无涯。"]},{"t":"伤时感怀 其一","f":"七言律诗","c":["三万六千成掷梭，欢娱常少愁常多。","干戈今日犹未定，书剑他年知若何。","淡荡三秋冷时节，萧条万里空山河。","伤时眼泪满襟血，更把少陵诗句哦。"]},{"t":"伤时感怀 其二","f":"七言律诗","c":["帝乡五载乱离中，亿万苍生陷犬戎。","二圣远征沙漠北，六龙遥渡浙江东。","斩奸盍请朱云剑，射虏宜贯李广弓。","借问秦庭谁恸哭，草茅无路献孤忠。"]},{"t":"驾幸温州次僧宗觉韵","f":"七言律诗","c":["圣主南巡驻六飞，邦人咫尺见天威。","间关高帝尚鞍马，谨厚汉光犹绛衣。","北斗城池增王气，东瓯山水发清辉。","伫看天仗还京阙，无复旄头彗紫微。"]},{"t":"次韵谦仲见寄","f":"五言古诗","c":["湖山蓝黛青，湖水琉璃碧。","我时湖边游，山水正秋色。","诗翁偶乘兴，来作湖边客。","谈锋两初交，意气已相得。","诗坛予与盟，文会公为伯。","豪词肆滂沛，淡语入幽寂。","心匠巧雕斲，物态穷搜觅。","壮哉五言城，卓尔万仞壁。","初疑公肠胃，百怪所窟宅。","吐气干云霄，宜欲斗霹雳。","妙夺解牛术，奏刀声砉剨。","我才寸莛微，洪钟讵能击。","又如鸣蟋蟀，啾然和金石。","未窥学藩篱，敢语讨奥赜。","缪为马慕韩，浪作赤效白。","奖拔非所蒙，猖狂固宜责。","新篇又拜嘉，开缄光艳射。","藏之比明珠，长使夜照席。","惜哉不遇时，岂为臧仓隔。","儒冠五十年，世路疲行役。","操矛赴文场，战艺辄败北。","书剑两无成，泥涂困踪迹。","龙钟似东野，穷愁揽怀臆。","空吟三百篇，高视古无敌。","霜风剪林木，黄叶满泽国。","我思公不见，羸马未能策。","恨无神仙术，安得生两翼。","因召管城颖，免冠加拂拭。","书帛寄征鸿，心目两俱极。"]},{"t":"送凌知监赴玉环次觉无象韵","f":"五言古诗","c":["晨兴趣行装，秋色满离席。","悲风苦送声，短晷频移刻。","兰舟薄暮发，去去转遐僻。","极目望官所，沉沉烟霭积。","清有濯缨水，白有漱齿石。","悠然水石间，官情聊自适。","朝焉游其南，暮焉戏其北。","彼微山中鸟，亦将识公德。","公无赋归去，田园付人役。"]},{"t":"答毛唐卿虞卿借昌黎集","f":"七言古诗","c":["予少不知学古难，学古直欲学到韩。","柰何韩实不易学，怛觉昼夜心力殚。","茫然故步亦已失，有类寿陵学邯郸。","虽然予心未肯已，尚欲勉强求其端。","跬步不休效驽马，千里未至空长叹。","羡君兄弟俱早慧，家学岂止传柔温。","圣经贤传饫已久，百家诸子皆蠹残。","学文要须学韩子，此外众说徒曼曼。","韩子皇皇慕仁义，力排佛老回狂澜。","三百年来道益贵，太山北斗世仰观。","我生于今望之远，时时开卷相欣欢。","岂惟庐陵惜旧本，我亦惜此祇自看。","子今欲假敢违命，愿子宝之同琅玕。"]},{"t":"辛亥九日侍家君同孙子渊子昭子尚登高于家之东山时菊花未开坐客皆以为恨至十月望独步东篱下见前日青枝已烂熳矣东坡云凉天佳月即中秋菊花开日乃重阳不以日月断也于是命酒肴呼邻里饮于丛畔云","f":"五言古诗","c":["前日重阳日，与客同登玩。","有酒无菊花，把杯一长叹。","良辰苦易失，十月今又半。","缅焉想前游，独到东篱畔。","鲜鲜霜中菊，满地金钱粲。","我思东坡言，邻里乃相唤。","斩新作重九，不以日月断。","人生贵适意，世俗岂能绊。","遇酒即欢乐，取醉期烂熳。","羲和驭白日，疾剧走丸弹。","百年能几何，不饮乃痴汉。"]},{"t":"次韵季仲默见寄","f":"五言古诗","c":["予少择交游，有友四五子。","仲默姿不凡，好学喜观史。","寄我新诗章，我惊欲掩耳。","昔日心未降，而今已降矣。","我久事章句，滋味一杯水。","平生况多愚，于己不自揣。","林间等蝉噪，井底作蛙视。","今焉见君诗，吾诚二虫比。","岂敢妒且热，低头拜不止。","思欲和其音，兀坐辄忘起。","沉吟竟不成，徒觉倦两髀。","从今焚笔砚，不复坐书几。"]},{"t":"题湖边庄","f":"七言律诗","c":["十里青山荫碧湖，湖边风物画难如。","夕阳茅舍客沽酒，明月小桥人钓鱼。","旧卜草庄临水竹，来寻野叟问耕锄。","他年待挂衣冠后，乘兴扁舟取次居。"]},{"t":"湖边怀刘谦仲","f":"七言律诗","c":["湖山如画水如蓝，杖屦湖边酒半酣。","往事萧条谁共说，旧游零落我何堪。","炎凉世态从他变，生死交情祇自谙。","诗客有魂招不得，秋风依旧满江南。"]},{"t":"寄孙永之","f":"七言律诗","c":["咏歌沂水舞雩风，气压当时冠与童。","人似贾生年更少，家传孙绰赋尤工。","孤罴傲兀深丛里，一鹗轩昂众鸟中。","早取功名寄衣钵，古来相种出山东。"]},{"t":"寄毛虞卿","f":"七言律诗","c":["文会今年喜重寻，葭姿玉质又同林。","弟兄并秀如君少，朋友相知独我深。","一别几劳终夜梦，相逢更话百年心。","长卿赋有凌云志，却笑区区蚓窍吟。"]},{"t":"次韵虞卿送别","f":"七言律诗","c":["喜君直谅更多闻，共惜光阴寸与分。","萤照夜窗才煖席，蝉吟秋树又离群。","尊前忍听阳关曲，江上愁看日暮云。","别后谁能慰牢落，锦囊长带故人文。"]},{"t":"次韵刘方叔见寄","f":"七言律诗","c":["交情贵久岂须频，我辈尤宜率且真。","子政有孙诚益友，长卿何代乏诗人。","论文初喜逢知己，言志深期共致身。","箕斗相望正南北，颍川何夕聚荀陈。"]},{"t":"寄方叔","f":"七言律诗","c":["故人一别路漫漫，又觉春生到水村。","鱼跃雁飞空注目，柳开梅落自消魂。","唱酬应有诗千首，谈笑长怀酒一尊。","正是刚肠九回处，子规声断月黄昏。"]},{"t":"潘岐哥","f":"词","c":["君不见凤之雏，骥之子，潘家岐哥无乃是。","鹤溪仙子降英灵，雁荡名山钟秀美。","颜色纯明白玉璞，精神皎洁秋江水。","胸中之气已吞牛，开眼睛光如虎视。","此儿奇绝非常儿，小子观人盖多矣。","宁非汉代偷桃朔，别是唐家谪仙李。","愚知先生百不忧，但患此儿名盛耳。","先生才高爵未绾，赖渠力振家声起。","鹿岩他日筑高门，车马煌煌塞闾里。"]},{"t":"赠余取新","f":"七言律诗","c":["小邑那能敌大邦，与君角力固非双。","气骄欲纵偏师战，势屈翻求北面降。","深惧操戈重入室，自惭阁笔久临窗。","定知纸价从今贵，余子诗名满蜃江。"]},{"t":"次韵昝监务早梅","f":"七言律诗","c":["群芳避路放梅开，奔走游人满砌苔。","半树溪边冲雪破，一枝头上带春回。","月移瘦影供吟兴，风荐幽香袭酒杯。","刚被西湖都道尽，至今诗客句难裁。"]},{"t":"寄贾一节","f":"七言律诗","c":["无奈穷冬易感伤，况添离别助凄凉。","五更月残频成梦，十里青山几断肠。","短棹未乘晨雪去，尺书聊遣暮鸿将。","少年勉力亲灯火，要使家声继洛阳。"]},{"t":"孙子尚过明庆以诗见招未及往次韵","f":"七言律诗","c":["剡溪未起子猷寻，空对溪山恨满襟。","孤雁远来天杳杳，故人相望雪深深。","思君一日成三岁，寄我行书直万金。","惆怅今宵一尊酒，自邀明月伴孤斟。"]},{"t":"送子尚如浙西","f":"七言古诗","c":["嗟我穷居海之角，人物素殊邹鲁俗。","年虽及冠无交游，孤陋寡闻嗟独学。","闭门不出长太息，思得其人共磨琢。","孙子往从西北来，头角轩轩真一鹗。","飘飘逸气凌云霄，凛凛高谈吐锋锷。","文辞翰墨两奇绝，世上群儿徒碌碌。","我昔风期一相遇，欣然握手论心腹。","衡茅三度枉车轩，书剑连年共灯烛。","论交自喜得房杜，言志端能效来郝。","长篇短韵迭赓唱，明月清风共斟酌。","囊无一钱身不忧，食止一箪贫自乐。","有友如君复何憾，百不为多一已足。","今焉舍我将何之，遂使江乡复萧索。","南国初寒旅雁来，吴江已冷丹枫落。","惜君不尽与君别，兀坐无言情更恶。","干戈未息行路难，胡马今独饮河洛。","京国有家归未得，钱塘此去仍栖托。","会须徒步谒天子，慨然一吐胸中略。","请缨缚虏壮志士，庶使平时语无怍。","相将煖律破寒梅，驿筒远寄无辞数。"]},{"t":"怀子尚","f":"七言律诗","c":["满眼干戈行路难，故人千里驻征鞍。","几劳终日驰魂梦，安得乘风插羽翰。","水北山南春寂寂，天涯海角路漫漫。","欲凭人寄新消息，手把梅枝仔细看。"]},{"t":"乐清僧寮有过客钱之翰题二绝有伤时之叹因次其韵 其一","f":"七言绝句","c":["终日伤心泪溅花，干戈满眼恨无涯。","衣冠南渡如东晋，安得车书混一家。"]},{"t":"乐清僧寮有过客钱之翰题二绝有伤时之叹因次其韵 其二","f":"七言绝句","c":["功名谁复汉嫖姚，壮士逢时岂惮劳。","半夜飞来看宝剑，此身端许掷鸿毛。"]},{"t":"读亲征诏书二首 其一","f":"七言律诗","c":["逆虏何时正典刑，久闻诸将拥彊兵。","中原未雪十年耻，圣主自劳千里征。","楚国群臣谁恸哭，杜陵野客自吞声。","君恩压顶丘山重，命掷鸿毛未是轻。"]},{"t":"读亲征诏书二首 其二","f":"七言律诗","c":["诸将年来已极荣，回看烟阁欠功名。","八年犹未平淮甸，一战那能复帝京。","畎亩忠臣自忧国，闾阎小子妄谈兵。","凭谁决得天河水，一洗乾坤万里清。"]},{"t":"次韵题曹大夫怀忠阁","f":"七言律诗","c":["小阁谁怀畎亩情，遥瞻天日眼增明。","平生忧国丹心在，一饭思君血泪横。","礼沛功臣真有种，并汾壮士素蜚声。","区区问舍求田者，应被元龙一笑轻。"]},{"t":"闻韩帅世忠退保丹阳远近忧惧州县议结乡兵以备不虞闾巷少年贯弓走马若有得色感而有作","f":"七言律诗","c":["逆虏纵横未剪齐，王师退保浙江西。","羽书日报犹未息，戎捷远来何太稽。","千里战云新鬼哭，满天阴雨夜乌啼。","臂弓腰箭谁家子，竟日鸣鞭跃马蹄。"]},{"t":"和刘方叔溪上一绝","f":"七言绝句","c":["杖屦徘徊驻碧溪，遥看飞瀑下崔嵬。","乘槎欲访吹箫客，烟草茫茫没旧台。"]},{"t":"和方叔见赠二绝 其一","f":"七言绝句","c":["相对清谈味有馀，始知胜读十年书。","尘襟不用频挥麈，自有清风为扫除。"]},{"t":"和方叔见赠二绝 其二","f":"七言绝句","c":["一舍萧然学有馀，窗间遮眼尽文书。","已将事业盟灯火，万事何烦酒破除。"]},{"t":"得陈商霖书","f":"七言律诗","c":["山馆无人慰索居，喜君交契有终初。","扁舟方起雪溪兴，尺素又传鱼腹书。","炊黍定寻前日约，题诗宁怨故人疏。","好来相共亲灯火，可惜青春度莫虚。"]},{"t":"昔与南浦刘谦仲大梁孙子尚游自刘死横阳孙亦有浙西之役交旧零落为之慨然感而有作","f":"七言律诗","c":["刘翁泯泯已新鬼，孙子飘飘犹旅人。","诗酒旧游谁在眼，江山回首自伤神。","招魂拟向横阳道，有梦长飞霅水滨。","死者不生生者别，死生离别两沾巾。"]},{"t":"次韵李刑曹病起书怀","f":"七言律诗","c":["中原回首尚尘飞，书剑南来早识机。","方事高眠学安石，却愁多病似王徽。","肠枯谩有书千卷，腰瘦难胜带十围。","志士未逢聊尔耳，古人何用泣牛衣。"]},{"t":"又用前韵","f":"七言律诗","c":["文园病思乱如飞，禅榻逍遥谩息机。","渐喜珠丝封药裹，未容鹤发上簪徽。","酒能伐性聊须止，棋恐劳神未敢围。","惟有诗怀禁不得，任他憔瘦不胜衣。"]},{"t":"送曹大夫赴行在所","f":"七言古诗","c":["西北连年杀气高，群盗横行如猬毛。","廉颇李牧不世出，吾皇侧席心焦劳。","汾阳自古多壮士，曹侯意气千人豪。","年今四十犹偃蹇，拊髀长叹淹龙韬。","慨然挥袂谒行在，报国已淬腰间刀。","登坛拜将预指日，看君举手清风涛。"]},{"t":"送表叔贾元范赴省试","f":"七言古诗","c":["河东先生才行高，昔游太学联烝髦。","雄文伟论万人敌，糠秕歆向奴刘曹。","抟风自许九万里，肯作斥鴳游蓬蒿。","礼闱一战果得隽，妙割不折庖丁刀。","礼部无端抑韩子，至今士论犹嗷嗷。","霜蹄暂蹶志益锐，不学郊岛徒悲号。","圣君图治方侧席，兹复下诏求贤豪。","壮怀思雪会稽耻，广场猛效兰皋鏖。","焚舟决胜在此举，乡闾属望心焦劳。","天庭射策决素蕴，忠言为国驱腥臊。","区区一第溷君耳，要将事业窥伊皋。","琼林宴罢跃归骑，薰风拂面吹恩袍。"]},{"t":"答季仲宜","f":"七言古诗","c":["我昔从君伯氏游，短素长笺日唱酬。","凌云健笔驱山丘，欲追李杜参曹刘。","子今又复振风流，可人一气真吾俦。","明珠白璧蒙暗投，自揣无堪但增羞。","君家棠棣才俱优，吾知徐公百不忧。","更能勉力追前修，俯舍青紫何须求。"]},{"t":"游箫峰","f":"五言律诗","c":["蜡屐穿云去，山深喜路通。","人家烟色里，古寺水声中。","金溅星犹在，丹成灶已空。","吹箫人不见，台下想仙风。"]},{"t":"题双瀑","f":"五言律诗","c":["瀑水箫峰下，灵源不可寻。","倚天双宝剑，点石万星金。","势合鲸鲵斗，声联虎豹吟。","我来游胜境，洗耳听清音。"]},{"t":"送刘方叔兼简全之","f":"五言律诗","c":["相见无多日，依前又素居。","断魂梅的皪，过眼柳萧疏。","疋马来时路，征鸿别后书。","君归见温叟，为我问何如。"]},{"t":"送陈商霖","f":"五言律诗","c":["相逢犹未款，作别太匆匆。","日落江东莫，人归冀北空。","音尘应暂隔，谈笑更谁同。","回首箫峰外，明朝我亦东。"]},{"t":"昼卧书怀","f":"七言律诗","c":["书斋终日无人过，闭户便便事高卧。","炎蒸烁体汗流珠，蚊蚋费拍蝇劳驱。","南窗清风可供客，一枕万钱无计得。","梦魂未到乡无何，起来搔首空吟哦。"]},{"t":"用前韵赠刘全之","f":"七言律诗","c":["一声啼鸟檐间过，唤起幽人午窗卧。","瓮头一滴价如珠，穷愁衮衮凭谁驱。","溪畔相逢尽诗客，豪迈独输刘梦得。","篇章自有神谁何，讵须元白参吟哦。"]},{"t":"有客赠酒同舍终夕尽欢复用前韵","f":"七言律诗","c":["浊醪不向墙头过，吏部方思瓮间卧。","书斋得酒胜得珠，万事尽向杯中驱。","坐中俱是高阳客，一笑相逢宁易得。","明朝酒醒奈愁何，劝君莫惜同吟哦。"]},{"t":"复用前韵","f":"七言律诗","c":["岁月侵寻等闲过，草庐尚作南阳卧。","报国未为蛇吐珠，许身定与谁齐驱。","谩比凌云词赋客，意气飘飘真自得。","金溪风月价几何，要须买断共吟哦。"]},{"t":"戏酬毛虞卿见和","f":"七言律诗","c":["杜门不愿高轩过，聊学东山谢公卧。","伤时泪泣鲛人珠，挥毫写懑风雨驱。","友生笑我为狂客，齐楚未须论失得。","他年功业定如何，醉中细把君诗哦。"]},{"t":"怀归预别同舍","f":"七言律诗","c":["长念双亲垂素发，不奉甘旨今数月。","溪山虽好何如归，吾心已逐秋云飞。","欲别良朋重呜咽，催人啼鸟声何切。","明日琴书随我东，何如尊酒重相逢。"]},{"t":"寄僧觉无象","f":"五言古诗","c":["我昔居鹿岩，时来潜涧游。","西坡访觉老，终日为迟留。","高谈穷古今，满坐风生秋。","令我名利心，一听浑欲休。","论诗出古律，有唱无不酬。","篇章溢缣素，锦绣烂然浮。","此老岂易得，当于前辈求。","吾生限太晚，见师已白头。","儒释道不同，相从苦无由。","三年游金溪，兀坐颜常愀。","出门无游从，独赋临清流。","金溪可无僧，孰是西坡俦。","深房锁花木，妙供罗珍羞。","益作潜涧思，刚肠如转辀。","魂梦不自禁，夜夜飞山陬。","前日遇诸涂，一笑忘百忧。","相视未及语，归袖风飕飕。","别来能几时，不觉岁月遒。","闻师结莲社，旦莫事真修。","我狂似灵运，此志那能投。"]},{"t":"秋日山林即事次叔父宝印师韵 其一","f":"七言古诗","c":["萧萧蘋末生秋声，登临遐想兰台英。","天高气清水碧色，明月相映光如琼。","脱叶翩翻下深樾，莲社高人诗兴发。","讲外吟馀心更闲，白云满袖眠禅窟。","竹径通幽人不来，鸟鸣山静独徘徊。","应笑世间名利客，一生扰扰徒悲哀。"]},{"t":"秋日山林即事次叔父宝印师韵 其二","f":"五言古诗","c":["清凉涤烦襟，尘虑脱心境。","山城过疏雨，水国生新景。","虫鸣月满林，雁度云横岭。","感物夜九起，谋身日三省。","平生功名心，郁郁犹未逞。","深美白云人，身闲时自永。"]},{"t":"和怀孙子尚二绝 其一","f":"七言绝句","c":["泽国萧萧晚吹凉，东篱黄菊为谁香。","故人一别路千里，夜雨何时更对床。"]},{"t":"和怀孙子尚二绝 其二","f":"七言绝句","c":["记得年时访我游，壁间文字数行留。","溪山风月依然好，不对芳尊又一秋。"]},{"t":"季令生日","f":"七言律诗","c":["佳气光芒蔼剑池，庆门呈瑞应熊罴。","人间秋色平分际，天上冰轮欲满时。","何处楚丘占季子，自应无忌似牢之。","姮娥预把蟾宫桂，岁岁飘香荐寿卮。"]},{"t":"徐丞生日","f":"七言律诗","c":["日月俱阳节物新，先期谁应菊花辰。","未于崧岳生贤佐，且向柯山出异人。","月吐霜天钟气象，江涵秋水聚精神。","华堂献寿人多少，尽是明朝落帽宾。"]},{"t":"思友","f":"五言律诗","c":["夜雨暗点滴，窗风冷掀翻。","藜床卧幽独，好梦俄惊残。","故人在何处，远隔烟水村。","攲枕不复见，伤心涕汍澜。"]},{"t":"县学落成百韵","f":"五言古诗","c":["炎正中微后，皇家再造年。","斯文天未丧，吾道圣相传。","黼扆端周冕，岩廊拱舜弦。","宸章丽朝日，奎画焕中天。","贾马朝丹阙，皇夔捧御筵。","云龙庆相遇，星凤快争先。","金马袍披锦，戎亭帐褫毡。","崇儒符汉武，复古慕周宣。","方议成均制，仍增博士员。","伫观旂茷茷，行贲帛戋戋。","词赋扬群彦，贤良策万全。","圜桥汉亿万，鼓箧鲁三千。","狂客休歌凤，骚人肯钓鳊。","文风畅蛮貊，士气压腥膻。","王化诚无外，吾邦素自偏。","鱼盐人竞习，刀笔世相沿。","甘学樊迟稼，纷求许汜田。","揶揄戏缝掖，膜呗奉真诠。","未振寒乡陋，那经杀气缠。","闾阎森白刃，庠序燎寒烟。","断简嗟何考，青衿痛自怜。","诗存伤瓠叶，礼废忆豚肩。","磬碎交州石，弓焚矍相弦。","水流空涣涣，草碧自芊芊。","有识思兴起，无知分弃捐。","桑弧谁复射，城阙孰思还。","弟子贫原宪，先生冷郑虔。","嗣音几泯灭，素业遂迍邅。","屡应三年诏，曾微万选钱。","龙门无几到，虎榜不多联。","愈赋徒伤感，郊肠厌炒煎。","儒冠空叹误，铁砚莫知研。","白日非偏照，寒灰自不然。","百年嗟委靡，今日幸夤缘。","令尹真人杰，同僚命世贤。","崔丞老文学，梅尉旧神仙。","乐善诚何笃，承流志更专。","下车伤弊俗，修泮慕遗编。","浮议畴能夺，良谋断不愆。","商财方萃聚，卜日肯迁延。","役命诸生董，基谋爽垲迁。","邓林搜蓊郁，淇竹剪婵娟。","秘殿雄千尺，脩廊跨百廛。","虹梁挂天宇，云栋轶星躔。","缥缥飞鸳瓦，沉沉耀采椽。","沚茂春色早，坛杏午阴圆。","方沼分寒溜，明窗瞰碧涟。","前山昂马首，胜地夺龙眠。","瀑水灵源近，箫峰秀色妍。","规模何廓廓，气象更绵绵。","先圣风流远，新宫象貌鲜。","森罗龙衮列，肃穆雁行连。","剑佩星辰上，丹青日月边。","衣裳明黼黻，冠冕饰纮綖。","祀事脩崇报，心斋务至蠲。","新仪仍再习，吉日已重涓。","漏箭催庭燎，鸾刀待饩牵。","充庭端弁服，夹道拥车骈。","秉笏趍帷幄，升阶省豆笾。","馨香登黍稷，肥腯荐牲牷。","蔬撷罗芹藻，鱼羞备薧鲜。","牺尊澄玉液，宝篆喷龙涎。","荐裸仍更貌，观瞻竞曲拳。","礼文稽戴郑，乐舞奏韶卷。","设礼筵初秩，登门屦已填。","盍簪联桂玉，纫佩杂兰荃。","饰喜捐丝竹，论文具管笺。","献酬咸偻伛，进退各周旋。","挥麈谈飞屑，濡毫思涌泉。","妙词歌郢客，醉墨洒张颠。","共喜从于迈，俱忘咏式遄。","武纷堂上接，衣拥坐隅褰。","父鄙金籯满，师誇腹笥便。","雩风开性柳，教雨长材楩。","鼓瑟求曾点，攀鳞至闵骞。","水平翻振鹭，天阔戾飞鸢。","莺思友迁木，骅群尽著鞭。","草空收七壁，雀过堕三鳣。","道也将行矣，辰乎盍勉旃。","搜寻罗简札，点勘费丹铅。","洁净穷爻象，温柔考注笺。","典谟稽古学，仓制究残编。","异教排韩子，遗绖抱玉川。","壮夫羞篆刻，童子悟幽玄。","道德勤钻仰，文章变俨骈。","科名真溷尔，翰墨盖游焉。","雪耻终兴越，成功必霸燕。","真成两阙里，别是一陶甄。","化出文翁表，功居范宁前。","声莘终不朽，琬琰岂须镌。","未学成鸠拙，穷居类兔跧。","肠枯无锦绣，门冷乏貂蝉。","箪食虽云乐，藜床已厌穿。","室空司马壁，食窘鲁公饘。","误拜殽陵赐，长怀渭水畋。","断弦音寂寞，抱玉涕潺湲。","览镜时犹在，焚舟志益坚。","燕归欣遇厦，鱼得敢忘筌。","愿赴功名会，终归造化权。","唯凭大炉火，早晚铸颜渊。"]},{"t":"送刘方叔季文游雁山","f":"七言律诗","c":["二客骚肠不耐秋，飘然蜡屐去寻幽。","荡中若要穷青眼，岩下先须问白头。","诗社不容添异姓，名山应岂遇清流。","会须乘兴天台去，涧水桃花访旧游。"]},{"t":"游西岑遇雨","f":"七言古诗","c":["西岑风物秋更嘉，杖藜出郭欢无涯。","深村有酒隔烟渚，共乘小艇穿芦花。","罗裙绰约越溪女，茅舍迫窄吴侬家。","床头新酿喜正熟，千金倒瓮倾流霞。","天公妒我一日乐，俄然雨脚来如麻。","醉归扶路泥没股，冠巾不整头鬖髿。","人生贵在适意耳，安能局缩身如蜗。","杖头有钱即相觅，明日更泛仙源槎。"]},{"t":"幽居三咏 其一 脩竹","f":"七言律诗","c":["我得家传好此君，剩栽干挺拂青云。","尘埃不扫自然去，风月有馀谁可分。","万箨苍龙春后见，满轩鸣玉夜深闻。","时时助我毫端兴，宜与江山共策勋。"]},{"t":"幽居三咏 其二 黄杨","f":"七言律诗","c":["兵火回头二十年，吾家此树实青毡。","儿时尚及见封植，乱后那知独保全。","虽荷生成能蓊郁，不轻剪拂岂团圆。","主翁不忍加斤斧，旧物于人最可怜。"]},{"t":"幽居三咏 其三 丁香花","f":"七言古诗","c":["玄冬万木落如扫，苦恨江梅开不早。","谁言菊后便无花，更有丁香慰枯槁。","雨膏碧叶剪琉璃，风荐幽葩喷龙脑。","小轩深院夜凄清，月白霜寒天色好。","素面含情宋玉愁，仙肌带湿真妃澡。","何人为取药中名，端为花能除病恼。","我时独步琼枝边，相向无言意倾倒。","临风三嗅更徘徊，研墨为花加品藻。"]},{"t":"郑丞生日 其一","f":"七言律诗","c":["九日人间气象新，郑公家诞少康成。","玉山肌骨侵人瑩，秋水精神照坐明。","奕世簪缨真烜赫，冲天头角正峥嵘。","愿公此日身长健，醉把茱萸泛寿觥。"]},{"t":"郑丞生日 其二","f":"七言律诗","c":["贤关当日厕英游，意气轩轩压辈流。","心授广文真翰墨，家传北海旧春秋。","棠阴惠爱留三邑，莲幕声名重一州。","宾客盈门望推毂，蓝田松竹可能留。"]},{"t":"县学别同舍","f":"七言律诗","c":["萧瑟秋声起桂枝，登临谁赋送将归。","伴人灯火情犹在，过眼烟云事已非。","记取齑盐同冷落，忍教襟袂遽分违。","明朝一笑江山隔，望断日边鸿雁飞。"]},{"t":"次韵曾尉易任青田留别","f":"七言律诗","c":["梅仙乐教意尤勤，绛帐煎膏至夜分。","心学尽传隋董薛，词章高压汉卿云。","谁知有力能攘我，不许诸生久借君。","驷马重来定何日，好看双挂散清芬。"]},{"t":"淫雨","f":"七言律诗","c":["春雨无端苦浸淫，满天飞雾日光沉。","出门蒸润濡衣重，归路泥涂没股深。","欲与阳乌开烈艳，试呼风伯扫烦阴。","明朝会见佳天气，只恐春归无处寻。"]},{"t":"仰先生挽词","f":"七言律诗","c":["诸生衮衮登科第，造物苦公深可怜。","身到蟾宫都几日，名书鬼录已经年。","数同子厚无如命，才似韩公合在天。","慎水诸生哭相向，筑场无计愧前贤。"]},{"t":"寄潘先生","f":"七言律诗","c":["萧疏鬓发老安仁，才出人头未免贫。","书剑一生长肮脏，齑盐到处只酸辛。","招提夜永眠无室，绛帐春寒坐乏茵。","莫怪闇梨不具眼，先生未见宰官身。"]},{"t":"次韵潘先生莫春感怀见寄","f":"七言律诗","c":["缅想长安觉夜长，先生投老困文场。","几吟白雪眠萧寺，谁荐凌云达未央。","鼠目獐头多富贵，兔葵燕麦自悲伤。","感春情思如云乱，排闷题诗寄草堂。"]},{"t":"至乐斋读书","f":"五言律诗","c":["权门迹不到，颜巷自安贫。","独与圣贤对，更于灯火亲。","夜观常及子，昼讽直从寅。","莫恨成名晚，诗书不负人。"]},{"t":"用前韵酬昌龄弟","f":"五言律诗","c":["原宪曾非病，陈平岂久贫。","路遥骐骥困，原近鹡鸰亲。","窗几坐穷夕，更筹听报寅。","田园劳尔辈，愧是素餐人。"]},{"t":"怀孙子尚","f":"七言律诗","c":["孙郎何事久无书，又见青春柳拂渠。","千里阻山仍阻水，三年无雁亦无鱼。","弟兄官况宁多好，囊橐年来莫久虚。","海角天涯两形影，别时长记涕涟如。"]},{"t":"怀姜渭叟兼简谢守中用前韵","f":"七言律诗","c":["姜郎何事久无书，令君青春最忆渠。","别后又孤诗与酒，怪来都断雁并鱼。","守株身世俱非巧，画饼声名总是虚。","隔壁惠连无恙否，池塘春草句何如。"]},{"t":"怀刘方叔兼简全之用前韵","f":"七言律诗","c":["刘郎何事久无书，梦里频频却见渠。","往事真同塞翁马，此身何异蠹书鱼。","严亲白发皆如许，吾辈青春度莫虚。","意气飘飘羡温叟，凌云词赋压相如。"]},{"t":"述怀","f":"七言律诗","c":["吾年三十百无堪，世事如麻总未谙。","杨子家贫那嗜酒，卢仝丁白更添男。","回头场屋心几折，混迹泥涂分固甘。","赖有东皋遗业在，剩栽桑柘教妻蚕。"]},{"t":"送元范赴省","f":"七言律诗","c":["清峭霜天振羽翰，共观一鹗气轩轩。","愿将拄腹书千卷，尽作忧时策万言。","请系单于同太傅，不阿人主异公孙。","龙头素是君家物，又见传呼贾状元。"]},{"t":"送刘政孙","f":"七言律诗","c":["蚤岁声蜚舍法中，漕台前日始收功。","辛勤半世齑盐学，慷慨平生畎亩忠。","作佛肯居灵运后，登仙更与阮郎同。","琼林宴罢游天禄，太一然藜定照公。"]},{"t":"送刘全之","f":"七言律诗","c":["綵衣堂上别慈颜，匹马扬鞭指帝关。","千里清风生腋下，十分黄气满眉间。","手探春信寻梅去，袖带天香折桂还。","定向蓬莱燕仙侣，为言子晋在江山。"]},{"t":"前诗送三乡文行虽各献芹然非所以勉子大夫茂明大对之意更为古诗一章","f":"词","c":["逆胡残喘仍跳梁，中兴事业犹渺茫。","当今取士异平日，非为故事开科场。","庙堂方讳口打贼，翻抵正论为猖狂。","纷纷儿辈苟富贵，妄引申伯深阿王。","公孙老儒亦曲学，不敢正色言尧汤。","徒令天下慷慨士，肝胆一剑生光芒。","前年胡公以言逐，言今已验官未复。","近日径山缘赋诗，裹头衣白投荒服。","忠良自此多结舌，道路相看徒以目。","谁能言事如靖康，陈东已死欧阳戮。","国家养士恩至渥，千戈不废菁莪育。","诸公报国当如何，莫把刚肠慕粱肉。","丈夫一第何足道，幸勿以此存怀抱。","贾生当献太息流涕痛哭书，更施三表五饵请为属国系单于。","大刘小刘展尽畎亩惓惓忠，弘恭石显辈视之当与奴仆同。"]},{"t":"次韵潘先生寒食有感 其一","f":"七言绝句","c":["花媚韶光柳弄烟，箫声处处卖饧天。","谁知子厚怀桑梓，北望长号又一年。"]},{"t":"次韵潘先生寒食有感 其二","f":"七言绝句","c":["无赖杨花趁暖风，旅中节物与愁逢。","一声杜宇啼春怨，知在花梢第几重。"]},{"t":"次韵潘先生寒食有感 其三","f":"七言绝句","c":["人间寒食几经年，甲子谁能记后先。","且尽一杯蓝尾酒，莫将身事恼生前。"]},{"t":"悼僧德芬 其一","f":"七言律诗","c":["身著方袍十一年，缁林头角稍轩轩。","参禅早悟前三旨，学道思归不二门。","花落絮飞浮世尽，风清月白片心存。","异时我作高僧传，为记严公有此孙。"]},{"t":"悼僧德芬 其二","f":"七言律诗","c":["妙龄萧洒脱尘笼，高揖禅林话苦空。","万水千山新道眼，一瓶二钵旧家风。","圆镜肇论能知趣，笔法诗章稍自工。","圆泽精魂定何所，想随流水到天童。"]},{"t":"悼禅法师","f":"七言律诗","c":["阁中高隐岁华深，龟鹤精神老不侵。","宝剑妙传驱鬼术，灵丹长有济人心。","弥明石鼎方联句，弘景袈裟遽掩衾。","借问青牛何处去，九天云路杳难寻。"]},{"t":"毛虞卿见过","f":"五言古诗","c":["故人访吾庐，况是清和节。","高槐绿成阴，芳草碧未歇。","携手山间行，清兴浩然发。","呼童具鸡黍，浊酒醅初泼。","贫居愧荒凉，野蔌草罗列。","盘实饤梅豆，蔬餐荐薇蕨。","主礼虽甚微，客色未尝觖。","醉翁山水意，不为壶觞设。","蟹眼煎新汲，雀舌烹春撷。","浇君文字肠，掉我清谈舌。","人生会面难，岁月易飘忽。","君姑为我留，匆匆莫言别。"]},{"t":"读孙子尚旧所寄书","f":"七言古诗","c":["故人之书不易得，片纸只字皆可惜。","收拾永为巾笥藏，纵得千金不愿易。","开缄展转时一读，读未能终泪横臆。","之人门地盛衣冠，万里家居帝王宅。","干戈缭绕飘吾乡，倾盖论交似畴昔。","我年初冠君犹少，握手游从忝联璧。","金溪风月供醉吟，君唱我酬常即席。","君诗句句清且新，高压曹刘倒元白。","我才短浅何足论，彊伴宁容小生敌。","追风骏足横海鳞，暂困盐车与污泽。","掉头一去不可寻，南北茫茫烟水隔。","往年雁字时复传，近日诗筒杳难觅。","眼中不见故人面，纸上空怀故人迹。","人生会合能几回，一别八年同瞬息。","我去无由君不来，尊酒相逢更何夕。"]},{"t":"宋彦才挽词","f":"七言律诗","c":["德著吾乡月旦评，丘园萧散傲虚名。","袍虽不夺诗尤好，秋不曾悲赋自清。","早挂儒冠知有命，晚凭贝叶悟无生。","人间月落天池后，定向维摩顶上行。"]},{"t":"宋孺人挽词","f":"七言律诗","c":["晚岁归来奉伯鸾，力将勤俭济艰难。","鹿车共挽甘从鲍，熊胆亲调欲慕韩。","镜里玉容犹未老，梦中银漏忽惊残。","通家贱子非房杜，长记登门酒尽欢。"]},{"t":"先君子去世五十日孤某入四友室睹平生遗迹哀号痛哭绝而复苏既而书四十字以寄罔极之思","f":"五言律诗","c":["先子神何在，人亡迹尚存。","业馀经史案，趣寄圣贤尊。","榻冷宁攲枕，堂虚已盖棺。","晨昏徒泣血，无路报深恩。"]},{"t":"李府君挽词","f":"七言律诗","c":["利涂名路两崎嵚，甘向田园事陆沉。","一顷膏腴生计足，四时香火佛缘深。","筑门东海于公意，教子燕山窦老心。","衔涕为公铭隐德，不缘谀墓欲黄金。"]},{"t":"陈景公挽词 其一","f":"七言律诗","c":["冠玉堂堂骨相奇，起家消息露蓍龟。","齿牙不妄千金诺，度量难窥万顷陂。","车辙过门多长者，箕裘传业有佳儿。","西园新卜松楸地，记得公颜向此怡。"]},{"t":"陈景公挽词 其二","f":"七言律诗","c":["先子于公分颇深，晚年出处恨商参。","虽脩北海通家好，未遂香山会老心。","尽道吉人俱未艾，谁知凶讣遽相寻。","三年落尽思亲泪，今日登门又满襟。"]},{"t":"次韵万乔年李唐英二绝 其一","f":"七言绝句","c":["七贤林下共忘机，更有新诗为发挥。","竹叶一尊添逸兴，薰风吹散脸红微。"]},{"t":"次韵万乔年李唐英二绝 其二","f":"七言绝句","c":["黉舍炎炎畏日长，竹亭取次纳新凉。","文章风月须兼美，莫使时人恨海棠。"]},{"t":"送章生端武","f":"七言古诗","c":["麟经绝笔今几年，学者异说何纷然。","操矛入室务相伐，谁能浚井得美泉。","梅溪野人独好古，遗经独抱期心传。","从予讲论有赵陆，得趣往往忘蹄筌。","章生妙龄固可畏，圣经贤传思穷研。","赢粮远来若有意，席未及暖俄言还。","岂厌先生纸上语，奥境不见徒留连。","春秋明日遂东矣，情钟我辈徒拳拳。"]},{"t":"送罗生少陆","f":"五言古诗","c":["罗生黄山来，从我梅溪游。","齿发最年少，学问能自修。","短檠照深夜，细字书蝇头。","大业心欲潜，遗编力旁搜。","新文有佳趣，日进殊未休。","吾愧河汾翁，子学常与收。","行将拭老眼，万里看骅骝。","一叶下庭皋，大火当西流。","遥望河阳云，俄登李膺舟。","交朋重惜别，挽袖终不留。","吾肠百鍊刚，亦作茧绪抽。","籍也不吾叛，寻盟定高秋。"]},{"t":"送茹生履","f":"七言绝句","c":["灯火勤劳觉瘦生，望云心断涕从横。","贤关春信无多日，手折梅花赠子行。"]},{"t":"乙丑冬罢会呈诸友","f":"五言律诗","c":["缪意开家塾，微才愧斗筲。","虽逃有若叱，宁兑孝先嘲。","尚赖知心友，能全耐久交。","殷勤惜别意，终日在梅梢。"]},{"t":"江上遇风二绝 其一","f":"七言绝句","c":["薄暮登舟海飓生，短篷攲侧浪峥嵘。","江神正好怜行客，莫待他时却世情。"]},{"t":"江上遇风二绝 其二","f":"七言绝句","c":["弭棹乾门浪未平，同舟太半已山行。","自惭不是娄师德，免葬江鱼赖友生。"]},{"t":"宿黄岩妙智院","f":"五言律诗","c":["问讯开山始，于今二百年。","径幽微见竹，社废尚遗莲。","观颂思元老，游庵忆旧禅。","匆匆一宿客，未尽涤尘缘。"]},{"t":"过黄岩","f":"五言律诗","c":["三日离家客，悠然觉路长。","梅花十里眼，竹叶一杯肠。","诗思贪佳境，眉头忆故乡。","江山看未足，回首隔沧浪。"]},{"t":"宿庆善寺","f":"五言律诗","c":["刚被篙工误，迟留一日装。","川涂隔浩渺，灯火乱昏黄。","呼仆回行李，寻僧宿上方。","山前十里雪，夜入梦魂香。"]},{"t":"过天台","f":"五言律诗","c":["目逆神仙路，丹成未暇跻。","雪深封佛垄，云暗锁桃溪。","流水无还有，乱山高复低。","欲寻刘阮洞，归路恐成迷。"]},{"t":"过新昌","f":"五言律诗","c":["杖屦登关岭，山行无住时。","客情浑在眼，乡思苦关眉。","石现金仙像，溪蟠阮肇祠。","越山都几点，收拾上新诗。"]},{"t":"观石佛","f":"七言绝句","c":["土木涂金巧逼真，总随浮幻化埃尘。","何人著意镌山骨，长现金刚不坏身。"]},{"t":"戴溪亭","f":"七言绝句","c":["高士逃名隐此溪，凭栏遐想独徘徊。","不知吾祖乘舟后，得得谁从雪里来。"]},{"t":"曹娥庙","f":"五言律诗","c":["恸哭无寻处，投江竟得尸。","风高烈女传，名重外孙碑。","荒草没孤冢，洪涛舂古祠。","怀沙为谁死，翻愧是男儿。"]},{"t":"宿驿奥","f":"五言绝句","c":["未是他乡客，思家已断魂。","明朝春色好，宿处近花村。"]},{"t":"题灵峰三绝 其一","f":"七言绝句","c":["家在梅溪水竹间，穿云蜡屐可曾闲。","雁山新入春游眼，却笑平生未见山。"]},{"t":"题灵峰三绝 其二","f":"七言绝句","c":["洞中大士半千身，住世端能了世因。","应笑玉箫峰下客，马蹄长践利名尘。"]},{"t":"题灵峰三绝 其三","f":"七言绝句","c":["三宿灵峰不为禅，茶瓯随分结僧缘。","明朝杖屦丹丘去，带得烟霞过海船。"]},{"t":"出雁山","f":"七言绝句","c":["三宿山中始出山，出山心尚在山间。","浮名夺我林泉趣，不及高僧一味闲。"]},{"t":"关岭遇雪","f":"七言绝句","c":["路近剡溪春雪深，此行有愧子猷寻。","驱驰千里争蜗角，孤负扁舟自在心。"]},{"t":"过鉴湖 其一","f":"七言绝句","c":["谁把青铜铸鉴湖，湖光冷浸越王都。","东风二月西游客，买得扁舟入画图。"]},{"t":"过鉴湖 其二","f":"七言绝句","c":["春水如天浪未生，扁舟真在鉴中行。","渔人不问君王觅，占得湖光亦自荣。"]},{"t":"月夜独酌","f":"七言绝句","c":["月色撩人不忍眠，杖头独挂百青钱。","一杯竹叶那能醉，浇起乡心更黯然。"]},{"t":"太学寄梦龄昌龄弟","f":"七言律诗","c":["东望家山几断魂，白云飞尽路漫漫。","须知太学齑盐味，不似亲闱菽水欢。","事业未应孤铁砚，弟兄犹喜尽儒冠。","行飞直待秋风便，好作排空雁字看。"]},{"t":"丁卯秋赴鹿鸣宴次太守赵殿撰韵","f":"七言律诗","c":["食苹开燕副招求，梦草诗成宠士流。","要得异才联虎榜，亦容下客盗狐裘。","早脩慧业钦灵运，妄赞元经愧子游。","刺史笑谈风满席，定应吹拂到瀛洲。"]},{"t":"赴省治装有感","f":"七言绝句","c":["记得离家柳未黄，归来三径菊花香。","一年强半身为客，席未遑安又趣装。"]},{"t":"再过雁山三绝 其一 大龙湫","f":"七言绝句","c":["龙大那容在此湫，银河得得为飞流。","好乘风雨昂头角，直到天池最上头。"]},{"t":"再过雁山三绝 其二 天柱峰","f":"七言绝句","c":["女蜗石烂若为脩，四海咸怀杞国忧。","谁识山中真柱石，擎天功业胜伊周。"]},{"t":"再过雁山三绝 其三 天聪洞","f":"七言绝句","c":["重华疑到此山中，凿石疏岩达四聪。","端为草茅忧世士，不教无路献孤忠。"]},{"t":"思归","f":"七言绝句","c":["窗外西风竹数竿，秋声终夜趣归鞍。","吾庐此去八百里，归到家时天未寒。"]},{"t":"别太学同舍","f":"五言古诗","c":["二年客贤关，倾盖皆故人。","况我同舍郎，何异手足亲。","齑盐共牢落，灯火同悲辛。","坐觉岁月忘，所赖朋友仁。","西风起天末，淅沥吹江蘋。","思归适所愿，惜别还沾巾。","祖席歌骊驹，别肠转车轮。","离索恐孤陋，重来约新春。"]},{"t":"戊辰闰八月归临安观旧题脩竹黄杨丁香慨然有感复书三绝于后 其一","f":"七言绝句","c":["吾家风物富檀栾，最爱青青耐岁寒。","千里归来面苍玉，不烦时复报平安。"]},{"t":"戊辰闰八月归临安观旧题脩竹黄杨丁香慨然有感复书三绝于后 其二","f":"七言绝句","c":["同日种松今合抱，后来栽柳已参天。","笑看轩外黄杨树，我亦如君厄闰年。"]},{"t":"戊辰闰八月归临安观旧题脩竹黄杨丁香慨然有感复书三绝于后 其三","f":"七言绝句","c":["蕙兰憔悴菊萎秋，叶底藏春已数头。","诗客不知花韵别，却言空结雨中愁。"]},{"t":"次韵宝印叔题止庵三绝 其一","f":"七言绝句","c":["凿石依山作小庵，花香入座月侵檐。","虽然眼界无多地，解使人天竞耸瞻。"]},{"t":"次韵宝印叔题止庵三绝 其二","f":"七言绝句","c":["容膝茅庵不妄开，欲令人悟止由来。","个中妙意知谁解，多作休休莫莫猜。"]},{"t":"次韵宝印叔题止庵三绝 其三","f":"七言绝句","c":["晚学无由识道真，前贤未许继芳尘。","道从何进从何止，敢叩无为绝学人。"]},{"t":"翁府君挽词","f":"七言律诗","c":["场屋收功不在身，兰馨玉润总奇人。","过庭诗礼家风变，坦腹门阑喜气新。","华屋产芝虽美瑞，白头生齿误青春。","篮舆方起南游兴，无奈今年岁在辰。"]},{"t":"十月十九日雷二十一日雪","f":"七言绝句","c":["前日始惊雷失令，今朝忽见雪漫天。","寒窗夜拥黄紬坐，闲读春秋隐九年。"]},{"t":"次韵表叔余叔成示儿","f":"五言古诗","c":["父子乃天性，钟情谁不然。","教之以义方，先贤有名言。","日严在所尚，私念宜舍旃。","君子不自教，遣随师友肩。","青紫乃馀事，要当知圣贤。","居家务孝弟，立行防悔愆。","穷当慕颜回，达勿为公孙。","庶几幼所学，终身可行焉。","不见下邳丈，秀发从妙年。","束书入贤关，日与英隽联。","忽作何蕃归，甘旨奉晨昏。","丘园事高尚，腹笥常便便。","过庭有奇儿，诗礼得家传。","勉哉尊所闻，慎勿学乡原。"]},{"t":"表叔陈景韶挽词 其一","f":"五言律诗","c":["问舍求田事，元龙意本轻。","功名孤壮志，诗酒送平生。","李密伤为弟，刘牢喜有甥。","诗书已三世，二子盍升卿。"]},{"t":"表叔陈景韶挽词 其二","f":"五言律诗","c":["先友嗟无几，公今亦古人。","平门散车辙，蕃榻锁埃尘。","甚愧常公厚，深知管子贫。","平生谈笑地，感激泪沾巾。"]},{"t":"咏述师葡萄","f":"七言绝句","c":["柱杖拈馀戏插泥，草龙珠帐挂檐西。","荔枝体物差胜枣，毕竟俱非善品题。"]},{"t":"十一月七日东山省坟因思先子昔年题壁有山光水色两依依之句，旧屋已坏墨迹不留山水依然感叹不已因成一绝","f":"七言绝句","c":["松楸一见一伤心，亭院凄凉惨树阴。","记得先君旧题壁，水光山色恨难禁。"]},{"t":"寄万大年","f":"七言律诗","c":["九万程遥共退飞，江南竹叶后先归。","儒冠到底输纨裤，关吏还应笑布衣。","虽欠姓名联桂籍，不妨欢笑奉亲闱。","殷勤尊酒论文约，却恨还乡与愿违。"]},{"t":"万季梁和诗留别再用前韵","f":"七言律诗","c":["三年燕雁不同飞，一笑相逢慰远归。","搜我肺肠茶著令，饮君文字酒淋衣。","诗方唱和如仙馆，人遽飘零似省闱。","毕竟此心元不别，祇应形影暂相违。"]},{"t":"将过万桥用前韵寄大年先之","f":"七言律诗","c":["三年在阜不鸣飞，侧翅俱从旧路归。","师德量宽真耐事，沈郎诗瘦不胜衣。","都缘有职供甘旨，可是无心恋阙闱。","酒发葡萄螯斫雪，定知此愿不吾违。"]},{"t":"种兰有感","f":"五言律诗","c":["芝友产岩壑，无人花自芳。","苗分郑七穆，秀发谢诸郎。","世竞怜春色，人谁赏国香。","自全幽静操，不采亦何伤。"]},{"t":"再用前韵","f":"五言律诗","c":["谁棹深林秀，遥分奕叶芳。","秉殊溱上客，握拟殿中郎。","眼净见幽韵，心清闻远香。","当门不及种，践履恐成伤。"]},{"t":"三月晦日与同舍送春于梅溪因诵贾阆仙诗云三月更当三十日，风光别我苦吟身共君今夜不须睡未到晓钟犹是春时有二十八人遂以齿序分韵","f":"七言律诗","c":["记得来时手自探，预知今日思难堪。","树头绿暗莺如诉，地上红多蝶尚贪。","此夜钟声那忍听，明朝酒盏可能酣。","却因送别还惊我，老境如蚕已食三。"]},{"t":"为麦祈实","f":"五言古诗","c":["阳律临姑洗，宸心念岁饥。","时羞方庙献，麦实为民祈。","日煖轻花吐，风和翠浪微。","敢言因鲔荐，愿勿作蛾飞。","会续来牟颂，宁闻告籴讥。","崆峒今岁熟，登荐定无违。"]},{"t":"次韵万先之读庄子","f":"五言古诗","c":["庄生蔽于天，先儒已能言。","六经有真味，奚用食马肝。","王何佐其高，遗害今犹存。","夫君高明士，寄趣名理间。","恐蹈贤者过，因诗与君论。"]},{"t":"己巳梅溪同舍三十人其九人者游从之旧也酌别之夕独五人在焉谢子与能犹在予馆而四人者且去矣遂各以其姓赋诗送之 周仲翔","f":"五言律诗","c":["梅溪辟家塾，辱与英俊游。","回首五年旧，子独终始周。","善交固耐久，厚德堪镇浮。","异时行所蕴，无愧祖绛侯。"]},{"t":"己巳梅溪同舍三十人其九人者游从之旧也酌别之夕独五人在焉谢子与能犹在予馆而四人者且去矣遂各以其姓赋诗送之 李大鼎","f":"五言律诗","c":["贤哉予外兄，厚德著乡里。","积善有天报，钟秀在吾子。","学问如驰马，著鞭殊未已。","西游不负盟，早早戒行李。"]},{"t":"己巳梅溪同舍三十人其九人者游从之旧也酌别之夕独五人在焉谢子与能犹在予馆而四人者且去矣遂各以其姓赋诗送之 许辉先","f":"五言律诗","c":["子昔从予游，方读纸上语。","磨砻出圭角，剪拂就规矩。","不为中道废，当振大岳许。","行将拭老眼，看子惊人举。"]},{"t":"己巳梅溪同舍三十人其九人者游从之旧也酌别之夕独五人在焉谢子与能犹在予馆而四人者且去矣遂各以其姓赋诗送之 谢鹏","f":"五言律诗","c":["之子方妙龄，耻为聋俗化。","三年游梅溪，灯火读深夜。","男儿四方志，万里思高跨。","愿如芝与兰，毋愧古诸谢。"]},{"t":"别宋孝先","f":"五言古诗","c":["楚台风骚客，遥遥有奇孙。","去岁始识面，未遑叩渊源。","但见眉宇间，一点阳春温。","琴书忽来游，文字获细论。","经术有根蒂，词章富波澜。","时时戏翰墨，动辄千万言。","子固予所畏，语蒙子推尊。","予尝语所学，文当气为先。","气治古可到，何止科第间。","子贤且乐善，服膺每拳拳。","临行出新诗，殷勤记诸篇。","好学见雅志，予言未应然。","惜哉有离别，后会何夤缘。","男儿各自勉，事业无穷年。"]},{"t":"送黄岩三友","f":"五言律诗","c":["聚散本常理，未应轻感伤。","祇因三益友，故断九回肠。","子少才俱美，予穷老更忙。","相将亦行客，后会恐参商。"]},{"t":"又各赠一绝 余如晦","f":"七言绝句","c":["遥遥华胄自由余，识量深沉岂浅夫。","半载从游殊半面，临行一语可能无。"]},{"t":"又各赠一绝 郑逊志","f":"七言绝句","c":["灯火相亲臭味同，来何太晚去匆匆。","未曾箴我膏肓失，堪叹康成道已东。"]},{"t":"又各赠一绝 施良臣","f":"七言绝句","c":["学传士丐旧家声，诗法肩吾句已成。","尊酒论文两经岁，却因送别倍钟情。"]},{"t":"别余谐","f":"五言律诗","c":["我昔自总角，识君先大夫。","闺门脩子职，乡里号名儒。","仁者偶不寿，善人宜有孤。","肯堂能自勉，泉下慰榛芜。"]},{"t":"别余壁","f":"五言律诗","c":["之子有家学，妙龄殊众儿。","参乎宜语孝，鲤也早闻诗。","谩习雕虫技，终絺吐凤词。","五车书读尽，定有起家期。"]},{"t":"别周浚","f":"七言绝句","c":["莫恨知书失太迟，妙龄聪子本非奇。","好因椎鲁加鞭策，会见火然泉达时。"]},{"t":"后七夕二夜同梦龄宿湖边庄 其一","f":"七言绝句","c":["无用乾坤一腐儒，年来踪迹转崎岖。","身名未就耕桑废，何日投闲老此湖。"]},{"t":"后七夕二夜同梦龄宿湖边庄 其二","f":"七言绝句","c":["弟兄身事各茫然，赖有先人二顷田。","他日青山映黄发，长如今夜对床眠。"]},{"t":"次夜予宿湖南梦龄犹在别业再和前韵寄之 其一","f":"七言绝句","c":["家世衣冠误袭儒，年几四十尚嵚岖。","营营世事何时了，乞取湖边作鉴湖。"]},{"t":"次夜予宿湖南梦龄犹在别业再和前韵寄之 其二","f":"七言绝句","c":["一襟秋色已凄然，云水初空眼界田。","那更萧萧风雨夜，弟兄分影隔湖眠。"]},{"t":"宿灵山院","f":"七言绝句","c":["灵山未是别乡山，回首吾庐咫尺间。","明日出山家渐远，乡心从此上愁颜。"]},{"t":"登姚奥岭望家山有感","f":"五言绝句","c":["已作一宿客，渐为千里人。","吾亲白云下，回首一沾巾。"]},{"t":"与万先之登丹芳岭路人有手持桂花者戏觅之概然相赠且言欲施此花久矣又言花名秋香一名十里香遂与先之分之记以一绝","f":"七言绝句","c":["携手丹梯语话长，不知身到碧云乡。","行人相见如相识，赠得岩花十里香。"]},{"t":"题石梁","f":"七言绝句","c":["荡中天柱见已久，山外石梁今始观。","尊者力能回造化，会须移向柱头安。"]},{"t":"过雁山","f":"七言绝句","c":["清秋天气过山中，征雁行人路不同。","从此又劳千里翼，传书来往浙西东。"]},{"t":"次先之过雁山韵","f":"七言绝句","c":["云山缭绕几千重，撩我秋来逸兴浓。","欲向灵岩移卓笔，与君同扫万人锋。"]},{"t":"张施二生自黄岩拿舟送别于台城赠以二绝 其一","f":"七言绝句","c":["不放离人独解舟，片帆相逐到丹丘。","客情乡思从今日，更有思君一段愁。"]},{"t":"张施二生自黄岩拿舟送别于台城赠以二绝 其二","f":"七言绝句","c":["行役那堪八月时，肠非宋玉也应悲。","烦君为寄梅溪信，少慰吾亲别后思。"]},{"t":"过仙人渡","f":"七言绝句","c":["此去神仙路不迷，直从洞口到桃溪。","仙人心境无名利，笑我频年渡此溪。"]},{"t":"过百度岭","f":"七言绝句","c":["乘舟刚怕两难恶，度岭俄惊百步高。","僮仆相看话良苦，纵教轻担亦疲劳。"]},{"t":"关岭旅邸观林同季野去秋题壁","f":"七言绝句","c":["去岁还家秋正杪，今年行役暑初残。","同行壁上留题处，特下篮舆子细看。"]},{"t":"望天台赤城山感而有作","f":"七言古诗","c":["神仙境界无战争，奚用漆此巍巍城。","吾闻秦皇昔多欲，富贵已极贪长生。","蓬莱方丈欲亲到，车辙马迹无时停。","万骑南巡适吴越，天台咫尺行将登。","仙山不容肉眼见，天为设险藏神灵。","山中采药使未返，鲍鱼向已沙丘腥。","秦为防胡筑紫塞，连年不恤生灵害。","天亦防秦甚防胡，赤城高峙烟霞外。","神仙要非求可得，祖龙可笑徒劳役。","当时刘阮本无心，花笑水迎山自辟。","我向丹丘数往来，群仙杖舄未容陪。","挥毫欲续孙公赋，愧无掷地金声才。","目极苍崖千万丈，世无仙骨那能上。","直须内外两丹成，驾鹤骖鸾如指掌。"]},{"t":"柘溪道傍有班竹百馀挺萧洒可爱与先之赏玩移时因念乡间无是种约异日移其根予戏诵君看江上千竿竹不是男儿泪点班之句遂发一笑既而作数语解异世妇人之嘲且志不必移根也","f":"七言律诗","c":["男儿有泪不染竹，当作包胥贾生哭。","湘源遗种虽可爱，节目尚馀儿女态。","谁能千里移此根，出门又恐添啼痕。","不如还家种慈竹，不厌千竿万竿绿。"]},{"t":"代妇人答","f":"七言律诗","c":["君勿题诗訾湘竹，君勿笑他儿女哭。","人为钟情故生爱，夫妇相思乃常态。","为君飘荡太无根，两脸尽是思君痕。","安得相依似双竹，长保千秋万秋绿。"]},{"t":"题刘阮祠用过仙人渡韵","f":"七言绝句","c":["涧水桃花路易迷，不同人世下成蹊。","自从重入山中去，烟雨深深锁旧溪。"]},{"t":"至剡溪寄梦龄昌龄","f":"五言律诗","c":["歉岁为行客，清秋别故园。","自从离雁荡，长是念鸰原。","世路疲来往，亲闱废凊温。","缄书付归仆，销尽旅中魂。"]},{"t":"剡溪舟中有感","f":"五言律诗","c":["又作游吴客，重登入越船。","西风桑叶岸，细雨菊花天。","旅思秋偏恶，乡心夜不眠。","钱塘江上月，行见十分圆。"]},{"t":"前中秋一日舟过山阴晚稻方熟忽动乡思呈先之","f":"五言古诗","c":["西风吹白蘋，游子千里征。","扁舟入鉴湖，水月相涵明。","山阴晚稻熟，万顷黄云平。","凭湖属远目，动我乡曲情。","岂不有一饱，胡为苦营营。","五年倦来往，争此蜗角名。","未知得失间，奚辱亦奚荣。","何当毕所愿，同归及春耕。"]},{"t":"夜泊萧山酒醒梦觉月色满船感而有作","f":"七言律诗","c":["候届星虚午夜凉，更堪停棹水中央。","短篷破处漏明月，归梦断时思故乡。","客里未忘诗酒趣，老来厌逐利名场。","明朝又向钱塘去，十里西风桂子香。"]},{"t":"十月二十八日母氏劬劳之日也哀痛中书二十八字","f":"七言绝句","c":["县弧谩喜生良月，看镜堪嗟已二毛。","不见双亲空泣血，此生无计报劬劳。"]},{"t":"次韵昌龄游白石二诗 其一 东际","f":"七言律诗","c":["飞流喷沫下烟岚，肯使名同盗与贪。","莫讶来时多汩汩，定知止处却潭潭。","遥通雁荡灵湫两，巍压龙门巨浪三。","好景不烦摩诘画，尽归诗客句中含。"]},{"t":"次韵昌龄游白石二诗 其二 道岩","f":"七言律诗","c":["未穷脚力上层霄，想象名山兴亦高。","物外游人身插羽，洞中仙客体生毛。","利名奔走嗟吾老，杖屦徜徉羡子豪。","凫舄共游端有日，预期木叶下亭皋。"]},{"t":"再和二首 其一","f":"七言律诗","c":["佛国飞来百尺岚，要将法水洗嗔贪。","仙人错认蓬莱岛，骚客羞谈钴鉧潭。","观尽岂须穷莫四，悟来初不异前三。","莫将七际观东际，法界三千际际含。"]},{"t":"再和二首 其二","f":"七言律诗","c":["少和丹就已登霄，岩与仙风两并高。","甚欲此身参鹤驭，尚嫌多事类牛毛。","云间鸡犬年犹永，世上英雄意谩豪。","堪羡北山山下客，不缘射雉亦如皋。"]},{"t":"赠万序","f":"五言律诗","c":["弦诵先闾里，东平典则存。","残膏沾后学，馀庆在重孙。","事业年方少，功名志可吞。","时人贪择脔，慎勿为财婚。"]},{"t":"过万桥哭潘先生","f":"七言绝句","c":["投老西游志不成，死生贫贱见交情。","江头昨夜潮声怒，却为先生气不平。"]},{"t":"夏伯虎赠双鲤","f":"七言绝句","c":["知我山间久食蔬，遥分七十二鳞鱼。","不妨时遣长须至，要得频看尺素书。"]},{"t":"贫家连岁蚕荒今年尤甚，妻孥有号寒之患每欲以酒自宽酒恶竟不能醉拙于生事殊可笑也表弟万大年家蚕熟酒醇有足乐者因思旧诗有剩栽桑柘教妻蚕句遂和以寄之","f":"七言律诗","c":["年踰四十尚何堪，愈老生涯愈不谙。","何以代耕犹未仕，初无可乐误为男。","号寒儿讶桑条沃，饮酒宾嫌蜜汁甘。","堪羡通家万公子，细君善酿更能蚕。"]},{"t":"大年和诗再用韵","f":"七言律诗","c":["年少如君种种堪，文场世事两俱谙。","何忧晁错不高第，未怕杜陵无好男。","况有田园足耕养，好穷水陆奉肥甘。","更须猛割闺房爱，来与荀卿共赋蚕。"]},{"t":"李梗和诗复用前韵","f":"七言律诗","c":["维摩老病思何堪，药性从今却渐谙。","掩卷正思眠丈室，论文俄喜遇奇男。","共嗟世路羊肠险，刚怕人情鼠口甘。","耸壑昂霄君未晚，吾衰已是食三蚕。"]},{"t":"用前韵寄周光宗","f":"七言律诗","c":["炎凉世态可能堪，肺腑唯蒙长者谙。","耐久敢忘三世好，同庚况有两家男。","我嗟风树徒悲苦，君奉庭闱备旨甘。","他日相看两黄发，愿为邻舍话田蚕。"]},{"t":"送李梗","f":"七言律诗","c":["梅始花时送子归，梅黄雨细又分离。","不堪旅食见飞燕，那更催归闻子规。","太白读书容有趣，少卿惜别可无诗。","霜台清峭家风在，努力功名少壮时。"]},{"t":"壬申中秋交朋解散不期而会者郑生逊志夏生伯虎因小饮玩月二子各以诗赠依韵酬之 其一","f":"七言律诗","c":["郑生襟宇绝纤埃，夏子心希好学回。","谁遣吾人来破愿，可能良夜不衔杯。","从来月罕中秋见，那更尊无俗子陪。","遥指桂枝因贺客，文星近岁属温台。"]},{"t":"壬申中秋交朋解散不期而会者郑生逊志夏生伯虎因小饮玩月二子各以诗赠依韵酬之 其二","f":"七言律诗","c":["犹胜太白号三人，又免韩公诮聚蚊。","薄有壶觞非独酌，共将文字作清醺。","天高云散悬金饼，风峭溪凉皱縠文。","却恨钟情未能遣，愁肠终夜转车轮。"]},{"t":"书小成室","f":"七言律诗","c":["万言杯水北窗里，慷慨悲歌五夜长。","骨肉未知苏季子，乡闾谁敬马宾王。","为人心尽同毛颖，与世交疏类孔方。","晦迹溪山可无恨，萧然一室任凄凉。"]},{"t":"哭孟丙 其一","f":"七言绝句","c":["三岁甜酸学语儿，能来壁下看题诗。","当时戏发十年问，添我无穷今日悲。"]},{"t":"哭孟丙 其二","f":"七言绝句","c":["萧瑟杨雄宅一区，不堪老境失童乌。","数茎须似经霜叶，为汝钟情一夜枯。"]},{"t":"哭孟丙 其三","f":"七言绝句","c":["帘外飞飞燕哺雏，道傍儿戏聚游鱼。","老人含泪坐书几，不见吾儿已月馀。"]},{"t":"哭孟丙 其四","f":"七言绝句","c":["偃蹇衰翁四十馀，梅花溪上结茅庐。","窗明几净还如旧，不见儿来觅纸书。"]},{"t":"哭孟丙 其五","f":"七言绝句","c":["偶作吾儿真梦寐，暂来人世误娄罗。","虽然修短由天命，致汝无辜我罪多。"]},{"t":"哭孟丙 其六","f":"七言绝句","c":["七年娇姹慰衰翁，回首追思一梦中。","与汝夙缘如未断，重来当似顾非熊。"]},{"t":"家童拾栗因念亡儿作数语以写钟情之悲","f":"七言律诗","c":["去年觅栗嫌汝痴，责汝曾赋渊明诗。","今年栗熟不汝见，凄然白骨埋荒陂。","西风簌簌黄叶飞，家僮拾栗门前归。","汝兄汝妹争来取，汝父伤心泪如雨。"]},{"t":"林知常惠白酒六尊仍示酒法作十韵谢之","f":"七言古诗","c":["老去生涯付杯酒，种秫辛勤三百亩。","东皋遗法嗟失传，蜜汁齑浆不通口。","迩来软饱经月无，岂有清欢对朋友。","百钱强就村媪醉，终夜蔬肠作雷吼。","先生祇把文字耕，妙意能施杜康手。","怜我新愁馀万斛，那更浇肠无五斗。","分惠青州六从事，秘法兼蒙传肘后。","便同北海歌不空，免似东坡叹乌有。","嗟予偃蹇老更饕，感激故人情意厚。","会须续遣白衣来，篱畔黄花欲重九。"]},{"t":"九日饮酒会趣堂者十九人老者与焉既醒念不可以无诗因用赠林知常韵示诸友","f":"七言古诗","c":["我似杨雄贫嗜酒，笔作耕犁纸为亩。","辛勤耕植三十年，往往糟醨罕濡口。","今年九日瓮盎空，谁馔先生荷诸友。","衰颜迎醉生嫩红，馋腹随餐失饥吼。","菊花不上老人头，酒盏聊传此时手。","文字饮韩嘉数子，礼法拘髡惟一斗。","衰翁兴尽辄先归，不待杯盘狼籍后。","坐客高歌惊四邻，吾乡已在无何有。","明朝黄花亦不恶，俗眼无端自疏厚。","酒醒聊记坐中人，有似平原凡十九。"]},{"t":"陈元佐和诗赠以前韵","f":"七言古诗","c":["无功懒仕由堪酒，故向东皋事田亩。","自惭耕稼非老农，岁入何曾给糊口。","通功易事愧无术，谩辟书斋会乡友。","出技惭如鼯鼠穷，说法强为师子吼。","交游渐觉不在眼，老拙自知当缩手。","陈生慷慨真可人，文似良金胆如斗。","论交何止十年前，耐久遥期十年后。","把酒殷勤问黄菊，十年故旧宁多有。","士穷要使节义敦，不见韩公称子厚。","北窗捉笔书恶诗，醉中戏赠陈三九。"]},{"t":"周仲翔和诗赠以前韵","f":"七言古诗","c":["与子十年同把酒，贫贱未能离陇亩。","今年依旧对黄花，会意何由笑开口。","老来钟爱有三儿，迩岁从师得吾友。","祝螟方拟为蠃飞，舐犊俄惊作牛吼。","幼儿已作一觉梦，大匠徒施两年手。","乙子沉痾赖营牧，再生岂止由南斗。","嗟予屯厄世所弃，急难谁肯相先后。","论交最喜子善终，报德深惭我无有。","犹怜甲乙二孺子，莫景于渠意加厚。","烦君为我严诲之，毋惜鞭笞九十九。"]},{"t":"陈献可宋孝先万孝杰夏伯虎和诗复用前韵","f":"七言古诗","c":["准拟重阳会诗酒，手种菊花凡数亩。","佳节相逢俱可人，一一篇章堪适口。","扬庭酝籍更清新，晋宋间人颜谢友。","舜卿词源浩万斛，下笔惊人风雨吼。","季梁萧洒诗如人，飘然自是风骚手。","用之年少富文墨，日出珠玑不论斗。","诚叔思深希仲逸，齐驱未识谁先后。","老朽那能敌年少，胸中空洞嗟无有。","张我三军得数子，造物遗予非不厚。","明年秋战岂无人，云梦定须吞八九。"]},{"t":"九日把酒十九人和诗者数人而已今已后期不复追索许以来年九日还用前韵发一笑","f":"七言古诗","c":["劝君须饮文字酒，劝君耕耨心中亩。","饮非文字犹聚蚊，心田不耕棘生口。","登高佳节岂易得，况此相逢皆胜友。","谈倾坐上冰玉清，兴生笔下波涛吼。","我亦逢场聊戏剧，韵语殊非三昧手。","试投瓦砾已成堆，辱报骊珠未盈斗。","和之者寡岂阳春，高才料耻居王后。","嗟我穷愁无以遣，酒债诗篇行处有。","与兹饮会类平原，逃我诗盟几高厚。","如今并许隔年还，直须日月逢重九。"]},{"t":"宋孝先示读自宽集复用前韵","f":"七言古诗","c":["渊明酷爱尊中酒，季子贫无负郭亩。","我生薄与二子同，俯仰人间亦缘口。","一室萧然仅容膝，毛颖陶泓自相友。","会心终日雌声读，排闷有时粗气吼。","感秋诗集名自宽，雕琢更惭非妙手。","篇章不工如子固，声名敢望星之斗。","宋生辄作过情语，十韵殷勤为跋后。","誉之韩柳谁敢当，意古语奇吾岂有。","何如操矛时入室，针我膏肓乃相厚。","床头周易深且神，毋惜往来论六九。"]},{"t":"再用前韵述怀并简诸友","f":"七言古诗","c":["太白徉狂喜杯酒，元龙豪气耻求亩。","挥毫烂吐风月篇，济世高谈霸王口。","古人可作谁与归，白也吾师登可友。","万言窗下杯水冷，百尺楼头鼻声吼。","丈夫未遇聊尔耳，肯向权门思炙手。","净扫一室安吾贫，昼阅诗书夜星斗。","休论生天与作佛，灵运甘居丈人后。","吾侪慎分慕富贵，鸣鼓定须攻冉有。","但愿相从文字乐，交情合向穷中厚。","倚看前席坐间人，平步登瀛参二九。"]},{"t":"郑逊志胡叔成谢鹏刘敦信万廓邬一唯和诗复用前韵","f":"七言古诗","c":["前日中秋一壶酒，交朋解散归南亩。","把杯邀月止三人，中有客来从谷口。","首登诗坛出险语，张我孤军真畏友。","重阳佳句更奇绝，西风猛向松关吼。","中庸伯始遥遥胄，颖然作赋吟诗手。","谢客篇章似春草，分得家传才一斗。","句法天然自圆熟，长庆诗豪今有后。","妙龄能作老成语，必大奇儿亦希有。","邬郡太守司马孙，文与其人两温厚。","我与数子无薰莸，文字相从十常九。"]},{"t":"九日会饮予为唱首自和凡数篇皆因事叙情尔未作重九诗也今再和一篇每句用事而不见姓名末联外馀皆略存对偶必有能和之者","f":"七言古诗","c":["独坐东篱叹无酒，种秫西畴谩盈亩。","菊花丛畔来白衣，桑落杯中付馋口。","汝南风俗有故事，龙山宴集多佳友。","静闻彭泽三径香，遥想蓝田双涧吼。","顺时习射马嘶风，随俗登山囊系手。","慈恩塔冷旧衣冠，戏马台空古刁斗。","三嗅馨香感槩中，细看茱萸酩酊后。","应制赋诗人孰在，坐湖联句今还有。","明朝见花心已别，此日登高意宜后。","日月并应节物嘉，独恨今年无闰九。"]},{"t":"九日寄昌龄弟 其一","f":"五言绝句","c":["忆昔逢重九，登临不惮遥。","弟兄同把酒，行乐兴飘飘。"]},{"t":"九日寄昌龄弟 其二","f":"五言绝句","c":["去岁重九日，吾亲窀穸期。","东篱自黄菊，泪眼可曾知。"]},{"t":"九日寄昌龄弟 其三","f":"五言绝句","c":["此日黄花酒，深期酌弟兄。","谁知有离别，西望不胜情。"]},{"t":"九日寄昌龄弟 其四","f":"五言绝句","c":["我有茱萸沜，遥同辋川底。","登高少一人，又是王家弟。"]},{"t":"九日寄昌龄弟 其五","f":"五言绝句","c":["嘉节苦难遇，故山随俗登。","未能如郑谷，一榻对高僧。"]},{"t":"九日寄昌龄弟 其六","f":"五言绝句","c":["白石登山客，新诗句必豪。","宁容杜陵老，独步玉山高。"]},{"t":"九日寄昌龄弟 其七","f":"五言绝句","c":["我思雁荡游，欲与雁行去。","羽翼本天生，谁令分两处。"]},{"t":"九日寄昌龄弟 其八","f":"五言绝句","c":["乐事苦无多，良辰岂长见。","明年缀席时，要使茱萸遍。"]},{"t":"九日寄昌龄弟 其九","f":"五言绝句","c":["庭前有晚菊，青蕊未堪插。","开日即重阳，归来酒同呷。"]},{"t":"九日寄昌龄弟 其十","f":"五言绝句","c":["载酒觞黄菊，登山臂紫茱。","重修汝南事，灾厄自今无。"]},{"t":"九日寄昌龄弟 其十一","f":"五言绝句","c":["老去悲秋甚，兴来聊自娱。","明年知健否，子细看茱萸。"]},{"t":"九日寄昌龄弟 其十二","f":"五言绝句","c":["穷途嗟我衰，中岁伤儿夭。","兄弟止三人，尊前岂宜少。"]},{"t":"九日寄昌龄弟 其十三","f":"五言绝句","c":["嗅菊谩劳三，赐安得萸一。","聊分故园枝，不负重阳日。"]},{"t":"九日寄昌龄弟 其十四","f":"五言绝句","c":["节物岂不好，吾家何太贪。","一尊聊尔寄，重意愧先人。"]},{"t":"万叔永诞日在孟秋，乃以重九开燕俟佳节也予不获与称觞之列作诗以贺","f":"七言律诗","c":["种德尤胜窦十郎，灵椿未老桂先芳。","一门此去无疑大，五福他年未易量。","凤穴生雏梧正碧，龙山开宴菊初黄。","吾乡此会从来少，恨不登堂举寿觞。"]},{"t":"九月十二夜独步梅溪玩月人迹悄然秋色满眼微风不动岩桂自香初不劳思偶得四句盖心境中静时语也归小成室对短灯檠索纸书之","f":"七言绝句","c":["独步溪头夜初寂，扫空尘念心清凉。","月明眼底见秋色，境静鼻根闻桂香。"]},{"t":"前日寓邑偶值乍寒陈刘二生济我以衣童生济我以衾既别为二诗以赠 其一 赠陈元佐刘士宗","f":"七言律诗","c":["肌体生鳞须飒毛，衰年怯冷欲儿号。","无人来绽韩公袄，有友能施范叔袍。","入手乍惊儒袖阔，披身尤喜义襟高。","书生忍冻谁相顾，共弊轻裘赖我曹。"]},{"t":"前日寓邑偶值乍寒陈刘二生济我以衣童生济我以衾既别为二诗以赠 其二 赠童伟侃","f":"七言律诗","c":["凛冽霜风夜薄人，谁能煖我曲勾身。","寒欺三幅范衾陋，睡美一宵姜被新。","体粟不愁生旅舍，鼻雷想见撼比邻。","梦回却念君兄弟，苫块无眠痛慕亲。"]},{"t":"万先之生两男作洗儿歌贺之","f":"词","c":["君不见徐卿二子生绝奇，熊罴入梦非同时。","徒烦孔子与释氏，两回抱送麒麟儿。","又不见昔日梁嬴亦双乳，生止一男仍一女。","过期毕竟非其人，未免终身亦妾圉。","郁葱佳气充门闾，龙穴盛事从来无。","蓂阶良月吐三荚，蚌腹甲夜生双珠。","相对抱持翁妪喜，眉目分明巧相似。","慈颜戏语綵衣郎，汝子他年胜我子。","郎君拜舞笑答翁，翁生六儿年岂同。","何如今日一卮酒，手抱两孙头未童。","二雏庆诞相先后，未省如何分长幼。","商家尚质周尚文，唤取何休细推究。","庆门兰玉行满庭，伯仲叔季双命名。","他时四乳类周士，森森八桂同敷荣。","我忝通家同笔砚，闻君得子欢无间。","殷勤为作洗儿歌，觅取金钱三百万。"]},{"t":"黄府君挽词 其一","f":"七言绝句","c":["不杂商山绮与园，生涯占得小桃源。","平生隐德知多少，跨灶诜诜已六孙。"]},{"t":"黄府君挽词 其二","f":"七言绝句","c":["纷然紾臂已成风，一爨谁能再世同。","野史他年书逸事，定须记此富家翁。"]},{"t":"黄府君挽词 其三","f":"七言绝句","c":["扬州别驾知名士，肝胆崔嵬百鍊刚。","谁谓公家有兰玉，解令高选继东床。"]},{"t":"黄府君挽词 其四","f":"七言绝句","c":["齿发如公自古稀，定应含笑九原归。","春风白石岩前路，忍见杨花作雪飞。"]},{"t":"予自乙丑冬如临安赴补逮今凡五往矣是行也痛慈亲之不见伤幼儿之蚤死登途泫然因成是诗","f":"五言律诗","c":["八岁五行役，兹行最感伤。","思亲啼血泪，忆子断刚肠。","游远有遗恨，钟情难遽忘。","离家两夜梦，长绕白岩旁。"]},{"t":"初拟过雁山既而取道乌石寄梦龄昌龄","f":"七言绝句","c":["不度丹芳七七盘，非缘杖屦厌间关。","要留来岁高风便，兄弟成行过此山。"]},{"t":"过白溪","f":"七言绝句","c":["朝离黄塘憩乌石，莫宿青江过白溪。","岭上回头观赤水，山川五色望中迷。"]},{"t":"过盘山宿旅邸","f":"七言绝句","c":["一岭迢迢十里赊，行人半日踏烟霞。","青山遮莫盘千匝，归梦何曾不到家。"]},{"t":"登皇华亭","f":"七言绝句","c":["不是四方衔命士，偶来亭上赋皇华。","凭栏回首三百里，烟水茫茫思故家。"]},{"t":"宿浮桥","f":"五言律诗","c":["落日丹丘下，西江十里西。","浮桥通古道，逆旅傍清溪。","夜静水声细，晓阴山色迷。","吾乡在何处，天远白云低。"]},{"t":"与郑时敏登楼把酒书二绝 其一","f":"七言绝句","c":["十里青山接郡城，危楼四望眼添明。","海冥天阔乡心切，更听飞飞鸿雁声。"]},{"t":"与郑时敏登楼把酒书二绝 其二","f":"七言绝句","c":["登楼能赋非王粲，沽酒忘形有郑虔。","千里相从文字饮，不辞费尽杖头钱。"]},{"t":"途中见早梅","f":"七言古诗","c":["山行初逢建子月，始见寒梅第一枝。","遥想吾庐亦如此，谁能千里赠相思。","梅花发后思家切，竹间水际出横枝。","暗香疏影和新月，自是离情禁不得，触物那堪此时节。","春前腊后定归来，要看溪上千株雪。"]},{"t":"乙丑冬西游观南明石像作诗一绝至壬申十月四日复往观焉和前韵并书于佛阁","f":"七言绝句","c":["儿戏团沙欲象真，谁将愿力历三尘。","八年来往箫峰客，两度来瞻百尺身。"]},{"t":"西征","f":"七言古诗","c":["绍兴建元二十二，良月壬午时丁未。","王家辞弟游帝都，出门满眼思亲泪。","鹡鸰送我过原隰，朋友携尊宿萧寺。","朝离黄塘惜分别，莫宿青山嗟独自。","初心满拟游雁山，行止非人辄乖异。","黄岩留连越三宿，故旧过从日沈醉。","郑生伴我千里行，近世人无此风义。","皇华亭上一回首，陡觉眉头起乡思。","西江十里浮桥边，把酒登楼吟拥鼻。","山行初逢建子月，入眼梅花已春意。","前观三渡觉非旧，下视两滩真可畏。","渡头仙人还笑我，髭须如棘犹名利。","欲入天台观石桥，行来匆匆未能遂。","途中邂逅张老丞，十五年前乐清尉。","自嗟吾非沈谢辈，面目从来苦难记。","飞泉枕上梦成魔，达旦思家何曾睡。","细雨濛濛入关岭，旅邸重寻旧题字。","雨脚微收过天姥，洗出峰峦叠苍翠。","刘阮祠荒土犹赤，溪山真是神仙地。","道旁石现小金仙，传舍荒凉谁废置。","柘溪竹染儿女痕，石岭松含栋梁器。","路入南明观石佛，楼阁岧峣更深邃。","八年行役两来游，岩上题诗记前事。","乘兴剡溪寻故人，久别相逢杂悲喜。","义风吹水送行舟，越国江山满瞻视。","十四岁娥孝且烈，三百里湖明更媚。","千岩竞秀壑争流，终日贪看趣遥寄。","西兴渡口声如雷，银浪崔嵬魄惊悸。","江神为我风色平，天阙煌煌瞻象魏。","贤关访旧话酸辛，更食齑盐旧滋味。","学官欲以职事留，自愧非才力辞避。","观台云物端可书，宫线初长日南至。","龙山僦舍观大礼，仪仗森然典文备。","人臣贵盛古今无，秦公父子俱为使。","景灵告谢乐声回，鹓鹭花枝侈君赐。","西游连日睹天颜，和气氤氲散憔悴。","岁云莫矣却归来，捉笔书为于役志。"]},{"t":"癸酉三月二十五日至剡溪旅舍观曹梦良题壁有撩我思家第一篇之句仆离家半月亦未尝作诗因次其韵","f":"七言绝句","c":["客舍那堪闻杜鹃，梦魂惊断竟无眠。","定知此境撩乡思，我亦曾非第二篇。"]},{"t":"剡之市人以崇奉东岳为名设盗蹠以戏先圣所不忍观因书一绝","f":"七言绝句","c":["里巷无端戏大儒，恨无司马为行诛。","不知陈蔡当时厄，还似如今嵊县无。"]},{"t":"周德远植瑞香于窗前戏成一绝","f":"七言绝句","c":["主人贪睡为贪香，花植窗前意味长。","见说有时魂梦里，化为蝴蝶绕花旁。"]},{"t":"游明心院","f":"五言律诗","c":["精舍傍脩岭，道心随眼明。","泉馀偃公迹，山接剡溪城。","无雨竹亦净，有风松更清。","谁名上方阁，撩我欲归情。"]},{"t":"游圆超院登挟溪亭次卢公韵","f":"词","c":["路入剡山腰，风生玉川腋。","孤亭物外高，双溪眼中碧。","山僧作亭知几春，赏音端怕逢诗人。","自从妙语发丘壑，遂使绝境多蹄轮。","我来首访维摩诘，问讯双溪自何出。","发源应与婺溪同，赋物惭无沈郎笔。","凭栏欲洗名利尘，入眼翻惊客恨新。","山城重重水如带，可能挽住思乡人。"]},{"t":"寄梦龄昌龄弟","f":"七言律诗","c":["老去生涯集百忧，一身萍泛剡溪头。","钓鱼温水同侯喜，旅食新丰类马周。","长铗有时思海味，短檠终夜照离愁。","也知四海皆兄弟，能似天生羽翼不。"]},{"t":"高和叔生日","f":"七言律诗","c":["高标绰有鲁王风，天为勋门庆诞公。","挥麈笑谈倾坐上，传家韬略蕴匈中。","暂从剡水高人隐，行继澶渊盖世功。","长愿红颜似今日，寿尊鲸吸百川空。"]},{"t":"天子始絺","f":"五言古诗","c":["盛德方居火，天王始服絺。","薰风生殿早，畏日到官迟。","瑩雪罗初叠，含风葛乍披。","汗宁濡玉体，暑不近天肌。","表饰遵尼父，恩荣彼拾遗。","中宫同俭德，无愧葛覃诗。"]},{"t":"渊源堂十二诗 其一 渊源堂","f":"五言绝句","c":["像貌崇贤圣，名言训子孙。","日亲师与友，力学探渊源。"]},{"t":"渊源堂十二诗 其二 细论堂","f":"五言绝句","c":["不饮红裙酒，祇将文字论。","江东渭北客，日日对芳尊。"]},{"t":"渊源堂十二诗 其三 宜桂轩","f":"五言绝句","c":["主人端不俗，景物亦相宜。","手种轩前桂，联芳共几枝。"]},{"t":"渊源堂十二诗 其四 蕴秀轩","f":"五言绝句","c":["剡溪蕴秀异，久郁少陵诗。","今向轩前看，人如晋宋时。"]},{"t":"渊源堂十二诗 其五 同襟馆","f":"五言绝句","c":["安道家何处，溪山深更深。","扁舟不惮远，得得访同襟。"]},{"t":"渊源堂十二诗 其六 富学斋","f":"五言绝句","c":["金玉本非富，诗书元不贫。","平生无尽用，学问在吾身。"]},{"t":"渊源堂十二诗 其七 辉声斋","f":"五言绝句","c":["功名就烜赫，遗训可能忘。","待献明光赋，蜚声满四方。"]},{"t":"渊源堂十二诗 其八 集彦斋","f":"五言绝句","c":["独学恐孤陋，要须亲友朋。","虚斋集群彦，共对短灯檠。"]},{"t":"渊源堂十二诗 其九 擢秀斋","f":"五言绝句","c":["好似东山谢，满庭芝与兰。","义方能不倦，擢秀固非难。"]},{"t":"渊源堂十二诗 其十 恢义斋","f":"五言绝句","c":["忆昔杜陵老，恨无千万间。","君能恢大义，吾党悉欢颜。"]},{"t":"渊源堂十二诗 其十一 兰馨室","f":"五言绝句","c":["一室虽方丈，游从必舜徒。","芬馨不自觉，身化与之俱。"]},{"t":"渊源堂十二诗 其十二 足鲤池","f":"五言绝句","c":["堂上论文客，异时还索居。","池中鲤鱼足，好寄别来书。"]},{"t":"书院杂咏 牡丹","f":"五言绝句","c":["今古几池馆，人人栽牡丹。","主翁兼种德，要与子孙看。"]},{"t":"书院杂咏 芍药","f":"五言绝句","c":["已过花王候，才闻近侍香。","来游禁酒地，免作退之狂。"]},{"t":"书院杂咏 岩桂","f":"五言绝句","c":["岩桂何时种，遥闻月窟香。","君家似燕窦，会见五枝芳。"]},{"t":"书院杂咏 江梅","f":"五言绝句","c":["园林尽摇落，冰雪独相宜。","预报春消息，花中第一枝。"]},{"t":"书院杂咏 酴醾","f":"五言绝句","c":["日烘香倍远，雨浥韵尤清。","谁把玉钱比，恐花羞此名。"]},{"t":"书院杂咏 红梅","f":"五言绝句","c":["桃李莫相妒，天姿元不同。","犹馀雪霜态，未肯十分红。"]},{"t":"书院杂咏 海棠","f":"五言绝句","c":["欲与春争媚，嫣然一笑芳。","雨中如有恨，疑是为无香。"]},{"t":"书院杂咏 瑞香","f":"五言绝句","c":["曾入江南梦，故宜名瑞香。","何人好谈论，雅目误更张。"]},{"t":"书院杂咏 菊花","f":"五言绝句","c":["不恨开时晚，自知能傲霜。","慎毋同琐细，采撷上君堂。"]},{"t":"书院杂咏 蜡梅","f":"五言绝句","c":["非蜡复非梅，梅将蜡染腮。","游蜂见还讶，疑自蜜中来。"]},{"t":"书院杂咏 榴花","f":"五言绝句","c":["客馆逢重午，石榴花正芳。","吾庐开亦好，归去嚼天浆。"]},{"t":"书院杂咏 薝卜","f":"五言绝句","c":["禅友何时到，远从毗舍园。","妙香通鼻观，应悟佛根源。"]},{"t":"书院杂咏 千叶黄梅","f":"五言绝句","c":["菊以黄为正，梅惟白最佳。","徒劳染千叶，不似雪中花。"]},{"t":"书院杂咏 千叶红桃","f":"五言绝句","c":["在处飘红雨，临窗照夕阳。","何时清禁里，一笑伴仙郎。"]},{"t":"书院杂咏 千叶白桃","f":"五言绝句","c":["岂有夭桃艳，淡然群卉中。","全身是清白，那肯媚春风。"]},{"t":"书院杂咏 佛见笑","f":"五言绝句","c":["学得酴醾白，更能相继芳。","金仙粲然笑，鼻观不多香。"]},{"t":"书院杂咏 荷花","f":"五言绝句","c":["十里西湖上，红云照绿波。","何如吾净友，臭味不须多。"]},{"t":"书院杂咏 蓼花","f":"五言绝句","c":["秋色在何许，蓼花含浅红。","客情禁不得，归兴逐西风。"]},{"t":"书院杂咏 萱花","f":"五言绝句","c":["有客看萱草，终身悔远游。","向人空自绿，无复解忘忧。"]},{"t":"书院杂咏 斑竹","f":"五言绝句","c":["苍梧巡不返，斑竹至今存。","今日稽山下，几枝忠孝痕。"]},{"t":"书院杂咏 燕竹","f":"五言绝句","c":["问讯东墙竹，佳名今始知。","龙孙初迸日，燕子却来时。"]},{"t":"书院杂咏 西河柳","f":"五言绝句","c":["潇洒西河种，谁移向浙东。","青枝太纤细，莫近楚王宫。"]},{"t":"书院杂咏 葡萄","f":"五言绝句","c":["珠帐临檐挂，龙须满架抽。","也知堪酿酒，不要博凉州。"]},{"t":"书院杂咏 芭蕉","f":"五言绝句","c":["草木一般雨，芭蕉声独多。","主人栽未足，其奈客愁何。"]},{"t":"书院杂咏 石菖蒲","f":"五言绝句","c":["天上玉衡散，结根泉石间。","要须生九节，长为驻红颜。"]},{"t":"书院杂咏 慎火草","f":"五言绝句","c":["禁殿安蚩尾，骚人逐毕方。","何如栽此草，有火自能妨。"]},{"t":"书院杂咏 盆中新荷","f":"五言绝句","c":["首夏盘池里，新荷点数圆。","主人行中选，故为作青钱。"]},{"t":"书院杂咏 假山","f":"五言绝句","c":["君有好山僻，叠山亭院间。","不遮山外眼，又得见真山。"]},{"t":"书院杂咏 盆池","f":"五言绝句","c":["不比儿童戏，埋盆作小池。","要令盆底水，长满不倾攲。"]},{"t":"书院杂咏 书架","f":"五言绝句","c":["君富端不俗，有钱长买书。","家藏三万轴，不怕腹空虚。"]},{"t":"书院杂咏 鹤","f":"五言绝句","c":["雅志在冲霄，长思振羽毛。","风前匆相和，声彻九天高。"]},{"t":"书院杂咏 鹅","f":"五言绝句","c":["善鸣聊自适，不愿遇知音。","深恐山阴妪，误猜君子心。"]},{"t":"书院杂咏 花鸭","f":"五言绝句","c":["毛羽不多异，浪于花得名。","深疑杜陵误，黑白未分明。"]},{"t":"书院杂咏 鸂鶒","f":"五言绝句","c":["文采真为累，飞鸣不自由。","小池新水涨，相对谩沉浮。"]},{"t":"剡溪杂咏 剡溪","f":"五言绝句","c":["千古剡溪水，无穷名利舟。","閒乘雪中兴，惟有一王猷。"]},{"t":"剡溪杂咏 了溪","f":"五言绝句","c":["禹迹始壶口，禹功终了溪。","馀粮散幽谷，归去锡玄圭。"]},{"t":"剡溪杂咏 挟溪亭","f":"五言绝句","c":["远水从台婺，同归古嵊州。","巍亭压山顶，千古挟双流。"]},{"t":"剡溪杂咏 龙宫碑","f":"五言绝句","c":["曾到龙宫寺，拂尘观古碑。","何时无短李，肉眼可能知。"]},{"t":"剡溪杂咏 戴颙墓","f":"五言绝句","c":["旷野冢累累，子孙犹不知。","千年戴颙墓，三字道旁碑。"]},{"t":"剡溪杂咏 阮仙翁宅","f":"五言绝句","c":["再入山中去，烟霞锁翠微。","故乡遗宅在，何日更来归。"]},{"t":"剡溪杂咏 戴溪亭","f":"五言绝句","c":["剡水照人碧，剡山随眼青。","我来非雪兴，惭上戴溪亭。"]},{"t":"剡溪杂咏 偃公泉","f":"五言绝句","c":["泉自何时有，得名从偃公。","谁能继张陆，为载水经中。"]},{"t":"书院挂额展筵雅会也戏集诸堂轩斋名作诗","f":"五言古诗","c":["黉馆名初挂，银钩势欲翻。","人才蕴秀异，学业扣渊源。","俊彦方群集，文章可细论。","辉声迈前辈，擢秀蔼诸孙。","心友居兰室，天香满桂轩。","兹为学者富，难与俗流言。","恢义高风倡，同襟旧好敦。","池中神鲤足，一一上龙门。"]},{"t":"别周德远诸友","f":"五言古诗","c":["山城过疏雨，客馆生新秋。","乡心杂病思，浩荡不可留。","忆昨初来时，园花弄春柔。","俯仰节物变，木杪风飕飕。","旅食百日馀，故人情已周。","论文有深味，惜别添牢愁。","槐花物色老，琴书散交游。","暖律回南枝，相期泛仙舟。"]},{"t":"宿石佛","f":"五言律诗","c":["脩径入幽壑，梵宫摩碧霄。","仰头惊突兀，跬步怯岧峣。","宝相石间涌，钟声云外飘。","明朝路南北，身世各尘嚣。"]},{"t":"白若遇水以小舟从石门渡势危甚因书数语示图南文卿时八月二日也","f":"词","c":["归途阻秋潦，溪涨不可涉。","迂从石门渡，未见心已怯。","壮哉龙伯宫，幽据雁山胁。","岩如峙城壁，南北本相接。","众流欲朝宗，天为开岌嶪。","泓澄潭百尺，臲卼舟一叶。","吾生何自轻，内顾无可挟。","所赖二友生，千里同负笈。","忠信傥可仗，免作飞鸢跕。","来归从剡溪，山水颇涉猎。","石齧天台舟，浪拍临海楫。","可曾如此境，令我魂震慑。","连年作行客，川涂但取捷。","不因风雨暴，谁?远步屧。","兹渡虽云恶，观览意亦惬。","谩赋石门篇，添入剡游箧。"]},{"t":"孟甲生日","f":"五言律诗","c":["记汝初生际，灯花达旦然。","门阑增喜庆，翁妪最矜怜。","已过周天岁，行临志学年。","勉修愚鲁质，诗礼称家传。"]},{"t":"孟甲孟乙好蓄古钱因示以诗","f":"五言古诗","c":["世人多好钱，今汝独好古。","书中阅平准，壁上按图谱。","广拾汉五铢，远及周九府。","惜哉生我家，此物罕曾睹。","百中时得一，喜笑见眉宇。","所蓄虽不多，其志颇可取。","闾阎富家子，绕床堆阿堵。","一字不识丁，碌碌何足数。","更宜移此力，典坟读三五。","纵未到圣贤，定可过乃父。"]},{"t":"周光宗赠蛎房报以溪莼","f":"七言律诗","c":["珠屿蛎房魁海错，左原莼线冠溪毛。","韩公南食可曾见，张翰东归徒自高。","鼎俎珍庖输肉食，江湖佳味属吾曹。","有无相易通家事，僮仆往来毋惮劳。"]},{"t":"刘府君挽词 其一","f":"七言律诗","c":["歆向诜然萃一门，过庭诗礼尽公恩。","奇儿不负义方教，旧治至今遗爱存。","心境欲明凭贝叶，寿藏预卜傍祇园。","髯郎行烛青藜杖，定见荣光达九泉。"]},{"t":"刘府君挽词 其二","f":"七言律诗","c":["贱子无天衅早钟，记观先友涕亡从。","士林方喜荣三桂，丞舍俄惊惨二松。","剡水凄凉回棹速，丹丘恸哭过车凶。","发扬门户胜他族，深羡公家有蔡邕。"]},{"t":"贾府君挽词","f":"七言律诗","c":["鹿岩重见鹿门翁，襟宇浑然太古风。","负郭良田全种德，起家难弟已收功。","花间麟冢经年就，木杪龟趺指日丰。","门婿自惭非李汉，鄙文何足状韩公。"]},{"t":"陈夫人挽词","f":"七言律诗","c":["伟节声名盖一时，夫人淑德最相宜。","便甘布素从高隐，不惜花钿拯众饥。","萱草未乾堂下土，杨花已应梦中诗。","如今多少王孙饿，进食哀怜复有谁。"]},{"t":"纳凉偶成","f":"五言律诗","c":["架松却烦暑，梳竹来清风。","顽然七尺躯，寄此微凉中。","高枕傲有道，深杯醉无功。","山林有馀乐，此兴谁吾同。"]},{"t":"悼演述二老僧","f":"七言律诗","c":["叠石峰前二老僧，相逢一笑见真情。","社中对酒日初永，林下围棋秋始清。","尚拟维摩眠丈室，遽惊圆泽厌浮生。","通幽亭冷西楼古，过客伤心涕泪横。"]},{"t":"黄杨","f":"词","c":["嘉彼黄杨，郁焉其苍。","匪瓮而圆，匪盖而张。","百干同根，森如弟昆。","千枝其子，万叶其孙。","惟此黄杨，先子所植。","草木有义，先子之德。","愿言我家，兄弟子孙。","如此嘉树，永为义门。"]},{"t":"林下十二子诗 竹子脩","f":"七言绝句","c":["万木萧疏怯岁寒，子脩相见喜平安。","世间宁有扬州鹤，休讶平生肉食难。"]},{"t":"林下十二子诗 井子深","f":"七言绝句","c":["席量泓泓井子深，客来车辖总能沉。","定须再筑新亭覆，不负先君好事心。"]},{"t":"林下十二子诗 梅子先","f":"七言绝句","c":["竹外溪头手自栽，群芳推让子先开。","好将正味调金鼎，莫似樱桃太不才。"]},{"t":"林下十二子诗 桂子苍","f":"七言绝句","c":["学仙深愧似吴郎，赖有吾庐两子苍。","疑是广寒宫里种，一秋三度送天香。"]},{"t":"林下十二子诗 兰子芳","f":"七言绝句","c":["国香入鼻忽扬扬，知是光风泛子芳。","林下自全幽静操，纵无人采亦何伤。"]},{"t":"林下十二子诗 昌阳子仙","f":"七言绝句","c":["天上星郎字子仙，结根拳石傍清泉。","豨苓方入医师手，谁识仙姿解引年。"]},{"t":"林下十二子诗 黄子嘉","f":"七言绝句","c":["保绿轩前黄子嘉，非松非柏亦非花。","故应唤作思人树，数十年前阅我家。"]},{"t":"林下十二子诗 丁子素","f":"七言绝句","c":["雨底含愁雪里芳，琉璃叶映小何郎。","世人竞重熏笼锦，子素何曾怯瑞香。"]},{"t":"林下十二子诗 柳子春","f":"七言绝句","c":["夹道青青柳子春，自从栽植几番新。","如今已作参天树，应笑衰迟老主人。"]},{"t":"林下十二子诗 槐子夏","f":"七言绝句","c":["方苦炎炎畏日长，欣蒙子夏惠清凉。","三槐雅是王家物，为榜新亭拟旧堂。"]},{"t":"林下十二子诗 菊子秀","f":"七言绝句","c":["子秀霜中色更嘉，金钱粲粲满庭阶。","渊明异日开三径，端仗兹花慰老怀。"]},{"t":"林下十二子诗 王子野","f":"七言绝句","c":["场屋虚名且罢休，归来聊效晋人游。","林间诸子总非俗，肯与野人为友不。"]},{"t":"昌龄辟圃植花索诗于老者戏作数语兼简梦龄","f":"七言律诗","c":["东园小小花木稀，西园廓廓规模奇。","西园主人但置酒，东园老人甘赋诗。","朝游西园饮千斛，莫向东园吟百幅。","更约南园好事人，酒盏诗篇日相续。"]},{"t":"西园新辟昌龄索诗予以其未开尊也戏作数语既饮复用前韵","f":"七言律诗","c":["阿连好事由来稀，开轩辟圃幽更奇。","峰峦罗列富遐览，气象收拾归新诗。","百挺琅玕花数斛，宛似辋川图一幅。","朝莫过从有弟兄，长愿歌声无断续。"]},{"t":"予与二弟连日赋诗饮酒诗成命二子书之亦居家之一乐也复用前韵","f":"七言律诗","c":["不愁地辟车马稀，自喜兄弟俱好奇。","阿连举觞劝我酒，阿买研墨书翁诗。","长泛郑生船百斛，日赋邺侯三四幅。","何用身封万户侯，但愿青箱有人续。"]},{"t":"昌龄和诗以不得志于贤关有欲退隐之语复用前韵勉其涵养俟时未可真作休休计也","f":"七言律诗","c":["出门休叹知己稀，开卷揽取前人奇。","西园松菊聊笑傲，未可遽赋休休诗。","涵养胸襟容万斛，仰视青天纸盈幅。","行看富贵来逼人，江左家声子当续。"]},{"t":"昌龄频开尊再用前韵","f":"七言律诗","c":["人生常患如意稀，利名扰扰何足奇。","谁能如我惠连弟，有园有酒兼能诗。","种秫西畴都几斛，时见小童驰片幅。","风轩洒扫又相呼，适有嘉鱼馈羊续。"]},{"t":"用前韵题东园","f":"七言律诗","c":["吾园小小游人稀，吾腹便便空自奇。","径草青青可煎饮，雨竹涓涓堪赋诗。","鲜鲜菊满东篱斛，扬扬兰入骚人幅。","牡丹芍药紫薇梅，四时花卉开相续。"]},{"t":"贾元识和诗酬以前韵","f":"七言律诗","c":["河东丈人年及稀，精神矍铄心瑰奇。","新来移居向山谷，一尊时得同论诗。","酒量汪汪可胜斛，醉后挥毫动盈幅。","新诗疏越似朱弦，不才何用煎胶续。"]},{"t":"次韵昌龄西园即事","f":"七言律诗","c":["世态蝇营已厌驱，小园初辟称幽居。","杯深转觉利名薄，心静更宜花木疏。","窗几吟馀山色好，轩斋梦觉日华舒。","尤怜不弃东园老，时复相从辨鲁鱼。"]},{"t":"东园小閤丹粉一新昌龄有诗次韵","f":"七言古诗","c":["小园小閤无奇新，但喜有酒堪娱宾。","西畴种秫可自酿，不用勤买抛青春。","月明星稀乌择木，吾爱吾庐堪寓目。","须知主父五鼎珍，不似王猷数竿竹。","丈夫未遇当安贫，带经且作锄园人。","诗酒过从老兄弟，一笑可破双眉颦。","见说西园相继辟，好将因果同栽植。","子孙清白世相传，莫同阮氏分南北。"]},{"t":"梦龄得男老者喜甚汤饼会中出诗以贺","f":"七言律诗","c":["梅溪佳气夜葱葱，果得奇儿应梦熊。","汤饼笑欢良不浅，桑弧时节稍相同。","喜将老眼看犹子，首出新诗贺乃翁。","从此吾门如谢傅，芝兰玉树满庭中。"]},{"t":"予有书閤仅容膝东有隙地初甚荒芜偶于暇日理成小园径以通之杖藜日涉于其间几欲成趣然花木萧疏不足播之吟咏谩赋十一小诗以记园中之仅有者时甲戌仲冬也 小小园","f":"五言绝句","c":["预作休休计，先开小小园。","杖藜成日涉，得趣与心论。"]},{"t":"予有书閤仅容膝东有隙地初甚荒芜偶于暇日理成小园径以通之杖藜日涉于其间几欲成趣然花木萧疏不足播之吟咏谩赋十一小诗以记园中之仅有者时甲戌仲冬也 便便閤","f":"五言绝句","c":["一閤仅容膝，闭门尘虑捐。","读书心已懒，高卧腹便便。"]},{"t":"予有书閤仅容膝东有隙地初甚荒芜偶于暇日理成小园径以通之杖藜日涉于其间几欲成趣然花木萧疏不足播之吟咏谩赋十一小诗以记园中之仅有者时甲戌仲冬也 青青径","f":"五言绝句","c":["小径循园辟，青青草色都。","主人犹未仕，时得理荒芜。"]},{"t":"予有书閤仅容膝东有隙地初甚荒芜偶于暇日理成小园径以通之杖藜日涉于其间几欲成趣然花木萧疏不足播之吟咏谩赋十一小诗以记园中之仅有者时甲戌仲冬也 娟娟林","f":"五言绝句","c":["绕舍种脩竹，清风长满筵。","天姿本来净，不雨亦娟娟。"]},{"t":"予有书閤仅容膝东有隙地初甚荒芜偶于暇日理成小园径以通之杖藜日涉于其间几欲成趣然花木萧疏不足播之吟咏谩赋十一小诗以记园中之仅有者时甲戌仲冬也 扬扬畹","f":"五言绝句","c":["九畹何人种，光风泛国香。","林间今几许，鼻观日扬扬。"]},{"t":"予有书閤仅容膝东有隙地初甚荒芜偶于暇日理成小园径以通之杖藜日涉于其间几欲成趣然花木萧疏不足播之吟咏谩赋十一小诗以记园中之仅有者时甲戌仲冬也 鲜鲜砌","f":"五言绝句","c":["吾圃岂不富，黄金无数钱。","谁云何用好，霜里白鲜鲜。"]},{"t":"予有书閤仅容膝东有隙地初甚荒芜偶于暇日理成小园径以通之杖藜日涉于其间几欲成趣然花木萧疏不足播之吟咏谩赋十一小诗以记园中之仅有者时甲戌仲冬也 牡丹","f":"五言绝句","c":["人道此花贵，岂宜颜巷栽。","春风情不世，红紫一般开。"]},{"t":"予有书閤仅容膝东有隙地初甚荒芜偶于暇日理成小园径以通之杖藜日涉于其间几欲成趣然花木萧疏不足播之吟咏谩赋十一小诗以记园中之仅有者时甲戌仲冬也 芍药","f":"五言绝句","c":["十花称近客，千叶重维扬。","世上无姚魏，还他霸众芳。"]},{"t":"予有书閤仅容膝东有隙地初甚荒芜偶于暇日理成小园径以通之杖藜日涉于其间几欲成趣然花木萧疏不足播之吟咏谩赋十一小诗以记园中之仅有者时甲戌仲冬也 早梅","f":"五言绝句","c":["北陆寒未半，南枝春已回。","方于雪中种，便向雪中开。"]},{"t":"予有书閤仅容膝东有隙地初甚荒芜偶于暇日理成小园径以通之杖藜日涉于其间几欲成趣然花木萧疏不足播之吟咏谩赋十一小诗以记园中之仅有者时甲戌仲冬也 双竹","f":"五言绝句","c":["本是一根出，相期同化龙。","慎毋轻剪伐，云路定相从。"]},{"t":"予有书閤仅容膝东有隙地初甚荒芜偶于暇日理成小园径以通之杖藜日涉于其间几欲成趣然花木萧疏不足播之吟咏谩赋十一小诗以记园中之仅有者时甲戌仲冬也 紫微花","f":"五言绝句","c":["盛夏绿遮眼，兹花红满堂。","自惭终日对，岂是紫微郎。"]},{"t":"梅花次贾元识韵","f":"七言律诗","c":["南枝昨夜暖先回，压尽群芳独自开。","仙客风中飘素袂，玉妃月下试新裁。","未凭驿使殷勤寄，首辱新诗特地来。","明日雪晴须共赏，为花拚却饮千杯。"]},{"t":"岁暮雨雪连作稍阻会集贾元识有诗次韵","f":"七言律诗","c":["自从春色上孤根，淫雨经时步不前。","爱日未能供宿润，愁云依旧蔽青天。","溪山咫尺成千里，棋酒因循又一年。","今夕篮舆定相过，尊前行乐兴无边。"]},{"t":"万府君挽词 其一","f":"五言律诗","c":["东平隐君子，当以古人看。","孝却豺群易，恩全雁序难。","人如心画正，度胜酒肠宽。","粲粲三株树，门阑已壮观。"]},{"t":"万府君挽词 其二","f":"五言律诗","c":["老成嗟不见，里巷尚能谈。","衣解因周急，簪还务激贪。","蹶蹄心不愠，折翼泪常含。","瞑目应无恨，声名与佛参。"]},{"t":"万府君挽词 其三","f":"五言律诗","c":["吾母昔逃难，携孥依舅船。","态多朝暮警，恩独始终全。","滥与高门出，尤蒙长者怜。","未能成宅相，徒有泪如泉。"]},{"t":"林府君挽词","f":"五言律诗","c":["我昔游庠序，夤缘识令孙。","雅知苗裔远，更喜典刑存。","俗子犹迁善，偷儿最感恩。","佳城明日闭，堕泪满江村。"]},{"t":"表兄璐挺二道人以山茶一根见赠植于便便閤前每黑甜馀开窗寓目茗碗不捧精神自清因成小诗","f":"七言绝句","c":["一枕春眠到日斜，梦回喜对小山茶。","道人赠我岁寒种，不是寻常儿女花。"]},{"t":"又觅没利花","f":"七言绝句","c":["没利名嘉花亦嘉，远从佛国到中华。","老来耻逐蝇头利，故向椫房觅此花。"]},{"t":"二道人以抹利及东山兰为赠再成一章","f":"七言律诗","c":["西域名花最孤洁，东山芳友更清幽。","远烦丈室维摩诘，分韵小园王子猷。","入鼻顿除浮利尽，同心端与国香侔。","从今日讲通家好，诗往花来卒未休。"]},{"t":"觅海棠","f":"七言律诗","c":["好事高人重海棠，两株分植舫斋旁。","恰当燕子来时放，更向禅房深处芳。","道眼想应怜不俗，痴人何苦恨无香。","梅溪野叟曾经眼，欲觅一根栽草堂。"]},{"t":"郁师赠海棠酬以前韵","f":"七言律诗","c":["珍重高人赠海棠，殷勤封植弊庐旁。","固宜花里称名友，已向园中压众芳。","万树总含儿女态，一根独带佛炉香。","杜陵应恨未曾识，空向成都结草堂。"]},{"t":"札上人许赠山丹花且云此花三月尽开俟蕊成移去至上巳日以诗索之","f":"七言律诗","c":["人间花木眼曾经，未识兹花状与名。","丹却青山暮春色，续他红树堕时英。","梅溪野老栽成癖，莲社高人诺不轻。","小小园林绿将暗，早移芳蕊看敷荣。"]},{"t":"表弟津上人有瑞香抹利戏觅之","f":"七言绝句","c":["瑞香早入江南梦，抹利来从毗舍园。","久与道人同寂寞，不如来荐孔融尊。"]},{"t":"觅季仲权碧桃","f":"七言绝句","c":["红雨纷纷空自繁，碧云一朵胜桃源。","君家独有神仙种，分我闹花深处根。"]},{"t":"觅季仲达酴醾","f":"七言绝句","c":["名园羽盖谩童童，不似青虬出瓮中。","好事主人仍好施，定移韵友乞山翁。"]},{"t":"和宝印叔送春二绝 其一","f":"七言绝句","c":["潜涧园林幽更奇，送春归去有新诗。","风光流转身长健，又见明年花满枝。"]},{"t":"和宝印叔送春二绝 其二","f":"七言绝句","c":["青春不觉去堂堂，把酒谁分此日光。","偶读高人送春句，味回齿颊有馀香。"]},{"t":"族兄文通赠山茶","f":"七言律诗","c":["野性无端喜种花，吾兄得得赠山茶。","莺声老后移虽晚，鹤顶丹时看始嘉。","雨叶鳞鳞成小盖，春枝艳艳首群葩。","自惭欲报无琼玖，来往同看本一家。"]},{"t":"万府君挽词 其一","f":"五言律诗","c":["前辈风流久，之人尚典刑。","抱才虽汩没，种德自芬馨。","养浩眠龙穴，流光属鲤庭。","乡评推燕窦，所欠独年龄。"]},{"t":"万府君挽词 其二","f":"五言律诗","c":["太学称多士，奇儿占上游。","贤书连得隽，舍选复居优。","善教由狐突，兴家出万脩。","板舆游未遂，风树已萧飕。"]},{"t":"万府君挽词 其三","f":"五言律诗","c":["屈指吾乡党，如公今几何。","门犹毕万大，男类陆终多。","壮志埋蒿里，幽光发薤歌。","河梁嗟未就，遗恨满沧波。"]},{"t":"张廷直挽词","f":"七言律诗","c":["意气轩轩盖一时，林头周易造深几。","芹芳泮水声蜚早，花满河阳迹到稀。","方外客携因果去，道旁人汲义泉归。","柳川池馆规模壮，一夕花妖世已非。"]},{"t":"左原纪异","f":"词","c":["君不见温公年方髫龀时，奋然击瓮活小儿。","至今遗事在图画，活人手段良可奇。","又不见耿恭昔年困疏勒，孤城凿井踰千尺。","整衣一拜精诚通，俄顷枯泉飞为液。","乐清有地名左原，地幽井古知几年。","一朝陷溺谁氏子，万石压脑沉黄泉。","路隔幽冥生望绝，三宿沉魂岂能活。","鬼神莫救功莫施，天遣仁人为之出。","彩棒来临驱五丁，抉石求尸俄有声。","头颅半露语未辩，人疑鬼物相视惊。","拯溺辛勤功未果，土圮石攲纷欲堕。","争言陷者不复生，救者徒遭颓压祸。","梅仙恻然临井旁，焚香再拜祈彼苍。","散金募众蹈死救，手植板干加堤防。","土石相衔危不倒，齑粉馀生仅能保。","须臾夺命鬼窟中，万口欢呼喜填道。","翕然舆论咸奇公，异事行将达帝聪。","感物诚居耿恭上，活人手与温公同。","况公才学俱超绝，吏隐那能久淹屈。","使君前日飞鹗章，莅事详明己廉洁。","鲰生桑梓居此间，具书目见非妄传。","太史采诗傥见取，愿付银笔书青编。","将见大书特书屡书不止此，史笔芬香此其始。"]},{"t":"法灯俊上人惠杜鹃花","f":"七言律诗","c":["杜鹃嘉树状非常，久向缁林压众芳。","春去尚疑啼蜀魄，客来还错认丁香。","高人好事栽莲社，野叟移根植草堂。","习气未除端自笑，赏花衔惠意难忘。"]},{"t":"法灯闻上人和杜鹃诗酬以前韵","f":"七言律诗","c":["道眼相看颇异常，遥遥莲社有遗芳。","两篇诗好无蔬气，四季花然带佛香。","杖锡何时离竹径，寻山莫惜访槐堂。","小园花疏烦题注，诗往花来未可忘。"]},{"t":"孙先觉毋夫人正月四日生时年八十","f":"七言律诗","c":["蓂开四荚瑞新春，瓦弄幽闺应此辰。","蛇虺梦中祥女子，凤凰占里吉佳人。","平生不负三从义，老去兼全五福身。","他日奇儿亦黄发，捧觞犹得寿慈亲。"]},{"t":"明庆忏院上方地爽而幽盖精蓝之胜也予因会友托迹于其间一日探囊中得石刻诗一本乃王瞻叔国博先生题台人秀野堂也摹写景物颇类于此因置之壁间意有感触遂借其韵","f":"七言律诗","c":["下帷精舍远尘繁，境静心清事不关。","案上忘机有黄卷，眼中得趣是青山。","林泉欲共高僧老，事业未容吾辈闲。","准拟他年挂冠后，飘然杖履白云间。"]},{"t":"忏院种兰次宝印叔韵 其一","f":"七言绝句","c":["偶向缁林植子芳，光风入院泛幽香。","他时倘免芟锄患，馀馥犹堪供道场。"]},{"t":"忏院种兰次宝印叔韵 其二","f":"七言绝句","c":["不放凡花染道场，故栽芳友伴友郎。","一盘喜遇高人赏，却胜家园十八香。"]},{"t":"次济上人韵","f":"七言律诗","c":["老来未厌短檠光，又集青衿就故乡。","却荷道人能具眼，不同时辈有他肠。","心传潜涧源流别，首出新诗意味长。","我亦笔头为佛事，未应中国异西方。"]},{"t":"玄鸟至","f":"五言古诗","c":["昆虫方启户，玄鸟亦知辰。","去自盲风候，来逢化日春。","深条烟雨湿，广厦羽毛新。","故垒寻遗迹，雕梁拂旧尘。","早莺宜结友，秋雁不同宾。","嘉尔能知义，无忘旧主人。"]},{"t":"陈希仲赠山茶","f":"七言律诗","c":["都胜名花入小园，群芳无复敢争妍。","童童翠盖藏春色，艳艳繁灯照雪天。","青蕊似开吾辈眼，高标不染俗流钱。","此花端有岁寒意，好赋甘棠蔽芾篇。"]},{"t":"酴醾次贾元节韵","f":"七言律诗","c":["春山杜宇唤人归，归见酴醾满架垂。","叶底半开千颗白，鬓边斜插一枝奇。","园林绿树成阴后，亭院青春欲老时。","把酒对花歌数阕，濡毫更和鹿岩诗。"]},{"t":"觅海松赠僧希月","f":"七言绝句","c":["海石真宜植海松，青青不改四时容。","道人妙得栽培力，乞与书斋待化龙。"]},{"t":"浴佛无雨","f":"七言古诗","c":["俗言浴佛天必雨，今年浴佛天愈晴。","招提钟磬集梵侣，世尊尘埃思一清。","纷然膜拜口诵偈，举头看天红日明。","或云天意与佛拗，不放雨师龙伯行。","天虽不雨佛亦浴，误此亿万苍生情。","庙堂何人职调燮，劝天与佛无使争。","沛然一雨四方足，亿万苍生俱沐浴。"]},{"t":"喜雨用前韵","f":"七言古诗","c":["去年春夏人苦雨，今年春夏人厌晴。","水枯秧老农务急，霈然膏泽来太清。","小民易怨亦易喜，不知天意常分明。","何须频祷应上公，但起夏禹陈五行。","五风十雨尧舜世，自古天意缘人情。","今兹一雨荷帝力，龙神社鬼无妄争。","南亩有馀人意足，蚕已三眠更三浴。"]},{"t":"雨止复用前韵","f":"七言古诗","c":["水枯秧老农欲雨，麦黄桑绿蚕欲晴。","一朝大霈满四泽，云收雾扫天还清。","曰旸曰雨岂人力，圣德仰荷吾君明。","庙堂况无痴宰相，不怕泥泞妨牛行。","布谷催耕最知务，鸣鸠呼妇殊有情。","平原出水云吐日，阴阳得所无战争。","明日阳光照临足，今日阳乌已先浴。"]},{"t":"孟夏十有一日时雨初霁晨登高阁极目四望烟锁日出气象一新复用前韵","f":"七言古诗","c":["蝶梦惊回听残雨，鸟声唤起欣初晴。","梵宫烟火带馀湿，黉舍几席生微清。","披衣登阁忽四顾，顿觉远目增双明。","樵渔欸乃雾中出，舟楫荡漾田间行。","清和节物满眼界，柳垂暗绿花含情。","窗明几净日渐永，天开地廓阴不争。","俯视沧浪堪濯足，遥看扶桑观日浴。"]},{"t":"再用前韵勉诸友","f":"七言古诗","c":["蚕妇欲晴农欲雨，书生事业无雨晴。","况兹长日足可惜，薰风入户精神清。","虚窗文字遮眼暗，短檠灯火通宵明。","纸为良田力耕穫，一廛稼穑嗤许行。","太山北斗仰韩子，千态万状穷周情。","群居涵养务浑厚，藩篱剖破销纷争。","拭目天衢骧骥足，下视污池雀儿浴。"]},{"t":"颖师赠榧栽","f":"七言古诗","c":["自从儿时食火榧，思欲移根向乡里。","年来花木浪经心，品色徒多真戏耳。","道人赠我方外根，不比寻常桃与李。","枝柯宛类秦大夫，功效端如使君子。","殷勤栽植同因果，众目纷纷等奴婢。","他年摘实荐新时，杖屦相从莲社里。"]},{"t":"月上人以拳石植海松莳菖阳于四际苍姿秀色钟清气于几案间以为梅溪之野人赠兼惠诗章因与酬唱凡四首 其一","f":"七言律诗","c":["苍苍千尺大夫松，不似湖嵌植小茏。","枕水一拳形崒嵂，凌云三干色尨茸。","王衡星化姿兼茂，莲社诗高席可重。","乞与书窗端不恶，萧然如对德人容。"]},{"t":"月上人以拳石植海松莳菖阳于四际苍姿秀色钟清气于几案间以为梅溪之野人赠兼惠诗章因与酬唱凡四首 其二","f":"七言律诗","c":["处士何须种七松，剩栽海上绿髯龙。","灵根频灌苍如玉，黛色初抽软似茸。","蘸水小山形凿凿，引年昌歜节重重。","道人分得岁寒种，一洗梅溪憔悴容。"]},{"t":"月上人以拳石植海松莳菖阳于四际苍姿秀色钟清气于几案间以为梅溪之野人赠兼惠诗章因与酬唱凡四首 其三","f":"七言律诗","c":["禅杖西游睹万松，归栽九节伴苍龙。","何须偃盖藏龟甲，自可延年胜鹿茸。","赞老房幽看更好，昼公诗险和难重。","为师旦旦加浇濯，不遣尘埃上绿容。"]},{"t":"月上人以拳石植海松莳菖阳于四际苍姿秀色钟清气于几案间以为梅溪之野人赠兼惠诗章因与酬唱凡四首 其四","f":"七言律诗","c":["涧毛纤细荫青松，会见成仙与化龙。","孤屿两峰多臭味，一茎九节异香茸。","羡师得句侵澄观，顾我谈经愧叔重。","明日还家带沧海，园林小小可能容。"]},{"t":"忏院种红蕉用宝印叔韵","f":"七言律诗","c":["新植灵根续蕙兰，缁林佳处占清闲。","深红应费化工染，浓绿疑从帝所颁。","正色可曾娱俗眼，晚英犹足慰衰颜。","它年解组归三径，多种青青满故山。"]},{"t":"题佛阁三绝 其一","f":"五言绝句","c":["佛阁阅人久，儒官涉世疏。","伽蓝真长者，容我半年居。"]},{"t":"题佛阁三绝 其二","f":"五言绝句","c":["桑下不三宿，阁中经半年。","青山满庭户，虽好莫留连。"]},{"t":"题佛阁三绝 其三","f":"五言绝句","c":["灵运本狂客，偶来莲社游。","钟鱼听已厌，归去故园休。"]},{"t":"题郭庄路","f":"七言古诗","c":["南山有井名黄花，我卜别业临其涯。","酌泉漱石思往事，天遗景与名俱嘉。","东篱采菊隐君子，悠然凝望南山赊。","兹人高躅已千古，三径芜没堪咨嗟。","我生本抱丘壑尚，误涉尘世争浮蜗。","十年太学志未遂，归来陇亩躬桑麻。","草庄新筑亦不恶，青山远近光交加。","会须移住效杜老，终赋归去师陶家。","新凉入郊九日近，西风渐欲吹乌纱。","龙山风俗有故事，撩我清兴凌烟霞。"]},{"t":"率饮亭二十绝 其一","f":"五言绝句","c":["吾门非北海，安得客满坐。","有亭名率饮，邻里日相过。"]},{"t":"率饮亭二十绝 其二","f":"五言绝句","c":["苍头稍知耕，赤脚颇能酿。","有田俱种秫，我日坐亭上。"]},{"t":"率饮亭二十绝 其三","f":"五言绝句","c":["幽亭阔方丈，脩竹种千百。","有时人不来，影月为吾客。"]},{"t":"率饮亭二十绝 其四","f":"五言绝句","c":["富贵有天命，安贫士之常。","聊为真率饮，未用利名忙。"]},{"t":"率饮亭二十绝 其五","f":"五言绝句","c":["老去识交情，兴来怀酒伴。","山林车马稀，风月壶觞满。"]},{"t":"率饮亭二十绝 其六","f":"五言绝句","c":["文举客满坐，渊明酒盈尊。","虽无古高躅，妙意亦常存。"]},{"t":"率饮亭二十绝 其七","f":"五言绝句","c":["文字粗能饮，圣贤时复中。","林间十二子，宾主自清风。"]},{"t":"率饮亭二十绝 其八","f":"五言绝句","c":["富饮不解文，翁意非在酒。","三杯聊遣兴，一醉岂缘口。"]},{"t":"率饮亭二十绝 其九","f":"五言绝句","c":["我游醉乡中，常在软饱后。","谁脩醉乡记，添我姓名不。"]},{"t":"率饮亭二十绝 其十","f":"五言绝句","c":["吾家数兄弟，薄有古人风。","生计何曾足，酒杯无日空。"]},{"t":"率饮亭二十绝 其十一","f":"五言绝句","c":["我性野而率，山林谩求安。","有酒固可乐，无酒亦自宽。"]},{"t":"率饮亭二十绝 其十二","f":"五言绝句","c":["亭上可率饮，林间宜率吟。","每于诗酒里，寓我率然心。"]},{"t":"率饮亭二十绝 其十三","f":"五言绝句","c":["结交虽不泛，绝物亦何曾。","莫问亲疏客，过门无不应。"]},{"t":"率饮亭二十绝 其十四","f":"五言绝句","c":["交游聚散中，身世浮沉里。","观书悟昨非，把酒知今是。"]},{"t":"率饮亭二十绝 其十五","f":"五言绝句","c":["有酒或无客，有客或无酒。","何时此亭中，客酒两常有。"]},{"t":"率饮亭二十绝 其十六","f":"五言绝句","c":["是非何足论，时酒谩消遣。","但把无它肠，聊为在家善。"]},{"t":"率饮亭二十绝 其十七","f":"五言绝句","c":["灯火散交游，园林寄幽兴。","万事付无心，随缘不求胜。"]},{"t":"率饮亭二十绝 其十八","f":"五言绝句","c":["心向静中求，身宜闲处著。","閤已号便便，亭宜名莫莫。"]},{"t":"率饮亭二十绝 其十九","f":"五言绝句","c":["吾家老兄弟，杖屦日相过。","对酒欢无限，论诗味更多。"]},{"t":"率饮亭二十绝 其二十","f":"五言绝句","c":["有口但饮酒，无悰亦作诗。","它年宦南北，还忆在家时。"]},{"t":"横山连氏妻方奉姑甚谨姑死刻木像事之越十年不怠郡守张公子韶下车命诸邑访孝义予披牒至其家获观木像感叹不已因书四十字时绍兴丙子七月十四日也","f":"五言律诗","c":["纯孝世稀有，事亡人所难。","堪嘉里曾子，况有妇丁兰。","守令方尊礼，乡闾竞耸观。","名将闻帝阙，旌表及门阑。"]},{"t":"登姚奥岭望家山有感","f":"五言绝句","c":["昔年度兹岭，回首念慈亲。","如今望云处，惟有泪沾巾。"]},{"t":"题驿奥张店思周光宗","f":"七言绝句","c":["忆昔同行宿此村，重来堪叹止吾存。","芙蓉雁荡重经眼，旧事无人与共论。"]},{"t":"度雁山","f":"五言古诗","c":["雁山五经眼，兹行尤可观。","初冬天气佳，雁归山未寒。","有日照幽谷，无云翳层峦。","入境见祥云，振衣登马鞍。","瀑水飞玉龙，羽旗导翔鸾。","石柱屹天外，卓笔书云端。","灵峰观石室，杖屦穿巑岏。","山禽知我来，好音若相欢。","群峰列春笋，丹青状尤难。","行色愧匆匆，更约它时看。"]},{"t":"度谢公岭","f":"五言律诗","c":["十年九行役，屡经此山中。","爱山不厌观，每愧行匆匆。","大士瞻矩罗，骚人思谢公。","一生看不足，语如白头翁。"]},{"t":"腊日与守约同舍赏梅西湖","f":"七言古诗","c":["西湖处士安在哉，湖山如旧梅花开。","见花如见处士面，神清骨冷无纤埃。","不将时节较早晚，风味自是花中魁。","暗香和月入佳句，压尽今古无诗才。","武林深处景益胜，十里眼界多琼瑰。","北枝贪睡南枝醒，枝屦得得搀出来。","旅中兹游殊不恶，况有佳友衔清杯。","手折林间一枝雪，头上带得新春回。"]},{"t":"同舍再约赏梅用前韵","f":"七言古诗","c":["梅溪野人真野哉，老眼长为寒梅开。","朅来西湖探春色，濡毫一洗匈襟埃。","却将梅花比和靖，花与人物俱奇魁。","同行二十五佳客，一一尽是离骚才。","新诗一出花价长，糠秕桃李奴玫瑰。","湖山已槁处士骨，风月未厌吾侪来。","欣闻好事约重赏，准拟餐玉尝春杯。","预办长笺收白雪，载取十里清香回。"]},{"t":"前日探梅李元翁以疾不往和诗有玉华野人多病恼独守寒炉煨芋魁句复用前韵约同赏","f":"七言古诗","c":["西湖十里真佳哉，百花未放梅先开。","吾侪好事颇成癖，探春不惮冲风埃。","李生不出苦病恼，书阅肘后占河魁。","胆瓶相对数点雪，锦肠写出飘然才。","人如西湖有涵养，句与和靖争奇瑰。","重寻胜游有新约，湖山准拟诗仙来。","寒炉蹲鸱不必煨，为花痛饮拚千杯。","愿君及早理杖屦，莫令立马头频回。"]},{"t":"春日游西湖","f":"五言律诗","c":["山色绿如染，湖光青似磨。","峰高捧日久，波阔浸天多。","瑞气浮城阙，春光醉绮罗。","能将比西子，妙句有东坡。"]},{"t":"和韩秋怀十一首 其一","f":"五言古诗","c":["孟夏游会稽，禾稼方薿薿。","南风翼新苗，生意殊未已。","重来觉非久，相去百日耳。","黄云万顷空，蘋末凉风起。","园林亦摇落，触目成疑似。","人生过隙驹，朱颜何足恃。","胡为向迷涂，奔走不停轨。","得失无荣辱，归来实堪喜。"]},{"t":"和韩秋怀十一首 其二","f":"五言古诗","c":["草木无利名，时来自荣悴。","人生异草木，百念起心地。","困穷斯感伤，利达或骄恣。","一朝同物化，荣辱两何异。","有酒且行乐，不必富与贵。"]},{"t":"和韩秋怀十一首 其三","f":"五言古诗","c":["直道疾伊优，壮怀增靡曼。","海上豕方牧，夜中牛屡饭。","半生营一名，偃蹇未如愿。","青铜忽自照，白发已堪叹。","斥鴳适蓬蒿，大鹏抟九万。","物情贵得所，奚用求自献。","富贵似可喜，贫贱亦何怨。"]},{"t":"和韩秋怀十一首 其四","f":"五言古诗","c":["秋雨浸成潦，秋霜渐为凌。","老树喑寒蝉，腥盘集痴蝇。","天涯有归客，面目吁可憎。","吟馀自扪腹，肝胆空棱棱。","临渊不善渔，篱头挂寒罾。","数椽茅屋下，养此百不能。"]},{"t":"和韩秋怀十一首 其五","f":"五言古诗","c":["秋怀虫共悲，秋夜鹤同警。","辉辉玉绳低，耿耿银汉永。","静思凫舄乔，遐慕螭蟠猛。","途远慵著鞭，井深艰下绠。","鸟倦当知还，马失亦云幸。","穷通委天命，尘虑可深屏。"]},{"t":"和韩秋怀十一首 其六","f":"五言古诗","c":["客路厌繁暑，归怀惬新景。","枕冷梦自清，夜明窗更炯。","聊栖明月枝，胜逐西风梗。","支床甘自息，伏枥倦思骋。","惟有问目心，拳拳慕回请。"]},{"t":"和韩秋怀十一首 其七","f":"五言古诗","c":["窗几生新凉，灯火照初暗。","省己有昨非，探怀无宿憾。","古书恣掀翻，古意薄窥瞰。","心将游寂寞，语复攻苦淡。","实歉名忌浮，才疏得惩滥。","守志惧不坚，入道恐成暂。","性抑戒戕贼，心猿思系缆。","有友频琢磨，无官自校勘。","澹然学杨雄，不恨储无甔。"]},{"t":"和韩秋怀十一首 其八","f":"五言古诗","c":["贤关蔼多士，头角争轩轩。","中有倦游客，虚名厌驰奔。","学为忠与孝，思践阳城言。","高秋赋归去，戏舞庭闱前。","东园柿栗熟，采摘供盘餐。","兄弟各赋诗，集作棣萼编。","甲乙二孺子，日诵言半千。","学语三岁时，笑味生甜酸。","欣然动我怀，长夜不成眠。","归来有此乐，亦可终残年。"]},{"t":"和韩秋怀十一首 其九","f":"五言古诗","c":["吾庐有脩竹，滴翠凝不乾。","天风一吹拂，终夜鸣琅玕。","黄杨亦嘉树，一瓮何团团。","日暮飞禽归，啾然欲求安。","嗟予欲何为，屡涉吴江澜。","一名竟未就，举弹空飞丸。","对竹赏佳树，聊系予征鞍。"]},{"t":"和韩秋怀十一首 其十","f":"五言古诗","c":["商飙起何处，古树生秋声。","肃肃夜气寂，悠悠月华明。","兀兀念前古，孜孜殚寸诚。","默默守孤陋，兢兢防满盈。","兴至役诗匠，愁来驱酒兵。","自适布衣愿，未觉青衫荣。","长须与赤脚，亦足供使令。"]},{"t":"和韩秋怀十一首 其十一","f":"五言古诗","c":["鲜鲜霜中菊，谁云晚不好。","开日即重阳，虽晚亦同蚤。","对景便须醉，浮生苦难保。","胡为楚大夫，不饮致枯槁。","何如醉乡人，虽醉亦有道。"]},{"t":"和韩符读书城南示孟甲孟乙","f":"五言古诗","c":["性无有不善，兹言闻子舆。","学所以脩性，杨雄著之书。","欲知人之生，灵台湛然虚。","习善裕乃身，习恶丧厥初。","下惠与盗蹠，不生两门闾。","所趋一不同，相去霄壤如。","是以吾夫子，诗礼教伯鱼。","当时非义方，圣门亦萧疏。","我似杜陵翁，有儿最怜渠。","徒爱不知教，惧如驴与猪。","讵望登丹霄，折桂骑蟾蜍。","粗令有闻见，免为瓮中蛆。","丱角入小学，首诵仲尼居。","要知先孝弟，馀力哉乎欤。","我家素孤寒，金玉苦无储。","旧业止青箱，辛勤二星馀。","遗尔以清白，尔曹宜念且。","性情乃良田，学问为耘锄。","勿患远难致，跬步驰蹇驴。","勿忧年不逢，六经有新畬。","勿随奔竞流，伺候人庭除。","勿学田舍儿，黄金买冠裾。","在我能自脩，不患无声誉。","我久困笔砚，退思老山墟。","拭眼看尔曹，庶使愁肠舒。","诗篇和韩公，座右宜书诸。","青春最堪惜，勉矣无踌躇。"]},{"t":"和韩醉赠张秘书寄万大年先之申之","f":"五言古诗","c":["良友不易得，清谈苦难闻。","前夕知何夕，我来访诸君。","共对灯烛光，芳尊细论文。","通家忝孔李，促席联机云。","杯盘略荷礼，气味同清芬。","一盏洗穷愁，三杯话离群。","春舟会稽别，秋袂钱塘分。","顾我与三友，新当败孤军。","飘零各南北，对酒无复醺。","客况饱牢落，时光负氤氲。","聚散实堪恨，荣枯何足云。","归来已三月，俗状日纷纷。","幸此同一笑，盘餐饤腥荤。","蚝山荐巨房，龟脚烹脩裙。","良辰属严冬，败欢无蝇蚊。","痛饮竟长夜，高歌和南薰。","虽非韩孟张，所饮亦典坟。","何时脱场屋，南亩同耕耘。","昼为鸡豚社，夜策诗酒勋。","此言宜早践，勿待桑榆曛。"]},{"t":"和韩县斋有怀四十韵","f":"五言古诗","c":["读书窥古今，掩卷成叱咤。","唐虞昔垂衣，禹稷起躬稼。","人材各超绝，王业迭兴谢。","典谟光日月，雅颂蔼兰麝。","孟轲论易地，颜回堪并驾。","穷达虽殊途，圣贤实同价。","避就乡邻斗，泣笑疏戚谢。","甘心惟饮瓢，没齿不谈霸。","斯人嗟已亡，末俗遂多诈。","禄从枉道求，气为权门下。","争为邑犬吠，翻取猎师骂。","幽人思隐盘，高士欲耕灞。","予生苦多难，安迹殊未暇。","冬行皲两足，夜坐痹双髂。","黄卷徒自劳，青云未能跨。","借势乏王公，成名无仆射。","大学厌齑盐，亲闱疏脍炙。","眷眷日怀归，区区每求假。","飞同鹢过宋，闲若马归华。","陋巷怀哲人，短檠烧午夜。","对床有兄弟，通家足姻娅。","谈笑开芳尊，尘劳释征靶。","篇章日盈囊，卷帙时抽架。","咏歌同舞雩，叹息殊观蜡。","有田聊代禄，无谪不祈赦。","未为雄草玄，谩学愈苴罅。","啸傲穷朝曛，弦歌达冬夏。","头角姑自藏，齿牙谁肯借。","眠从弟子嘲，醉不金吾怕。","心知得失妄，眼见炎凉乍。","造物岂吾苦，交情勿渠讶。","马来未为福，火尽安足藉。","孝弟傥自脩，长幼必能化。","力耕西畴禾，剩种东皋柘。","旨甘奉盘餐，温凊饰台榭。","斗粟鉴汉谣，一爨共崔舍。","仰效慈乌哺，俯笑寒鸱嚇。","但令尊不空，莫厌客频迓。","风篁观掩冉，山禽听娇姹。","困穷乃吾幸，此祸不须嫁。"]},{"t":"和韩桃源图","f":"七言古诗","c":["嬴秦斩新开混茫，傲睨前古无虞唐。","诗书为灰儒鬼哭，李斯秉笔中书堂。","长城丁壮无还者，送徒更住骊山下。","避世高人何所之，出门永与家乡辞。","入山惟恐不深远，岂是得已巢于斯。","来时六合为秦室，未省今为何岁日。","吏不到门租不输，子长丁添更何恤。","春入山中桃自花，招邀隐侣倾流霞。","男耕女织自婚嫁，派别支分都几家。","谁泛渔舟迷处所，山开洞辟闻人语。","乍相惊问卒相欢，设酒烹鸡讲宾主。","可怜秦事已茫然，帝业初期万万年。","犹道祖龙长在世，岂知异姓早三传。","邻里殷勤争饷馈，人情与世无相异。","未信壶中别有天，却讶身游与梦寐。","山花乱眼鸟哀鸣，数日留连喜复惊。","更从洞口寻乡路，逢人欲话疑非情。","异日扁舟欲重顾，水眩山迷红日暮。","后来图画了非真，作志渊明乃晋人。"]},{"t":"和韩永贞行","f":"词","c":["君不见天为元和开号令，先遣憸人窃朝柄。","奉天难平闲虎貔，弈客待诏来京师。","口中班班谈治道，贞观开元何足为。","党与纷纷自标置，远借伊周供佞媚。","望尘附火皆美官，怨脩睚眦曾不难。","梯媒爵位由货赂，斥遂朝士因杯盘。","珣瑜卧第郢佑默，谁为唐室回狂澜。","朝攘利权未为怪，莫夺兵柄尤可叹。","仙李蟠根未当艾，十叶神器那容干。","禁中大义知谁主，东宫受禅同三祖。","越儿涕泣吴儿悲，从此豺狼不生羽。","刚明天子位初登，剪除元恶流凶朋。","八州司马才可称，节已扫地谁复矜。","子厚年少躁飞腾，身陷丑党罹熏蒸。","著文拟骚愁思凝，欲自辨白终莫曾。","王孙尸虫托骂憎，色岂不愧明窗灯。","所记先友时良肱，忍使柳氏家声崩。","吁嗟匪人何足凭，士勿妄进当战兢。","退之鲠直愤不胜，诗篇史笔两可徵，永贞覆辙宜痛惩。"]},{"t":"和韩短灯檠歌寄刘长方","f":"七言古诗","c":["我与君游最久长，短檠夜夜分清光。","初从乡校共牢落，晚入太学同凄凉。","眼看儿辈尽腾踏，尚磨铁砚穿藜床。","君今已作青云客，万言曾射天庭策。","蓝袍归拜七十翁，寿酒十分倾太白。","嗟予偃蹇只如前，日高空作卢仝眠。","乐事已输君自恣，银烛高烧环翡翠。","直形空腹旧时灯，墙角未应容易弃。"]},{"t":"和韩苦寒","f":"五言古诗","c":["羲和错冬令，寒燠常相兼。","在人为不常，时焉作贪廉。","玄冥当用事，如忌还如谦。","宜寒噤不嘘，群萌误抽尖。","既燠俄吹冷，夜寐黑不甜。","水行失其理，厥疾不可砭。","前日当孟冬，雷声震铜蟾。","三日辄大雪，飞花眩观觇。","逮此始踰月，屡变寒与炎。","晨起坐东窗，阳光快恩沾。","霜畦秀蔬苗，欣焉自腰镰。","顷刻变凛冽，枯藤怯提拈。","齿牙战霜风，缩舌疑衔钳。","架抽纷掀翻，谁能正牙签。","酒杯觉无力，瓶罄劳频添。","貂裘尚不暖，况无或衣缣。","兀坐拥黄紬，脰作寒龟潜。","气血粟肌体，涕涶冰须髯。","红炉炽薪炭，旋觉寒星歼。","静思天壤间，万类何繁纤。","路傍泣冻馁，海角愁废淹。","羽毛有不庇，腥血有不燖。","岂堪当此时，可以吾身占。","殷勤语妻子，汝勿多怨嫌。","破被尚禁絮，漏茅可添苫。","人生苟知足，处此意亦恬。","但愿王化行，东西俱被渐。","尧天日舒长，有目皆可瞻。","寒生在陋巷，甘心事齑盐。","何须傍人门，炙手随奸憸。","耽耽王侯宅，笙歌下珠帘。","寒暑止温凉，焉知有穷檐。","否泰迭往来，祸福相依黏。","勿用倚彼玉，自分安吾蒹。","饱腹日三饭，蔽形衣一襜。","祁寒勿怨咨，庶用惩无厌。"]},{"t":"和韩南食","f":"五言古诗","c":["海错千万族，惟蚝不能行。","潮来腹自饱，亦足遂厥生。","翻笑鱼蟹虾，晨夜何营营。","风味与江瑶，可以次第名。","荐身炮炙间，壳破材始呈。","北客昔南食，一见生怪惊。","故人居海滨，群鲜厌庖烹。","酷爱此味真，不假姜桂橙。","遥怜山间友，混迹黎与骍。","蔬肠久不饱，肌骨尪且狞。","巨房饷馋腹，一笑百念平。","岂为饮食欲，实见亲旧情。","谁知齑盐馀，盘餐味常并。","故乡实堪恋，未用图西行。"]},{"t":"和韩听颖师琴","f":"词","c":["七弦自相语，唱予仍和汝。","千指忽凄凉，骚人悲战场。","大弦温和小消越，惠风夷韵参悠扬。","琴瑟鸣寒泉，仪仪舞鸾凰。","山高水远听愈淡，花奴羯鼓声方彊。","施生幽雅士，不好笙与篁。","千金买焦尾，悠然坐藜床。","顾我非知音，感激涕自滂。","三听辄三叹，羲皇在我齑盐肠。"]},{"t":"和韩忆昨行示梦龄","f":"词","c":["忆昨少年气锐心未灰，平明出门薄暮回。","解衣换酒期必醉，乱花压面攲条枚。","年华荏苒今半世，触事往往生悲哀。","欢娱无复少年味，勉强谈笑陪尊罍。","饮才过量辄成疾，秋霜入鬓刚肠摧。","子年少我气鼎盛，琅玕夜诵声如雷。","匈中平时足蕴藉，颐神养素成婴孩。","松姿柏质异蒲柳，坚刚不怕霜霰漼。","凌云变化未可料，岂比嵲屼风中桅。","胡为郁郁乃如许，与我老者同虺隤。","岂缘心事未如愿，一念遂觉忧愁来。","还惊世态多险阻，忤意未兑生嫌猜。","壮怀千里力未致，龃龉翻类三足能。","伤和伐性致坎轲，两眉蹙恨凭谁开。","吾闻君子贵知命，数者于我何有哉。","又闻古人亦迍蹇，在易固有无妄灾。","闭门静坐养时晦，拂拭心镜捐尘埃。","他年定作仁者寿，齿背会见同鲵鲐。","圣贤遗训载子腹，此事宁不知所裁。","否往泰来固有日，坦涂利毂宁须推。"]},{"t":"和韩燕河南府秀才送周光宗","f":"五言古诗","c":["吾皇尚柔理，北客来输平。","投戈讲文艺，虞庠萃群英。","蔼蔼六年间，人物如西京。","菁莪各成材，龙虎巍标名。","东嘉号多士，半作鸿都生。","昭然藻鉴中，不负事业精。","先进日通显，天衢作雷轰。","后生益可畏，行艺方蜚声。","贤哉汝南丈，头角令人惊。","撑肠饱文史，欲振三年鸣。","偃蹇未如志，造物殊无情。","归来务遵养，绝意蜗角争。","高堂有慈亲，禄养须大烹。","壮怀不能已，千里提短檠。","掉头脱尘鞅，举翼摩太清。","贱子忝交末，平生荷推诚。","缅怀去年春，驾言共西征。","悠悠旧时路，君今独先行。","江梅弄春色，爱日烘新晴。","勿惮行役苦，会见归来荣。"]},{"t":"和韩答张辙寄曹梦良","f":"五言古诗","c":["故旧别云久，话言犹未聆。","岁暮念愈剧，宵长梦形频。","忆昔始倾盖，相看俱妙龄。","参乎方越席，鲤也才趋庭。","乐泮共采藻，泛江同食萍。","玄深探羲画，狂妄窥麟经。","端能辨箕荄，未省分雷霆。","卷帙发晨架，膏油燃夜棂。","君才富八斗，我字识一丁。","轻愿苦窘幅，高屋钦建瓴。","低头愿为愈，割席终惭宁。","结游指寥廓，约泛航清泠。","骥足骋天骏，鳌头缗海腥。","涂远困尘鞅，棹回阁寒汀。","壮怀誓白水，愤气干青冥。","孤屿散形影，双溪隔沧溟。","耿耿月遥共，悠悠门独扃。","论文忆李白，对酒怀刘伶。","乡校鼓沂瑟，颂章赓鲁駉。","濯暑振风袂，破寒操雪舲。","胜游仿栗里，雅会脩兰亭。","瓶罄沽瓮蚁，烛残照囊萤。","猖狂却大雅，酩酊还独醒。","槐市忽飞诏，英才先振翎。","短檠歌慷慨，长剑磨晶荧。","旧耻雪赤壁，奇功收井陉。","高价压群玉，新文丽繁星。","乡闾借光艳，庠序资仪刑。","随群袍暂白，唾手衫当青。","残生适孤苦，举足方伶俜。","文房泣遗泽，座右悲先铭。","犬马不填壑，凫鹥卒同泾。","射缟服彊箭，撞钟施寸筳。","惟求免场屋，讵望扬王庭。","师旋约奏凯，案就期脱囹。","势屈战徒力，命奇文不灵。","秋翼困燕雀，春苗害蟊螟。","日念返桑梓，愿言和鸾铃。","溪山有偕隐，风雨无独听。","悬崖踏苍翠，怪石穿珑玲。","豹闲眠雾窟，鸟倦栖云屏。","世情自翻覆，交态长芳馨。","岁时觉荏苒，咫尺如飘零。","盈亏屡瞻桂，开落频观蓂。","欲去废负米，念来方祝蛉。","何时掺子手，一笑空吾瓶。","注目杳云雁，缄书附原鸰。","鄙吝伫涤胃，钝顽资发铏。","得得戒徒驭，迟迟趋阙廷。","犹胜炙手辈，奔走趋公厅。"]},{"t":"己巳元日读韩送杨郎中贺正诗因和其韵","f":"七言律诗","c":["晓日五更鸡咿喔，银缸明灭烧馀脂。","家家呼牛逐耗鬼，牛归谁家鬼何之。","皇都朝会我无与，西畴春事行及期。","弟兄成行拜亲老，犹胜去年身未归。"]},{"t":"人日过电山随行有昌黎集因读城南登高诗遂次韵留别孙先觉","f":"五言古诗","c":["腊去梅已稀，阳浮柳初弄。","北斗新转梢，东风渐消冻。","为人节固佳，顾我身无用。","命驾访亲交，肩舆劳仆从。","门阑念久别，灯烛忻此共。","兴来酒自斟，欢至攲频送。","提壶劝衔杯，播谷催除葑。","农耕方迫归，行乐未能纵。","人生苦离别，俗状嗟倥偬。","春风桃李花，把盏何时重。"]},{"t":"和韩李花 其一","f":"词","c":["春风入园林，万卉以艳争相夸。","胡为此仙李，颜色憔悴堪咨嗟。","棱棱瘦树数点雪，半醒半睡风攲斜。","枯枝肤剥少生意，况有疥癣相孽芽。","不如免葵及燕麦，妍媚春色摇纤葩。","下自成蹊直虚语，谁肯顾盼留香车。","顾我逢春少行乐，老眼日有文书遮。","自怜衰飒已如许，那更对此愁人花。"]},{"t":"和韩李花 其二","f":"七言古诗","c":["皇都二月桃李盛，朱轮翠盖方纷拿。","东君世情亦太甚，十分春在侯门花。","试吟怨句问苍昊，一种春工何损加。","白华秉烛光照夜，此树不属孤寒家。","造化无言意潜告，我爱万物初无差。","物情禀受苦自异，奚有厚薄施萌芽。","劝君勿为花致怨，居易俟命思无邪。"]},{"t":"和韩答柳柳州食虾蟆","f":"五言古诗","c":["虫鱼千万族，一一异状貌。","飞潜同一性，巨细何必校。","彼微水中蛙，四足伛而疱。","自从科蚪初，生育在泥淖。","好鸣乃其性，非故欲喧闹。","蝈氏职洒灰，恐非圣人教。","吾闻人间世，生死同梦觉。","杀物伤吾仁，忍听声熚爆。","况我儒衣冠，弦诵生乡校。","彼亦呼子曰，有意欲吾效。","人虫各好生，奚用苦相挠。","退之惮食蛇，得得释笼罩。","子厚放鹧鸪，仁心亦稍稍。","胡为于此虫，未尽忘嗜乐。","荐祠用枭獍，穿阱诛虎豹。","古人岂妄杀，去害除不孝。","愿留兹鼓吹，驻我寒溪棹。"]},{"t":"伏牺 其一","f":"七言绝句","c":["太古民淳事简稀，圣人牛首号包羲。","如今四海皆人面，心似山川更崄巇。"]},{"t":"伏牺 其二","f":"七言绝句","c":["六画中含万象殊，洪荒一变遂归儒。","河图不授包牺氏，民到于今目尚涂。"]},{"t":"神农","f":"七言绝句","c":["民食腥膻鸟兽同，那知土谷利无穷。","后人只祀勾龙弃，谁念艰难起帝功。"]},{"t":"黄帝","f":"七言绝句","c":["百年功就蜕乾坤，鼎冷湖空迹尚存。","别有庆源流不尽，皇朝叶叶是神孙。"]},{"t":"唐尧","f":"七言绝句","c":["仁德如天帝业隆，四凶不去付重瞳。","当时黄屋如传子，千古那知楫逊风。"]},{"t":"夏禹","f":"七言绝句","c":["洪流浩浩浸寰区，民杂蛇龙鸟兽居。","长叹当时微帝力，苍生今日尽为鱼。"]},{"t":"启","f":"七言绝句","c":["尧舜与贤真可法，夏王传子若堪疑。","讴攲自属吾君子，不是当时禹德哀。"]},{"t":"少康","f":"七言绝句","c":["虞仍靡艾共输忠，一旅中兴复禹功。","较德宜优汉高帝，知音惟有贵乡公。"]},{"t":"桀","f":"七言绝句","c":["大禹辛勤造夏邦，子孙何苦事淫荒。","国亡不悟生平罪，翻悔当时不杀汤。"]},{"t":"成汤","f":"七言绝句","c":["大乙兴仁兽网中，鸣条一战遂成功。","归来犹自怀惭德，事与唐虞已不同。"]},{"t":"高宗","f":"七言绝句","c":["须信精诚可动天，高宗一梦得真贤。","济川不赖良舟楫，安得中兴五千年。"]},{"t":"纣","f":"七言绝句","c":["酿酒为池肉作林，深宫长夜恣荒淫。","何如早散桥仓粟，结取臣民亿万心。"]},{"t":"周文王","f":"七言绝句","c":["民疾商辛若寇雠，三分天下二归周。","文王终世全臣节，不念前时羑里囚。"]},{"t":"武王","f":"七言绝句","c":["八百诸侯会孟津，民心天意总归仁。","须知不食干戈粟，自有登山采蕨人。"]},{"t":"成王","f":"七言绝句","c":["姬旦推诚相幼冲，流言交乱出居东。","谁云王是中才主，一启金縢即悟公。"]},{"t":"宣王","f":"七言绝句","c":["北伐南征万国臣，中兴周室赖贤人。","崧高千古英灵在，何独当时降甫申。"]},{"t":"幽王","f":"七言绝句","c":["文武基图未易量，可怜中叶坏幽王。","神龙流沫生尤物，赫赫宗周一笑亡。"]},{"t":"秦始皇","f":"七言绝句","c":["鲸吞六国帝人寰，遣使遥寻海上山。","仙药未来身已死，銮舆空载鲍鱼还。"]},{"t":"二世","f":"七言绝句","c":["始皇一怒逐扶苏，天欲亡秦果在胡。","翻被四方黔首笑，不分鹿马是谁愚。"]},{"t":"汉高帝 其一","f":"七言绝句","c":["百战功成汉业新，咸阳置酒问群臣。","区区高起王陵辈，岂识龙颜善用人。"]},{"t":"汉高帝 其二","f":"七言绝句","c":["仗剑崎岖起沛丰，祇将嫚骂驭英雄。","虽然能用三人杰，已失商山四老翁。"]},{"t":"文帝","f":"七言绝句","c":["文帝兴王自代来，百金不费亦仁哉。","后人不务师恭俭，万户千门几露台。"]},{"t":"武帝","f":"七言绝句","c":["武帝英雄类始皇，甘心黩武国几亡。","晚年赖有知人术，解把婴儿付霍光。"]},{"t":"宣帝","f":"七言绝句","c":["道杂霸王非美事，治先刑法少仁恩。","盖杨韩赵犹诛死，谁谓当时狱不冤。"]},{"t":"元帝","f":"七言绝句","c":["德化欲遵周轨辙，刑名思革汉规模。","更生疏斥萧生戮，元帝何曾善用儒。"]},{"t":"光武 其一","f":"七言绝句","c":["大命由来自有真，子舆徒号汉家亲。","须知炎祚中兴主，元是南阳谨厚人。"]},{"t":"光武 其二","f":"七言绝句","c":["郁郁葱葱瑞气浮，南阳兵起再兴刘。","将军大敌非常勇，文叔平生本好柔。"]},{"t":"明帝","f":"七言绝句","c":["万乘临雍事老更，桥门亿万会诸生。","永平天子真儒雅，只恨容人度未宏。"]},{"t":"章帝","f":"七言绝句","c":["民苦繁苛厌永平，科除惨狱慰群情。","不穷窦宪欺君罪，翻被宽柔坏典刑。"]},{"t":"魏武帝","f":"七言绝句","c":["董吕袁刘电扫空，阿瞒独步骋奸雄。","岂知权备皆人杰，未肯全将鼎付公。"]},{"t":"吴大帝","f":"七言绝句","c":["拔刀斫案气如虹，独倚周郎立隽功。","一战果摧曹孟德，不妨高枕霸江东。"]},{"t":"蜀先主","f":"七言绝句","c":["曹公奸黠世无双，玄德雄才肯见容。","谁把荆州资霸业，一朝云雨起蛟龙。"]},{"t":"晋宣帝","f":"七言绝句","c":["四朝天子寄安危，寡妇孤儿岂忍欺。","见说五湖扛鼎日，又胜三马食槽时。"]},{"t":"晋武帝","f":"七言绝句","c":["早岁膺图帝业光，晚年何事政多荒。","算来不用平吴好，毕竟吴平速晋亡。"]},{"t":"元帝","f":"七言绝句","c":["金陵王气为谁钟，五马南浮一化龙。","四海民心共思晋，江东何事却从容。"]},{"t":"宋武帝","f":"七言绝句","c":["宋武英雄世莫加，长驱千里定中华。","乘机不据金汤险，自剖乾坤作两家。"]},{"t":"齐太祖","f":"七言绝句","c":["天厌金刀水德终，一时人望属萧公。","能论魏武周文事，独有区区谢侍中。"]},{"t":"梁武帝","f":"七言绝句","c":["不法先王治用儒，拾身倾国事浮屠。","堪嗟饿病台城日，曾得空王救死无。"]},{"t":"简文帝","f":"七言绝句","c":["青丝白马渡江来，宫殿酣酣尽委灰。","不解开门纳桃棒，空悲明镜不安台。"]},{"t":"陈武帝","f":"七言绝句","c":["一旦权臣外召君，已知天帝欲兴陈。","江淮若道无神物，谁报齐兵至寿春。"]},{"t":"后主","f":"七言绝句","c":["临春阁上醉流霞，狎客酣歌兴未涯。","江左半无陈日月，君臣犹听后庭花。"]},{"t":"魏道武","f":"七言绝句","c":["火举南征破弱燕，拓开中土奠山川。","功成若更能修德，自可延年度厄年。"]},{"t":"北齐神武","f":"七言绝句","c":["浮图入海天亡魏，鹦鹉兴谣运启齐。","邺下兵兴黄蚁死，营中星陨众驴嘶。"]},{"t":"齐后主","f":"七言绝句","c":["峨冠食禄鸡开府，摇尾承恩大郡君。","将士焉能死征战，盍驱尔辈赴三军。"]},{"t":"周文帝","f":"七言绝句","c":["传檄东征贺六浑，亲迎天子入长安。","剩栽沙苑千株柳，长使齐军破胆寒。"]},{"t":"隋文帝","f":"七言绝句","c":["孽后邪臣造衅端，房陵幽闭抱深冤。","一朝变起宫闱内，方信当时用妇言。"]},{"t":"炀帝","f":"七言绝句","c":["汴水东流岸柳春，龙舟南下锦帆新。","鸟声劝酒梅花笑，笑杀隋亡亦似陈。"]},{"t":"唐太宗","f":"七言绝句","c":["仁义谁云不可行，文皇亲见治功成。","德彝可惜身先死，岂信人间有太平。"]},{"t":"高宗","f":"七言绝句","c":["贞观基图极盛隆，谁将神器付昏童。","倒持剑柄归房闼，仙李枝柯一剪空。"]},{"t":"明皇","f":"七言绝句","c":["天宝君臣玩太平，梨园弟于奏新声。","贵妃一笑天颜喜，不觉胡尘暗两京。"]},{"t":"肃宗","f":"七言绝句","c":["张后宫中巧弄权，上皇西内老谁怜。","杜陵独念君臣义，长向云安拜杜鹃。"]},{"t":"德宗","f":"七言绝句","c":["虏箭侵陵御幄时，君臣相顾不胜悲。","难平犹自推天命，卢杞奸邪竟不知。"]},{"t":"宪宗","f":"七言绝句","c":["叛将连头就典刑，元和功业竟无成。","晚年误信妖人术，祸自丹砂药里生。"]},{"t":"文宗","f":"七言绝句","c":["辇路青青春草多，凭高无语涕滂沱。","禁中夜召词臣语，受制家奴可奈何。"]},{"t":"梁太祖","f":"七言绝句","c":["天下人心共恶梁，祇应无奈虎狼彊。","可怜千尺黄河水，投尽清流始灭唐。"]},{"t":"唐庄宗","f":"七言绝句","c":["十年征战不知劳，三矢功成意气豪。","自咤身为李天下，焉知祸起郭门高。"]},{"t":"晋高祖","f":"七言绝句","c":["玉帛和蕃辱已深，那堪割地侈戎心。","关南一陷腥膻后，遗患寥寥直至今。"]},{"t":"汉高祖","f":"七言绝句","c":["石氏君臣尽播迁，晋阳兵起据中原。","早知只有三年汉，何似捐躯报晋恩。"]},{"t":"周太祖","f":"七言绝句","c":["出镇雄藩势已危，拥兵乘衅袭京师。","谁知一代生灵主，元是雕青郭雀儿。"]},{"t":"周世宗","f":"七言绝句","c":["高平决战破刘旻，北取三关速若神。","大业未成天命改，殿前点检是真人。"]},{"t":"许由","f":"七言绝句","c":["肥遁箕山不可寻，高名不朽到于今。","尚留昔日洗耳水，为洗世人争竞心。"]},{"t":"后稷","f":"七言绝句","c":["洪水横流四海饥，教民稼穑务三时。","后王欲识艰难业，读取豳风七月诗。"]},{"t":"伊尹","f":"七言绝句","c":["穷居乐道自躬耕，那肯要君用割烹。","汤后不加三聘礼，未应改志为苍生。"]},{"t":"箕子","f":"七言绝句","c":["谏君不听念君深，被发徉狂自鼓琴。","千古共传箕子操，一时难悟狡童心。"]},{"t":"比干","f":"七言绝句","c":["谏君不听盍亡身，岂忍求生却害仁。","不向天庭剖心死，安知心异世间人。"]},{"t":"伯夷","f":"七言绝句","c":["避纣穷居北海滨，归来端为有仁人。","武王不听车前谏，饿死西山志亦伸。"]},{"t":"太伯","f":"七言绝句","c":["太伯高风不可追，雁行接羽共南蜚。","莫言断发便无用，犹有荆蛮慕义归。"]},{"t":"太公","f":"七言绝句","c":["隐迹磻溪七十馀，钓滩清浅鬓萧疏。","满怀韬略为香饵，只钓文王不钓鱼。"]},{"t":"周公","f":"七言绝句","c":["明堂摄政朝群后，四海流言孺子疑。","何事召公犹不说，丹心惟有鬼神知。"]},{"t":"召公","f":"七言绝句","c":["鼠牙雀角岂能欺，召伯聪明听不疑。","南国政成公已去，甘棠长结后人思。"]},{"t":"齐威公","f":"七言绝句","c":["诸侯九合霸图成，晋宋江黄尽会盟。","惟有召陵功最直，包茅不贡故来征。"]},{"t":"晋文公","f":"七言绝句","c":["逆旅栖栖十九年，五蛇夹负遂升天。","却惭不及齐威正，卿相由无管仲贤。"]},{"t":"宋襄公","f":"七言绝句","c":["小国争盟祸莫逃，托名仁义直徒劳。","杀人祭鬼宁非忍，犹自临戎惜二毛。"]},{"t":"秦穆公","f":"七言绝句","c":["秦穆平生善用兵，孟明三败始功成。","后人不识兵家势，异议纷从胜负生。"]},{"t":"楚庄王","f":"七言绝句","c":["周衰夷狄最跳梁，楚入春秋势更强。","能用一言存灭国，贤哉犹有一庄王。"]},{"t":"鲁隐公","f":"七言绝句","c":["唐尧授舜由天命，太伯奔吴避圣人。","鲁隐效颦端可笑，逊威不正自亡身。"]},{"t":"威公","f":"七言绝句","c":["菟裘有意身将老，社圃无端衅已萌。","篡鲁由来因羽父，过齐争奈遇彭生。"]},{"t":"庄公","f":"七言绝句","c":["先君出会不生还，鲁弱无由可报冤。","祢庙岂宜姜氏见，庄同何忍与雠婚。"]},{"t":"闵公","f":"七言绝句","c":["庆父哀姜产祸芽，龂龂鲁道可胜嗟。","武闱难起无人救，季子来归未足嘉。"]},{"t":"僖公","f":"七言绝句","c":["僖公能继伯禽风，盛德揄扬鲁颂中。","惟有春秋用王法，不轻一字曲褒公。"]},{"t":"文公","f":"七言绝句","c":["时无闰月那成年，庙有先君岂上贤。","鲁国从来秉周礼，文公何事独无天。"]},{"t":"宣公","f":"七言绝句","c":["东门无道敢欺天，过市哀姜语可怜。","和气致祥乖致异，如公自合大无年。"]},{"t":"成公","f":"七言绝句","c":["周室孤危若旅人，诸侯谁复肯来臣。","成公不是朝天子，假道京师会伐秦。"]},{"t":"襄公","f":"七言绝句","c":["侯伯谁修二霸公，大夫专政自襄公。","堂堂鲁国车千乘，翻在三家掌握中。"]},{"t":"昭公","f":"七言绝句","c":["昭公失国寓乾侯，方伯无人肯见忧。","如晋适齐徒取辱，祇缘不用予家谋。"]},{"t":"定公","f":"七言绝句","c":["春秋疆埸事纷然，齐鲁干戈几载连。","若使真儒长见用，来归何止汶阳田。"]},{"t":"哀公","f":"七言绝句","c":["诸侯失政陪臣僭，中国无君左衽专。","欲问哀公后来事，春秋书止获麟年。"]},{"t":"郑庄公","f":"七言绝句","c":["天地深恩讵可忘，寤生忠孝两俱亡。","身从何出翻囚母，国是谁封敢射王。"]},{"t":"齐襄王","f":"七言绝句","c":["诸儿帷薄可曾修，敝笱诗包两国羞。","何事春秋尤讳恶，祇缘能报祖宗雠。"]},{"t":"齐顷公","f":"七言绝句","c":["敌国行人讵可轻，等闲戏笑祸胎成。","胥闾竟日知何语，回首齐郊已被兵。"]},{"t":"邓祁侯","f":"七言绝句","c":["舅甥杯酒结绸缪，岂忍阴怀盗贼谋。","不听三臣言亦是，未须深罪邓祁侯。"]},{"t":"晋献公","f":"七言绝句","c":["齿发衰残志虑昏，谗兴妇口可心寒。","不知尤物能为祸，却为骊姬寝食安。"]},{"t":"楚灵王","f":"七言绝句","c":["章华台就国被繇，徵会诸侯意气骄。","楚众已离犹不悟，近臣徒为颂祈招。"]},{"t":"楚怀王","f":"七言绝句","c":["怀王误与虎狼亲，身死咸阳一旅人。","见说国人怀旧德，楚虽三户亦亡秦。"]},{"t":"吴王夫差","f":"七言绝句","c":["西施未必解亡吴，祇为谗臣害霸图。","早使夫差诛宰嚭，不应麋鹿到姑苏。"]},{"t":"越王勾践","f":"七言绝句","c":["机会由来贵速投，姑苏事与会稽侔。","谋臣不早麾兵进，尝胆徒劳二十秋。"]},{"t":"颍考叔","f":"七言绝句","c":["衣冠肉食谩纷纷，谁解杯羹感悟君。","颍谷封人虽贱士，却能纯孝至今闻。"]},{"t":"石碏","f":"七言绝句","c":["人情谁忍弃天伦，公独能将义灭亲。","何惜一时诛贼子，不妨千古作纯臣。"]},{"t":"孔父","f":"七言绝句","c":["春秋死难止三人，皆欲求仁未得仁。","节义可书惟孔父，胜如仇牧胜如荀。"]},{"t":"仇牧","f":"七言绝句","c":["春秋死难止三人，皆欲求仁未得仁。","仇牧捐躯为君父，不如孔氏胜如荀。"]},{"t":"荀息","f":"七言绝句","c":["春秋死难止三人，皆欲求仁未得仁。","荀息捐躯为私昵，也胜贼子与奸臣。"]},{"t":"祭仲","f":"七言绝句","c":["庶子虽贤宁夺嫡，人臣惟圣可行权。","区区祭仲何为者，卖国容身岂足贤。"]},{"t":"管仲","f":"七言绝句","c":["小节区区岂足羞，功名未显分累囚。","平生自有真知己，宁患威公怨射钩。"]},{"t":"大夫种","f":"七言绝句","c":["狩罢吴郊鸟兔空，果烹猎犬废良弓。","大夫自为知几晚，岂是陶朱计不忠。"]},{"t":"范蠡","f":"七言绝句","c":["久与君王共苦辛，功成身退肯逡巡。","五湖渺渺烟波阔，谁是扁舟第二人。"]},{"t":"李广 其一","f":"七言绝句","c":["李广才名汉世稀，孝文犹自未深知。","辍餐长叹无颇牧，翻惜将军不遇时。"]},{"t":"李广 其二","f":"七言绝句","c":["陇右英豪真有种，将军才气更无双。","功高不得封侯赏，祇为当时杀已降。"]},{"t":"娄师德","f":"七言绝句","c":["忤意由来勿校难，谁能唾面自令乾。","直须事过心平后，方服娄公度量宽。"]},{"t":"狄仁杰","f":"七言绝句","c":["武火方炎李欲灰，忠良何力可能回。","斗南人有擎天手，为向虞渊取日来。"]},{"t":"徐有功","f":"七言绝句","c":["狱兴罗织陷忠良，公亦几遭虎口伤。","蹈死救人人免死，论功何止汉于张。"]},{"t":"丁丑二月二十一日集英殿赐第","f":"七言律诗","c":["太平天子崇儒术，寒贱书生荷作成。","槐市育才叨舍选，枫宸唱第冠时英。","圣恩宽大容愚直，御墨褒嘉佩宠荣。","却笑刘蕡不遭际，徒令纸上有虚名。"]},{"t":"游天竺赠同年","f":"七言律诗","c":["雅会清时不易逢，吾侪今日此游从。","逼人英气湖光瑩，照眼恩袍草色浓。","文盛一时俱俊杰，名先千佛愧疏庸。","致身许国宜相勉，莫学平津但取容。"]},{"t":"赠阎同年","f":"七言律诗","c":["飘飘吴蜀两衰翁，尊酒论文偶会同。","名在儒科虽后我，言关国体岂如公。","休嗟世路多巇崄，共报君恩有朴忠。","此日游从足可惜，行将渭北与江东。"]},{"t":"阎和诗叙别再用前韵","f":"七言律诗","c":["我本东嘉田舍翁，登科偶与蜀龙同。","盍簪经月钦高谊，分袂令人念此公。","幕府可能淹俊杰，宸襟应亦记精忠。","他年揽辔游吴越，访我茅庐浙水东。"]},{"t":"赠梁同年","f":"五言古诗","c":["君家锦水边，我居浙江东。","各在天一涯，芳尊偶相同。","君方富青春，劲气吐长虹。","我老志亦衰，倚麻愧蒿蓬。","会合已踰月，周旋见高风。","久客思故乡，归心各匆匆。","赠君无别言，相期尽孤忠。"]},{"t":"次韵陈大监见赠","f":"七言古诗","c":["中兴天子尤崇儒，众贤汇进如联珠。","邹枚待诏萃金马，皋夔接武相俞都。","策士初期异人出，不尚虚文与声律。","况当盛世多贾生，晁错岂容为第一。","自惭俗学非名家，遗经独抱居东嘉。","齑盐太学浪十载，岂有文许时人夸。","刍言旅奏宸庭策，狂妄误蒙明主择。","生天偶在千佛先，材劣名浮有馀责。","颍川丈人诗绝奇，长篇勉我毋趋时。","欲报君恩答知己，胸中耿耿何当施。"]},{"t":"次韵刘长方司户见赠","f":"七言律诗","c":["枫宸昔羡君登第，莲幕今惭我效官。","相见可嗟头并白，老来自合量俱宽。","不嫌此日成名晚，最喜平生取友端。","待报君恩知死所，却同神武挂衣冠。"]},{"t":"陈大监用赏梅韵以赠依韵酬之","f":"七言古诗","c":["颍川丈人贤矣哉，青眼喜为清流开。","诗章翰墨两奇绝，笔下一字无尘埃。","品题人物奖后进，搢绅乐善公为魁。","东嘉贱子生太晚，犹幸识此真人才。","朅来西游也不恶，锦囊所得俱琼瑰。","区区科第何足道，此行似为诗篇来。","客中拜贶更重复，丙穴鱼及郫筒杯。","寒乡故旧问归橐，首言带得公诗回。"]},{"t":"大监复赠诗纸尾有留饭语再用韵以谢","f":"七言古诗","c":["平生漫学乎欤哉，心茅胸棘锄不开。","得公新诗一再读，便觉胸宇清无埃。","银钩妙画发光艳，照眼有如参与魁。","鲰生肺腑非太白，公似工部尤怜才。","旅中屡获锦绣段，但愧欲报无琼瑰。","豫章一榻不妄下，贤非徐孺安敢来。","荷公此意最敦笃，一笑当奉论文杯。","乡心如飞不可遏，更为长者迟迟回。"]},{"t":"谢荣帅赠御书孝经用陈大监韵","f":"七言古诗","c":["辇毂之下先弹压，兹言虽佳未足法。","丈人身居弹压地，抚字心劳民自洽。","神圣当天万物春，王畿共理嘉得人。","云汉昭回赐优渥，不特为公端为民。","圣经一章公独得，黄堂葱郁生春色。","贤哉名卿才大夫，匪懈事君端可则。","石刻分馀犹及我，荣耀惊闻浙江左。","从今蔀屋光属天，更有宠褒云八朵。","愿公勉为不朽传，长如治吴与治川。","要令列郡法青白，了无一吏横索钱。"]},{"t":"陈大监饯别用前诗珠字韵以谢","f":"七言古诗","c":["宸廷侥冒先诸儒，宠褒况获骊龙珠。","青衫黄牒拜君赐，红莲绿水官留都。","明日扁舟欲东出，访别长忧碍新律。","丈人呼酒如韩公，贱子愧非张十一。","酒阑未放客还家，活火煎泉烹叶嘉。","西来频下豫章榻，盛事当作还乡夸。","始终尚赖公鞭策，邪正途中知所择。","捐躯誓报明主恩，青史庶逃千古责。","况公自是人中奇，境邻吕望逢明时。","行持从橐奉清问，美恶愿分嫫与施。"]},{"t":"用陈大监韵谢王国录季羔见赠","f":"七言古诗","c":["吾宗神秀时名儒，赠我三百隋侯珠。","野人不识希世宝，但见照眼清而都。","我昔遥从雁山出，旅食贤关淹岁律。","雅钦陆子常患多，更叹张融可无一。","长淮久绝谁起家，青箱有君殊可嘉。","祠科得隽诮子厚，何止文许后生夸。","我拙惭无济时策，老境初官尚何择。","江南莲幕君故乡，窃芘聊逃简书责。","寒贱误蒙君见奇，祖别赠言荣一时。","明日东归诧闾里，五绝首称虞伯施。"]},{"t":"陈郎中赠韩子苍集","f":"七言古诗","c":["唐宋诗人六七作，李杜韩柳欧苏黄。","近来江西立宗派，妙句更推韩子苍。","非坡非谷自一家，鼎中一脔曾已尝。","丈人珍重赠全集，开卷烂然光焰长。","诗如此公固足贵，赐出仁者尤难忘。","兼金白璧不足道，愿宝兹集为家藏。","鲰生幸脱场屋累，老境欲入诗门墙。","古诗三百未能学，句法且学今陵阳。"]},{"t":"章季子赠端砚","f":"五言律诗","c":["有客赠端紫，刚方如正人。","裔传家万石，力助笔千钧。","磨铁嗟吾老，著书欣尔新。","何当与毛颖，相约侍严宸。"]},{"t":"次韵陈大监赴天申节宴","f":"七言古诗","c":["圣主仁心等南北，燧息边庭兵不宿。","两阶干羽来远人，大度端能包濮祝。","万岁三呼诞弥月，四海千秋太平曲。","宴开文德赐群臣，喜溢天颜明四目。","向来献寿人谁在，元凯重登共鲧逐。","武夷戎监老风骚，去国十年官始复。","捧觞首赋天保章，遥指南山祝君福。","更献曲江金鉴录，不但能歌连理木。","贱臣逢时最侥倖，归美宁辞管城秃。","愿同韩愈颂元和，兼美武公歌绿竹。"]},{"t":"谢李侍郎赠御书","f":"词","c":["君不见西京孝武称材雄，致治欲与唐虞同。","诏求贤良论阙政，翻取曲学公孙弘。","又不见文宗在唐号儒雅，制诏勤勤策群下。","刘蕡切直弃不收，卒使太阿归宦者。","吾皇策士亲临轩，不为故事求空言。","犹疑有司效冯宿，或恐前列登公孙。","九天赐下飞奎翰，照眼昭回悼云汉。","抑尚忠谀有训词，品题高下由宸断。","儒宗被命持文衡，银钩拜赐恩非轻。","归将乐石刊圣语，分贶下及狂愚生。","畎亩惓倦蓄忠愤，射策自惭言不尽。","它日倘陪鸳鹭行，愿效魏公摅底蕴。"]},{"t":"涂中得宝印叔二诗次韵 其一","f":"七言绝句","c":["十年行役厌间关，一第初收鬓已斑。","重念此生难报处，君亲恩德重丘山。"]},{"t":"涂中得宝印叔二诗次韵 其二","f":"七言绝句","c":["双亲不见不胜悲，衔恨何曾有住时。","二叔尚存俱白首，归来犹足慰衰迟。"]},{"t":"次韵宝印叔题壁二绝 其一","f":"七言绝句","c":["风扫园林万木残，道人眼界却宜看。","北窗趺坐对松柏，人物青青俱岁寒。"]},{"t":"次韵宝印叔题壁二绝 其二","f":"七言绝句","c":["早已心潜不二门，犹将土苴与人论。","未须只履西归去，且作人间老世尊。"]},{"t":"万府君挽词 其一","f":"五言律诗","c":["不废东平业，思兴毕万门。","短檠书自照，铁砚志长存。","冠玉贫宁久，兰亭秀更蕃。","一门今盛大，诗礼荷公恩。"]},{"t":"万府君挽词 其二","f":"五言律诗","c":["肯叹儒冠误，长随举子忙。","阿戎成雅志，小阮发幽光。","原冷鸰犹近，椿摧桂始芳。","老成嗟不见，犹记貌堂堂。"]},{"t":"致政宋承事挽词","f":"七言律诗","c":["兰玉盈庭戏綵衣，颜如童子寿期颐。","临行四绝胜四偈，遁世五休高五噫。","蓝袖晚沾天子命，芳樽首致使君词。","谁云汲冢藏书富，应愧无公千首诗。"]},{"t":"张德惠挽词","f":"七言律诗","c":["隐居高躅已茫然，潜德如公亦足贤。","早见乡评称孝子，晚闻诗史记凶年。","事殊伯道儿宜有，行过王圭庙已先。","满腹玄谈共谁语，九原归去访伊川。"]},{"t":"宿罗汉三绝 其一","f":"五言绝句","c":["梵舍十八所，道场皆矩罗。","兹独号罗汉，想应无漏多。"]},{"t":"宿罗汉三绝 其二","f":"五言绝句","c":["雁荡屡经眼，个中方再游。","何时脱尘鞅，来此饱清幽。"]},{"t":"宿罗汉三绝 其三","f":"五言绝句","c":["故乡从此去，借问几时还。","先自思兄弟，那堪宿雁山。"]},{"t":"游大龙湫和前韵","f":"七言绝句","c":["十年重到大龙湫，千尺新流胜旧流。","会见四方霖雨足，老龙还向此藏头。"]},{"t":"游灵岩辉老索诗至灵峰寄数语","f":"词","c":["雁荡冠天下，灵岩尤绝奇。","烟霞列屏障，日月明旌旗。","岩前有卓笔，可以书雄词。","天聪况非遥，?然听无疑。","愿起灵湫龙，霖雨行何为。","愿用真柱石，永支廊庙危。","愿煽造化炉，四海归淳熙。","愿招鸾凤友，朝廷相羽仪。","何人梦石室，妄诞夸一时。","那能了世缘，未兑贪嗔痴。","名山误见污，公议安可欺。","愿借灵湫水，一洗了堂碑。","诗以寄老禅，狂言勿吾嗤。"]},{"t":"题瑞岩","f":"五言律诗","c":["雁荡看不足，瑞岩游更贪。","斗奇虽有愧，蕴秀了无惭。","涧古水鸣玉，寺幽山染蓝。","匆匆一宿去，未暇问三三。"]},{"t":"题天台国清寺","f":"七言律诗","c":["十里松声接涧泉，清音入耳夜无眠。","宜于四绝中称绝，谁向三贤后更贤。","寺就已无陈日月，时清长是宋山川。","明朝杖屦寻刘阮，不待桃花入洞天。"]},{"t":"题大慈寺","f":"七言绝句","c":["巍岭迢迢入翠微，梵宫佛陇锁烟霏。","断碑古寺曾经眼，刚笑陈隋往事非。"]},{"t":"题石桥二绝 其一","f":"七言绝句","c":["路隔仙凡意可通，石桥容我踏长虹。","桥旁方广人游久，不在登临杖屦中。"]},{"t":"题石桥二绝 其二","f":"七言绝句","c":["石桥未到已先知，入眼端如入梦时。","僧唤我为严首坐，前生曾写此桥碑。"]},{"t":"万年赠乡僧贲老 其一","f":"七言绝句","c":["梦魂惊断石桥边，身带烟霞入万年。","宾主相逢意良厚，永嘉缝掖永嘉禅。"]},{"t":"万年赠乡僧贲老 其二","f":"七言绝句","c":["学通儒释浩无边，江浙声名二十年。","见说胸中有论语，欲从师向此参禅。"]},{"t":"过鉴湖","f":"七言绝句","c":["朔风吹水鉴湖寒，千里扁舟赴幕官。","路入蓬莱天尺五，眼中见日与长安。"]},{"t":"民事堂","f":"七言律诗","c":["亲擢深蒙圣主恩，宜知民事训词温。","仰惟睿意思邦本，要使书生识治原。","不惮勤劳驰禹会，敢忘精白奉尧言。","它时上问苍生事，愿竭孤忠慷慨论。"]},{"t":"腊月望日出郊探春游告成观谒大禹祠酌菲饮泉遂至龙瑞宫观禹穴薄暮而还","f":"七言律诗","c":["禹葬稽山不记年，丹青落尽庙依然。","神文秘在藏书穴，俭德流为菲饮泉。","龙瑞峰峦高近日，鉴湖烟水阔浮天。","东州佳处略经眼，自笑好奇如马迁。"]},{"t":"采蕺 其一","f":"词","c":["陟彼越山，言采其蕺。","我思古人，中心悒悒。","维国有耻，吴弗遑粒。","胆于坐隅，霸勋以集。"]},{"t":"采蕺 其二","f":"词","c":["陟彼越山，言采其茗。","我思古人，中心炳炳。","维国有耻，夕弗遑瞑。","焦心以思，沼吴之境。"]},{"t":"采蕺 其三","f":"词","c":["厥草匪甘，厥蔬匪香。","维其味之，岂曰嗜之。","心焉孔焦，胆焉亟尝。","唯其苦之，是以取之。"]},{"t":"采蕺 其四","f":"词","c":["我陟高岗，瞻望东越。","访王之祀，旷古有阙。","宜庙于山，世享不绝。","何以荐之，蕺茗是撷。"]},{"t":"秦望","f":"楚辞体","c":["瞻彼秦望，崇于会稽。","曷云其崇，登焉而紫。","孰登是山，西方之人兮。","瞻彼秦望，轻于会稽。","曷崇而轻，名之以嬴。","孰名是山，东方之人兮。","我登稽山，思禹之绩。","吾侪不鱼，繄帝之力。","我瞻秦望，哀秦之过。","虐彼黔首，其谁之祸。","禹驾而游，夏民以休。","有翼其行，稷卨是谋。","政辙而狩，嬴随以仆。","孰稔其恶，斯高左右。","孤竹兄弟，殍于首阳。","山与其人，嘉名孔章。","溪辱以愚，泉污以盗。","物之不幸，名恶而暴。","浙涛如银，鉴流如绅。","濯彼崔嵬，勿污以秦。"]},{"t":"迎春遇雪","f":"五言绝句","c":["飞雪送残腊，带花迎早春。","西畴农事及，愧是不耕人。"]},{"t":"元日冒雪赴天庆观朝拜既趋府拜表还舍饮屠苏酒因思去年元日亦不在家感而有作","f":"七言律诗","c":["幕府初官愧不才，琳宫朝拜获参陪。","篮舆去踏搀先雪，蓬鬓归衔最后杯。","禹穴地幽寒未歇，尧天日近暖先回。","年年元日身为客，孤负吾庐溪上梅。"]},{"t":"贺何正言用蔡君谟韵","f":"七言律诗","c":["御笔亲除真谏官，翕然舆论已腾欢。","正人得路言无讳，圣主虚怀听不难。","莫厌封章箴衮阙，要令奸胆落毫端。","鲰生雅服阳公德，时把昌黎谏论看。"]},{"t":"寓小能仁寺即事书怀","f":"七言律诗","c":["小国青径梅溪老，绿水红莲越幕宾。","药裹随身多半夏，花枝照眼只常春。","郡楼鼓角听殊远，僧舍钟鱼闻已频。","窗外清风数竿竹，澹然相对净无尘。"]},{"t":"同莫教授朱县丞朱司理游西园","f":"五言古诗","c":["黎明出城郭，偶作西园游。","春浅花未都，池寒绿初抽。","湖山欲纵目，烟霭浮不收。","初来兴非浅，心赏殊未酬。","赖有三君子，清谈洗牢愁。","更期春色浓，携樽泛仙舟。"]},{"t":"次韵濮十太尉赏梅","f":"七言律诗","c":["春向群芳顶上来，可人风味亦奇哉。","未于茅舍疏篱见，先为金枝玉叶开。","竹外横斜才数点，笛中摇落已千堆。","因公撩我惜花意，深忆去年湖上杯。"]},{"t":"题寿乐堂用东坡韵赠杨元宾佥判","f":"七言古诗","c":["蓬莱阁下苍龙古，万壑千岩拥仙府。","寿乐堂西面卧龙，壑月岩风满窗户。","苍松溜雨大十围，绿水浮荷深一股。","作堂主人久黄壤，仁智风犹似邹鲁。","诗仙骑龙已上天，妙句光芒照寰宇。","青山偃蹇只如昔，高处去天无尺五。","杨侯淮泗老儒学，文字撑肠笔风雨。","朅来赞幕古东州，要与青山作盟主。","虚堂宴坐饱风月，此外一毫端不取。","它日从公物外游，贝阙珠宫酌琼乳。"]},{"t":"元宾赠红梅数枝","f":"七言律诗","c":["江梅孤洁太绝俗，红杏酣酣风味薄。","梅花精神杏花色，春入莲洲初破萼。","胆瓶分赠两三枝，醒我沉痾不须药。","愿公及早办芳樽，酒晕冰肌易销落。"]},{"t":"廨舍有脩竹数竿潇洒可爱","f":"七言绝句","c":["谁栽窗外碧琅玕，潇洒尤宜老眼看。","寄语后人毋剪伐，更须时为报平安。"]},{"t":"龙瑞道士赠兰","f":"五言律诗","c":["有客赠芳友，满堂闻国香。","清含道流气，轻带羽衣黄。","缀佩风光别，横琴旨趣长。","重须寻禹穴，一曲听扬扬。"]},{"t":"吴秀才以寿乐莲洲中千叶梅花为赠酬以诗","f":"七言律诗","c":["东君次第染群芳，更与南枝别样妆。","水涨春洲浮鸭绿，日烘花脸带鹅黄。","雪中琼蕊不多办，酒后玉肌无此香。","玉润冰清总佳士，驿筒相继赠春光。"]},{"t":"上丁释奠备数献官书十二韵呈莫子齐教授赵可大察推","f":"五言古诗","c":["鲁人呼东家，陈蔡不火食。","当时虽高第，往往亦愠色。","孰知梦奠后，庙祀亘无极。","嵬然衮冕尊，王侯面俱北。","武成祭上戊，龙弃配社稷。","隆杀良不同，论功岂如德。","去载游上庠，观礼杏坛侧。","备乐阅九奏，银袍烂千亿。","兹焉客莲幕，滥与俎豆职。","登阶瞻睿容，炳睟若亲识。","壮哉芹藻宫，不减鲁侯国。","归赓泮水颂，才劣惭史克。"]},{"t":"会稽三贤祠诗 吴先生祠","f":"词","c":["安定先生贤矣哉，一时高第俱英材。","诜然达者播廊庙，贫贱亦足光蓬莱。","会稽吴君更超绝，至今士子犹能说。","讲堂鸣鼓规使君，可使清风耸朝烈。","求田问舍遗子孙，钱愚地僻何纷纷。","不惜池塘种芹药，一段奇事前无闻。","君不见唐室蓬山称贺老，乞得鉴湖归去好。","却将儒服变流沙，更遣门阑亦归道。","又不见晋朝名士高阳公，才名上下王谢中。","乃心欲出三界外，山阴宅化瞿昙宫。","先生识见高流俗，不作二公缘祸福。","寄语多才郑广文，乞与毫端记高躅。"]},{"t":"会稽三贤祠诗 旌忠庙","f":"七言古诗","c":["国家往往艰难中，搢绅节义扫地空。","靖康有一忠悯公，建炎独有唐侯忠。","唐侯爵位何曾隆，身居行伍侪罴熊。","平生经史漫不通，严霜烈日蕴在衷。","愤然一奋不顾躬，太尉夺笏嗟匆匆。","子房铁椎计已穷，张巡就缚气尚雄。","杲卿锯解骂未终，忠血义肉涂地红。","烈气英魂薄苍穹，事惊朝野闻帝聪。","立庙旌忠浙江东，睢阳双庙同高风。","名书青史等岱崧，当时开门谁纳戎，贻臭千古如蛆虫。"]},{"t":"会稽三贤祠诗 悯孝庙","f":"七言古诗","c":["我昔尝读黄绢碑，长叹越国无男儿。","孰知种山山下水，千载有此一段奇。","呜呼哀哉蔡孝子，风烈远过恢与羁。","乃翁白首困缧绁，半年不脱儿心悲。","请身荷械代父罪，或甘黥涅居军麾。","况遇兵兴击叛卒，身先矢石死不辞。","当时非无贤太守，孝子抱志终不施。","人间无路可赴诉，投命河伯祈天知。","自为铭志及讼牒，欲愬以魂赎以尸。","精哀意切语不怨，孝与忠厚俱天资。","临河更效结缨死，颠沛于礼曾无亏。","父脱累囚子愿毕，身在九泉甘若饴。","名闻九重获旌表，赐庙悯孝风华夷。","胡为祠宇乃如许，一间破屋河之湄。","未闻设诔有度尚，绝妙更欠邯郸词。","我来赞幕钦孝烈，顾瞻庙猊成吁嘻。","他年太史作佳传，愿于纸尾书吾诗。"]},{"t":"某比缘职事朝拜殡宫瞻望松柏怆然悲涕遂成小诗","f":"五言律诗","c":["崇观升平主，神游在九霄。","稽山嗟葬禹，寰海痛思尧。","天上仙宫别，人间宝祚遥。","微臣望松柏，魂思黯然销。"]},{"t":"鉴湖行","f":"七言古诗","c":["苍苍凉凉红日生，葱葱郁郁佳气横。","鉴湖春色三百里，桃花水涨扁舟行。","花间啼鸟传春意，声落行舟惊梦寐。","胡床兀坐心境清，转觅湖山有风味。","鉴中风物几经春，身在鉴中思古人。","禹迹茫茫千载后，疏凿功归马太守。","太守湖成坐鬼责，后代风流属狂客。","狂客不长家鉴湖，惟有渔人至今得。","日暮东风吹棹回，花枝照眼入蓬莱。","回首湖山何处是，欸乃声中画图里。"]},{"t":"禹庙歌","f":"楚辞体","c":["君不见蜂目英雄吞四海，血祀初期千万载。","稽山木像弃长江，逆溯波涛鬼无馁。","鸟喙辛勤十九年，平吴霸越世称贤。","故国无人念遗烈，山间庙貌何凄然。","马守开湖利源迥，岁沃黄云九千顷。","年来遗迹半湮芜，庙锁湖边篆烟冷。","吴越国王三节还，尽将锦绣裹江山。","自从王气熄牛斗，庙比昭王屋一间。","乃知流光由德厚，祀典谁能如夏后。","九年洪水滔天流，下民昏垫尧心忧。","帝惧万国生鱼头，锡禹洪范定九州。","功成执玉朝冕旒，奔走讼狱归歌讴。","南巡会稽觐诸侯，书藏䰠穴千丈幽。","蝉脱尘寰不肯留，千古灵庙依松楸。","吾皇盛德与禹侔，菲食卑宫恶衣裘。","思禹旧绩祀事脩，小臣效职躬荐羞。","仰瞻黻冕怀远猷，退惜分阴惭惰偷。","嗟乎越山高兮可夷而丘，鉴湖深兮可理而畴。","惟有禹贡声名长不朽，告成世祀无时休。"]},{"t":"与赵安抚乞疏狱","f":"七言古诗","c":["小麦青青大麦熟，秧老欲移蚕欲簇。","皇天弥旬作淫雨，害及农桑一何酷。","麦枯秧腐蚕不丝，无食无衣岂能育。","使君今世贤方伯，政过龚黄同舜牧。","僦金蠲放官与私，喜气欢声倾比屋。","仁风已慰黎庶心，诚感苍穹理宜速。","胡为烝泄尚如许，阴沴干阳埋日毂。","岂惟泥泞困牛车，更恐鱼龙上平陆。","闾阎竞画指日蛮，香火遥祈上天竺。","伤和无乃有冤民，蠹政尚疑多大族。","使君有术开青天，按劾奸赃疏滞狱。"]},{"t":"次韵濮十太尉咏知宗牡丹七绝 其一","f":"七言绝句","c":["忆昔洛阳花盛日，品第况逢欧六一。","姚黄一品价无双，更有左花千叶密。"]},{"t":"次韵濮十太尉咏知宗牡丹七绝 其二","f":"七言绝句","c":["月陂春色满花枝，国色天香照雪肌。","当日栽陪恐无地，如今谁保旧园池。"]},{"t":"次韵濮十太尉咏知宗牡丹七绝 其三","f":"七言绝句","c":["开元往事感伤中，遗种犹馀一擪红。","借问通宵配妃子，何如及早念姚崇。"]},{"t":"次韵濮十太尉咏知宗牡丹七绝 其四","f":"七言绝句","c":["春色遥兴洛阳念，风俗聊于记中验。","今日苧罗山下魂，犹向人间吐妖艳。"]},{"t":"次韵濮十太尉咏知宗牡丹七绝 其五","f":"七言绝句","c":["地近尧天饶雨露，花王窈窕多风度。","书生不办买花钱，空解摇毫为花赋。"]},{"t":"次韵濮十太尉咏知宗牡丹七绝 其六","f":"七言绝句","c":["香苞初拆晓霞凝，甲第名园冠绍兴。","玉叶金枝老诗伯，更将好语为褒称。"]},{"t":"次韵濮十太尉咏知宗牡丹七绝 其七","f":"七言绝句","c":["造化无私处处芳，家山想见亦春藏。","无端窃禄身为客，孤负吾庐十八香。"]},{"t":"送僧游径山","f":"七言古诗","c":["潜涧家风不芜没，禅讲诜诜尽瓜葛。","如今更有奇儿孙，云水飘然继衣钵。","径山禅伯僧中龙，向来名节真无双。","我昔题诗已推许，两度相逢不曾语。","子今此行真得师，扫除妄想叩深机。","我待衣冠挂林下，迟子归来话潇洒。"]},{"t":"三月晦日邵宪宴僚属于西园某与焉赵提干即席赋诗次韵","f":"七言律诗","c":["送春开宴种山西，翠幄重重眼界迷。","一段清和人共物，十分幽胜地临溪。","鸳鸿曲水阁中集，莺燕落花枝上啼。","贤榻获陪文字饮，不嫌踪迹间云泥。"]},{"t":"送昌龄弟还乡兼简梦龄","f":"七言律诗","c":["束书千里赴王畿，战艺贤关事偶违。","鉴水天高鸿雁集，左原山远鹡鸰啼。","夜床风雨客情恶，春草池塘诗思飞。","勉力还家对灯火，待看双桂擢秋闱。"]},{"t":"粜米行","f":"七言古诗","c":["诏书发廪周饥荒，使君减价粜黄粱。","奉行上意固已良，小人用心胡不臧。","㪷米大半杂以糠，横索民钱名贴量。","怨语嗷嗷盈道傍，我惭寸禄偷太仓。","见之不言咎谁当，言之人指为轻狂，作诗聊语同舍郎。"]},{"t":"送会稽林簿弃官还乡","f":"七言古诗","c":["望秦秦望山苍苍，未秋先作归意浓。","三山深处孟园好，松菊恨君归不早。","拂衣高举追冥鸿，不将诗别乖崖翁。","年来处士径尤捷，美秩清资等闲躐。","君独高歌慕隐沦，林下何曾见一人。","芋魁豆饭吾亦有，深愧折腰贪五斗。"]},{"t":"戊辰岁尝和韩退之赠张彻诗寄曹梦良至今十年梦良方和以寄因赠一绝","f":"七言绝句","c":["欲识交情久远期，十年方和和韩诗。","他时更践诗中语，偕隐溪山不可迟。"]},{"t":"送赵可大如浙西","f":"七言绝句","c":["幕府游从盛一时，之人襟宇更瑰奇。","西风莫作鲈莼恋，越国江山日要诗。"]},{"t":"中秋赏月蓬莱阁呈同官","f":"七言律诗","c":["中秋玩月小蓬莱，风送婵娟入座来。","樽俎论文清有味，湖山照眼净无埃。","云生脚底蛟龙卧，影落人间鼓角催。","把酒问天兼问月，何时此夜更衔杯。"]},{"t":"中秋见月方以为喜既而阴蔽意殊不满东坡云良天佳月即中秋不以日月断也诸君有醵会之约复用前韵","f":"七言律诗","c":["中秋玩月小蓬莱，云掩清光不放来。","颇觉襟怀增梗槩，欲凭栏槛扫氛埃。","清宵忍放嘉宾散，明日还惊俗务催。","底用区区校时节，良天佳月即倾杯。"]},{"t":"记梦","f":"五言律诗","c":["夜梦随先君，梅溪策黎杖。","杉径早开辟，归休预标榜。","魂思惊晓醒，精神发秋爽。","披衣照孤灯，洒涕书惚恍。"]},{"t":"士人僧道俱赠岩桂","f":"五言律诗","c":["岩桂来三家，清标共秋风。","联芳近禹穴，擢秀疑蟾宫。","胆瓶金粟妍，鼻观天香通。","无心妄区别，妙契将无同。"]},{"t":"府吏有以老求退者询其年犹未六十诘其去之由云欲全身避祸耳予善其知机勇退可以愧嗜进之士夫有感而作","f":"五言律诗","c":["升高蝜蝂堕，粘壁蜗牛枯。","搢绅鸩粱肉，是亦蜗蝜徒。","抽身箠楚中，勇退愧此胥。","衣冠与刀笔，未可分贤愚。"]},{"t":"观习水胜","f":"七言律诗","c":["汉武英雄思拓边，昆明习战遗风传。","吾皇仁心异武帝，思患姑为预防计。","尔曹生长行伍间，操舟习水便宜闲。","异日捐躯宜报国，勿效水乌为盗贼。"]},{"t":"龙瑞道士赠岩桂","f":"七言绝句","c":["岩桂遥从禹穴来，天香全似月宫栽。","金风凄峭飘龙脑，想见吾庐烂熳开。"]},{"t":"九日登蕺山","f":"七言律诗","c":["九日同登古蕺山，眼明天阔兴清闲。","杯传但觉欢无尽，帽落俄惊鬓已斑。","乡思遥驰三径里，秋声近在八松间。","茱萸未许陪朝士，赖有清流数往还。"]},{"t":"梦龄九日有诗兼怀昌龄次韵","f":"七言古诗","c":["长记去年今日好，门外秋香喷沉脑。","弟兄邻里同登高，把菊行觞乐非少。","山殽海错乡味佳，银瓶索酒不用赊。","醉中不记脱巾卧，明日头上犹黄花。","今年岂不欲行乐，窃禄东州官事束。","那堪送酒无白衣，旋粜黄粱买桑落。","何如与子俱休休，谁能长抱离乡忧。","移书问讯惠连弟，三径许我归来不。"]},{"t":"赠庄童子","f":"七言绝句","c":["日诵千言七岁儿，方员动静早能知。","还家更读韩公序，器业他年必大奇。"]},{"t":"送朱丞","f":"七言律诗","c":["一片秋怀似乱云，不堪行客话离群。","红莲绿水尚留我，钜竹老槐深忆君。","千里从今遥共月，一樽何日更论文。","好将平昔家传学，勉力登朝立世勋。"]},{"t":"赠梦龄兼怀昌龄","f":"七言律诗","c":["我缘窃禄寓东州，子亦相从千里游。","铁砚功名壮心在，短檠灯火夜窗幽。","治书晁错宜登第，射策公孙定取侯。","他日三人老兄弟，结庐相共保松楸。"]},{"t":"和梦龄十月朔日书怀","f":"五言律诗","c":["岁事遽如许，玄冥威欲伸。","地炉犹未火，客坐况无茵。","日短惊瞻昴，天寒怯报寅。","尤怜对床弟，尚与短檠亲。"]},{"t":"赠喻叔奇县尉","f":"五言古诗","c":["同舍同年友，天资迥不群。","诗文侵晋宋，兄弟类机云。","梅市访仙侣，兰亭怀右军。"]},{"t":"赠王吉老县尉","f":"词","c":["臣子大节孝与忠，父母仇雠天不同。","贤哉会稽王孝子，感槩有古烈士风。","松楸一夕盗破冢，亲获鼠辈闻之公。","有司守法贷其命，孝子衔恨无终穷。","谁谓书生胆如许，貌若尪羸中甚武。","手斩凶人提髑髅，请死申冤诣公府。","君不见齐襄内行世所羞，春秋贤之缘复雠。","又不见子胥鞭尸报父怨，太史为之作佳传。","君今枕戈志已伸，更须移孝为忠臣。","他年当作傅介子，誓斩楼兰雪国耻。"]},{"t":"十月望日买菊一株颇佳 其一","f":"五言绝句","c":["秋去菊方好，天寒花自香。","深怀傲霜意，那肯媚重阳。"]},{"t":"十月望日买菊一株颇佳 其二","f":"五言绝句","c":["菊晚不害好，固宜登我堂。","书生自头白，奚用泣馨香。"]},{"t":"闻诗生日","f":"五言古诗","c":["良天逢十月，嘉节过三元。","汝父初生子，吾亲喜抱孙。","长成今若许，气习有馀温。","雁序自相友，麟经可与言。","志宜存远大，学必探渊源。","但务勤修德，年龄不用论。"]},{"t":"十月十六日欲与梦龄弟及闻诗闻礼同游兰亭仍约喻叔奇偕行会天气不佳喻亦以疾辞出门而止兀坐终日怀抱殊恶","f":"五言律诗","c":["我欲游兰亭，天气殊不佳。","同行感微恙，杖屦不可偕。","出门兴遽阑，兹游竟未谐。","遗文阅永和，聊用慰此怀。"]},{"t":"和喻叔奇集兰亭序语四绝 其一","f":"七言绝句","c":["我自扁舟入越初，兰亭已向梦中如。","崇山峻岭至今阻，唱和诗成无处书。"]},{"t":"和喻叔奇集兰亭序语四绝 其二","f":"七言绝句","c":["群贤少长毕经过，曲水流觞忆永和。","一代风流已陈迹，世殊事异感伤多。"]},{"t":"和喻叔奇集兰亭序语四绝 其三","f":"七言绝句","c":["晤言一室许谁亲，相过无非我辈人。","放浪形骸嗟老矣，仰观宇宙尚艰辛。"]},{"t":"和喻叔奇集兰亭序语四绝 其四","f":"七言绝句","c":["茂林脩竹未成往，游目骋怀聊自欣。","畅叙幽情有齐契，一觞一咏细论文。"]},{"t":"和韩退之晚菊赠喻叔奇","f":"五言律诗","c":["嘉菊何太晚，十月才黄花。","既晚好何益，三嗅良可嗟。","开日乃佳节，芳樽对年家。","今夕苟不饮，如此黄花何。"]},{"t":"夜读书于民事堂意有所感和韩公县斋读书韵","f":"五言古诗","c":["宦游寓幕府，幽怀属山林。","兀坐窗几间，默求圣贤心。","沉潜偶会意，叹息常弥襟。","世涂岂能骛，古道聊自斟。","䰠穴思欲探，丹书未容寻。","青铜每自照，白发已见侵。","事业浩无穷，筋力愧不任。","丈夫固有志，宁在官与金。"]},{"t":"李资深赠古瓦砚及诗","f":"五言古诗","c":["世贵铜雀砚，常患伪乱真。","千金买渴雀，虚名何足珍。","李生心好古，身困道不贫。","得此佳陶泓，制由万道人。","慇勤持赠我，器古诗清新。","置之窗几间，日与毛颖亲。","未能草太玄，姑用注获麟。","罗文及端紫，贵幸无比伦。","屈尔居蓬窗，与我同艰辛。","研磨媚权贵，挥染劳精神。","兹我所不敢，铭以书诸绅。"]},{"t":"喻叔奇惠川墨","f":"七言古诗","c":["子墨客卿来自蜀，绣川家藏尤不恶。","明窗研磨出珠玉，客卿于君德良渥。","嗟予经年客莲幕，交绝方兄涩囊橐。","文房诸子亦萧索，同年于予契非薄。","特遣卿来助予学，不才拜赐心愧怍。","客卿之意殊不乐，陶泓毛颖登台阁。","陈玄待诏同著作，卿从予游失所托。","惟清惟静惟寂寞，但有诗篇日酬酢。"]},{"t":"戴夫人挽词","f":"七言律诗","c":["勤俭肥家福亦肥，晚年门户更光辉。","满庭兰玉俱蓝袖，照眼云仍尽綵衣。","方外客携因果去，月中人折桂枝归。","回头往事梦幻影，丹旐五云原上飞。"]},{"t":"和赵可大四绝 其一 僧舍雨中","f":"七言绝句","c":["僧居岑寂异官居，索句搜肠撚断须。","那更雨中思底事，梦魂归到种山隅。"]},{"t":"和赵可大四绝 其二 闻子规","f":"七言绝句","c":["杜宇声中春欲归，少陵老泪不禁挥。","与君共被浮蜗误，不似渊明早见几。"]},{"t":"和赵可大四绝 其三 不寐","f":"七言绝句","c":["唾手科名尚少年，无穷事业更居前。","辛勤不寐思经意，却笑边韶好昼眠。"]},{"t":"和赵可大四绝 其四 朝永祐陵","f":"七言绝句","c":["万壑千岩拥越冈，朝陵追念旧天王。","自嗟无路攀弓剑，尚忍兴言及虎狼。"]},{"t":"送黄机宜游四明","f":"七言律诗","c":["游宦东州识老成，坐间谈笑欲风生。","人如元祐气尤直，诗不江西语自清。","雪棹非缘寻旧隐，夜床端欲对难兄。","行闻太史奏星聚，四皓联珠临四明。"]},{"t":"卢仁及县丞挽辞","f":"七言律诗","c":["妙龄才誉冠东嘉，百战功成暮景斜。","人在卢前有惭色，礼从戴后独名家。","蓝田美绩谁能记，绛帐奇儿最可夸。","乡里搢绅官业冷，因公沦落倍兴嗟。"]},{"t":"赠术者","f":"五言绝句","c":["枉道贵何益，正涂穷亦荣。","谁辞谈义命，试问小君平。"]},{"t":"游天衣寺","f":"七言律诗","c":["拂晓篮舆出蠡城，稽山照眼鉴湖明。","千岩深处十峰好，万壑流中双涧清。","香霭嘘成普贤像，风松吹作法华声。","灵乌不肯来城郭，长伴高僧避宠荣。"]},{"t":"次梁尉韵","f":"七言律诗","c":["探春连骑入山城，更喜梅仙亦会盟。","文字偶同吾辈饮，圣贤满为使君倾。","诗逢好境天然好，山为清流分外清。","潇洒宗之最年少，我惭叨预八仙名。"]},{"t":"酬陆宰用梁尉韵","f":"七言律诗","c":["收拾湖山付管城，士衡独步张文盟。","涌泉诗思逼人捷，屑玉笑谈终席倾。","天色亦缘吾辈好，路人能道长官清。","要令巧匠镌山骨，记取同行八士名。"]},{"t":"和喻叔奇游天衣四十韵","f":"五言古诗","c":["稽山高入云，鉴湖阔浮空。","禹秦有馀迹，晋宋多钜公。","我来岁及周，梦寐怀清风。","兹欣天气佳，扶桑欲曈昽。","驾言天衣游，盍簪尽鸳鸿。","经夕戒行李，如期集仙宫。","联骑出城南，行行指秦峰。","千岩竞吐秀，眼界清无穷。","招提在何许，十里松阴浓。","林端忽钟磬，与客为先容。","群簪拥花界，双佩鸣寒空。","试将比天台，大略如思丰。","首读邑浩碑，妙理开昏蒙。","细观元白诗，丘壑罗胸中。","萧壁尚堪面，梁薪几经烘。","兹宫现有相，禅客谈无同。","朝阳最崭绝，白云抹其胸。","杜鹃天下无，至今映山红。","鸡僧始开山，道业闻清衷。","思举照不起，高价倾江东。","袈裟缕黄金，宫女自针工。","昭明亲抱送，礼意何太恭。","白马忽渡江，台城丧英雄。","国破遗衣在，丹青落尘容。","我辈皆书生，意气飘如虹。","蜡屐共寻幽，宁求香火功。","载酒怀贺老，招隐思戴颙。","赋诗效吹台，一饭敢不忠。","况我贤使君，德宇尤疏通。","楚醴饷百榼，白衣走山中。","嗟余何为者，天资愧倥侗。","谬与酒中仙，偶同蕺山松。","同年妙词章，况有山水供。","古诗如古琴，山高水溶溶。","背囊小奚奴，捧砚长须僮。","胜游与佳作，二美今具逢。","品题遍群英，波澜及孤踪。","掬水弄华句，比拟何凡庸。","兹会如兰亭，同行类荀龙。","盛事在诗史，奚用呼画工。"]},{"t":"州宅","f":"七言绝句","c":["鉴水稽山拥卧龙，黄堂人似坐仙宫。","风流惟有元才子，终日赋诗屏障中。"]},{"t":"蓬莱阁","f":"七言绝句","c":["祖龙车辙遍尘寰，只道蓬莱在海间。","空上望秦山上望，不知此处是神山。"]},{"t":"清白堂","f":"七言绝句","c":["钱清地古思刘宠，泉白堂虚忆范公。","印绶纷纷会稽守，谁能无愧一贤风。"]},{"t":"清白泉","f":"七言绝句","c":["圣人达节犹憎盗，志士清心肯饮贪。","试问卧龙山下酌，世间无似此泉甘。"]},{"t":"观风堂","f":"七言绝句","c":["薄俗浇风有万端，欲将眼力见应难。","但令心境无尘垢，端坐斯堂便可观。"]},{"t":"望月台","f":"七言绝句","c":["明珠遥吐卧龙头，渐觉清光万里浮。","人望使君如望月，要须如镜莫如钩。"]},{"t":"秦望阁","f":"七言绝句","c":["纸上观秦尚过秦，那堪山作眼中尘。","为言高阁登临者，莫作秦人视越人。"]},{"t":"望海亭","f":"七言绝句","c":["踏雪遥登望海亭，扶桑日上卧龙醒。","微臣望处非沧海，只望尧天万里青。"]},{"t":"卧龙山","f":"七言绝句","c":["鉴水连天仅可容，稽山照眼五云浓。","只忧旱岁无霖雨，谁识东州有卧龙。"]},{"t":"种山","f":"七言绝句","c":["决策平吴霸业成，青山长占大夫名。","子胥忠义无生死，怒气随潮到越城。"]},{"t":"竞秀阁","f":"七言绝句","c":["宪台高阁偶跻攀，万壑千岩指顾间。","山色元来本无竞，人心自是错看山。"]},{"t":"戢山","f":"七言绝句","c":["十九年间胆厌尝，盘羞野菜当含香。","春风又长新芽甲，好撷青青荐越王。"]},{"t":"八松","f":"七言绝句","c":["潇洒荀家好弟兄，秦封不污有馀清。","钟成一种栋梁气，散作八方风雨声。"]},{"t":"右军祠堂","f":"七言绝句","c":["欲吊右军千载魂，祠堂荆棘断碑存。","老僧相见话前事，问我兰亭几世孙。"]},{"t":"鹅池","f":"七言绝句","c":["鹢鹢能鸣异众禽，池边墨客最知音。","世间多是山阴妪，应恐误猜君子心。"]},{"t":"砚池","f":"七言绝句","c":["凤翥龙蟠字字奇，陶泓汤沐向斯池。","波心雨后一鱼跃，犹似当年吞墨时。"]},{"t":"题扇桥","f":"七言绝句","c":["右军一画千金重，妙意宁容市妪知。","明日重来堪一笑，管城那肯更临池。"]},{"t":"雷门","f":"七言绝句","c":["吴越兴亡事若何，谯门遗迹枕山阿。","大声曾作雷霆震，应笑人间布鼓多。"]},{"t":"曲水阁","f":"七言绝句","c":["王谢兰亭久寂寥，茂林脩竹自萧骚。","蒋侯近代风流守，曲水流觞意亦高。"]},{"t":"西园","f":"七言绝句","c":["西园风物冠东州，飞盖纷纷烂熳游。","惟有红莲幕中客，倚栏才得片时留。"]},{"t":"望湖亭","f":"七言绝句","c":["杖屦登临望鉴湖，湖中一半已湮芜。","谁能更继东都守，长使山阴水旱无。"]},{"t":"吴先生祠","f":"七言绝句","c":["右军宅化空王寺，秘监家为羽士宫。","惟有先生旧池馆，春风归在杏坛中。"]},{"t":"贺知章祠","f":"七言绝句","c":["贺老祠堂枕鉴湖，霓裳羽化宅荒芜。","无人更问君王觅，转使高风千载孤。"]},{"t":"鉴湖","f":"七言绝句","c":["胸中万顷元才子，方外孤标贺季真。","鉴水萦回三百里，风流何止两唐人。"]},{"t":"禹庙","f":"七言绝句","c":["越国遗民念帝功，稽山庙貌胜卑宫。","少陵莫叹丹青落，纸上丹青自不穷。"]},{"t":"菲泉","f":"七言绝句","c":["梵王宫近夏王宫，一水清含节俭风。","越俗不知王好恶，泉名却在酒名中。"]},{"t":"禹穴","f":"七言绝句","c":["好古贪奇司马迁，胸中史记越山川。","如今禹穴无寻处，洞锁阳明石一拳。"]},{"t":"马太守庙","f":"七言绝句","c":["会稽疏凿自东都，太守功从禹后无。","能使越人怀旧德，至今庙食贺家湖。"]},{"t":"吴越王庙","f":"七言绝句","c":["一剑功成三节还，尽将锦绣裹江山。","斗牛气灭英灵泯，庙比昭王屋一间。"]},{"t":"望秦山","f":"七言绝句","c":["洛思昔有人思洛，秦望今无客望秦。","回首长安在何处，谁能念彼下泉人。"]},{"t":"少微山","f":"七言绝句","c":["出郭舟行十里间，少微山近若蕡山。","山中处士已长往，一点客星云外闲。"]},{"t":"梅梁","f":"七言绝句","c":["结实几调商鼎味，成材宜作禹祠梁。","世间何岁无风雨，铁锁无端误见殃。"]},{"t":"窆石","f":"七言绝句","c":["越俗流传素可疑，禹陵窆石果何时。","只应便是专车骨，未可呼为没字碑。"]},{"t":"和昌龄弟见寄","f":"七言古诗","c":["经年游宦思家乡，枕间魂梦长飞扬。","瓯越相望数百里，鱼雁来往安能常。","水绿莲红王俭幕，我愧才疏笔常阁。","居官不事羡长卿，执一无权犹子莫。","昔年姜被今独眠，何时更作三珠连。","左原风物亦不恶，溪莼抽丝蕨吐拳。","阿连春草诗篇好，劝我归来宜及早。","代笠亭前烟雨中，共把锄犁宁待老。"]},{"t":"怀喻叔奇","f":"七言律诗","c":["结得贤关雁塔因，东州相遇益相亲。","凌云三赋我惭马，清唱百篇君胜秦。","冀北群空殊昔别，江东日暮倍伤神。","同年四百二十六，莫逆论交能几人。"]},{"t":"次韵周尧夫赠睡香","f":"七言律诗","c":["长向春前腊后开，要将风味斗梅魁。","名从庐阜梦中得，根自鄮山嘉处来。","风拆锦囊香不断，日烘宝盖翠成堆。","定须移向梅溪去，栽伴吾庐桂与槐。"]},{"t":"送陈元佐游四明","f":"七言律诗","c":["鉴水悠悠接鄮川，宦情客况两凄然。","扁舟乘兴梅花月，樽酒送行灯火天。","我似郑虔官舍冷，君如冯子主人贤。","虞庠春榜无多日，行看香名动日边。"]},{"t":"闻礼生日","f":"五言律诗","c":["桃水仲春月，蓂阶双荚生。","添丁慰卢老，小子庆徐卿。","禀得中和气，看成远大名。","青春已如许，勉力继家声。"]},{"t":"次韵赵观使鸳鸯梅","f":"七言律诗","c":["奴视纷纷晰与休，芳心那肯贮离愁。","结成冰玉岳湛侣，开伴纻罗施郑流。","影照婵娟如并卧，枝横清浅似双浮。","不知他日调金鼎，胜得樱桃气味不。"]},{"t":"亡友孙子尚藁葬会稽山大禹寺之侧某至官八日出郊访其墓不获明年春被命祀禹访而得之又明年春再往酹酒因植柏十根哭之以诗","f":"七言律诗","c":["畴昔相知似弟昆，那知半世死生分。","无缘更饮杯中物，想见能修地下文。","有愧乘车葬元伯，仅同解剑吊徐君。","他年黛色参天处，是子会稽山下坟。"]},{"t":"子尚墓种柏","f":"五言绝句","c":["子尚乃如许，壮年坟已荒。","我来亲种柏，含泪待苍苍。"]},{"t":"郑夫人挽词","f":"七言律诗","c":["好溪太守非常好，慈母端如孟母贤。","熊胆调成真器业，鱼轩游遍旧山川。","颜间日有平反喜，方外时修香火缘。","身世九龄家万石，定应含笑向重泉。"]},{"t":"钱夫人挽词","f":"七言律诗","c":["忠孝之家女亦良，教传彤管有遗芳。","藁砧旧擢儒林秀，桂子新飘月窟香。","方拟鱼轩沾宠渥，遽惊风树变凄凉。","稽山鉴水青春暮，薤露声中恨更长。"]},{"t":"连月不雨农事失时府帅决狱廪饥德政动天霈然而雨某吟成律诗一章以贺","f":"七言律诗","c":["旱魃为灾罕似今，霈然一雨慰群心。","非关菩萨解为泽，自是使君能作霖。","躬虑滞囚冤尽释，广开义廪惠尤深。","伫公归国调元气，散尽愆阳与伏阴。"]},{"t":"次韵濮十太尉喜雨","f":"五言古诗","c":["去岁秋大水，民食方苦艰。","丁壮尚流离，而况白与班。","今春又不雨，事与安危关。","使符下列郡，呼雩舞童鬟。","投文责老龙，贪睡何痴顽。","我闻救灾术，乃在人事间。","兴师古有卫，决狱唐称颜。","年因吊伐有，雨送轺车还。","嗟此旱魃虐，和气知谁干。","半岁幸一雨，人心宁不欢。","麦秀禾可植，田里庶少安。","上纾当宁忧，吏责亦稍宽。","我家箫峰下，山长路漫漫。","东皋有先业，颇亦知艰难。","归耕愿及早，免起将芜叹。"]},{"t":"叔父宝印师往永嘉妙果院未期年而退弟子德纯住龙翔一日归省其师亦退居林下缁素挽留之乃遁于异郡不踰月间师弟子相继退休识者高之目为僧中二疏某窃禄将一考矣有愧二高僧因书一绝庶几他日或蹈其高躅云","f":"七言绝句","c":["挂冠林下近来无，谁谓僧中有二疏。","应笑红莲幕中客，故园三径已荒芜。"]},{"t":"寄黄簿","f":"七言律诗","c":["六一移书责司谏，聱隅闻命避徂徕。","兹风不作已久矣，吾子所为何壮哉。","在列诸公颜有愧，附炎群小胆应摧。","要须终始全名节，莫遣心随利禄回。"]},{"t":"次韵濮十太尉题禹穴","f":"七言古诗","c":["寰瀛三十六名郡，越在东南雄四镇。","宛委周回三百里，草木山川有光润。","秦山鉴水蕴秀异，人物风流夸汉晋。","传闻禹穴自太史，好古无人若为问。","杖屦飘然寻洞天，照眼千岩若攒刃。","细看盘石心愈疑，遐想丹书气犹振。","禹贡无传岂其阙，遁甲所书何足训。","彝伦叙自九畴锡，水土平繇五行顺。","洛书六十有五字，王业巍巍此途进。","八卷飞沉天与泉，兹说荒唐理难信。","吾侪去古恨大远，企首难窥禹墙仞。","穴傍有井清且甘，一酌端能洗骄吝。"]},{"t":"薛师约抚干召饭于圆通寺主僧瀹茗索诗","f":"五言律诗","c":["绿暗梅欲雨，风薰麦初秋。","官舍厌卑湿，僧庐访清幽。","儒餐惯蔬饭，道话便茶瓯。","鉴湖倘容觅，杖屦时来游。"]},{"t":"潘知县弟抚干和诗复用前韵","f":"五言律诗","c":["堂堂紫微公，气节横清秋。","风流属犹子，胸壑罗奇幽。","诗篇粲华萼，名字宜金瓯。","州县聊尔耳，行矣天池游。"]},{"t":"酬富阳张叔清县尉","f":"七言律诗","c":["尺素遥传到越城，入怀珠玉照人明。","登科雅服才名早，筮仕喜闻官业清。","空把交情对山色，要令音问续潮声。","匆匆作答无他语，莫羡人间势利荣。"]},{"t":"周德贻得子以钱果为贶仆不获为汤饼客贺之以诗","f":"七言律诗","c":["双鲤来从古嵊州，喜闻英物诞东州。","清和时节绿阴满，秀异溪山佳气浮。","分贶金钱意殊厚，欲为汤饼客无由。","乃翁指日身龙虎，况有奇儿气食牛。"]},{"t":"喻叔奇迎侍赴桐川榜其堂曰戏綵书来求诗寄题一绝","f":"七言绝句","c":["桐州綵棒暂宣威，首辟萱堂上寿卮。","堂上慈颜笑还语，老莱文采愧吾儿。"]},{"t":"女子生日","f":"五言律诗","c":["吾女何时见，薰风欲半时。","年龄今稍长，礼法要须知。","好读班姬诫，休吟谢女诗。","萱堂有慈母，淑德可为师。"]},{"t":"范文正公祠堂诗","f":"七言古诗","c":["堂堂范公真天人，配我仁祖为元臣。","材兼文武怀经纶，先忧后乐不为身。","上与夔卨相等伦，正色朝端批逆鳞。","三黜愈光名愈闻，一麾东游禹所巡。","作诗怀蠡祠季真，卧龙山麓井久湮。","绠而汲之清且新，堂于其旁记厥因。","名标清白垂不泯，规尔官师意谆谆。","洗贪濯盗思还淳，人亡迹在嗟己陈。","断碑往往埋荆榛，后人不识真天人。","但能日饮堂中春，使君好事贤且仁。","治民律己惟公遵，登堂感槩怀斯人。","刻石绘像扬清芬，丹青炳耀如麒麟。","凛然如生见如亲，躬修祀事率幕宾。","手酌寒泉羞涧蘋，一酌清我僚吏民。","再酌为国清簪绅，要将清白风无垠。","庶俾范公遗志伸，公乎为仙为明神。","为泽为瑞为星辰，当宁焦劳思若人，九原唤起清边尘。"]},{"t":"次韵梁尉秦碑古风","f":"七言古诗","c":["姬嬴遗迹存者希，世传石鼓稽山碑。","石鼓揄扬得韩子，文与二雅争驱驰。","秦碑夸大颂功德，埋没草莽无人知。","或言山顶石犹在，上有虎豹龙蛇螭。","神藏鬼护荆棘蔽，崖悬磴绝登无岐。","广文好奇穴探禹，梅仙喜事僧寻支。","我赞其行要亲睹，勿受世俗流传欺。","望秦秦望两崭绝，何山壁立东南涯。","礼碑屹植最高处，不知磨灭从何时。","剔苔扫墨了无有，模糊片纸亦足奇。","浓云霮䨴黯将雨，古木槎牙蟠老枝。","归来走笔出险语，诃政叱斯同小儿。","诗成得得写寄我，词严意伟法退之。","我闻秦人灭六国，酷若犬磔临江麋。","先王法为秦所负，负秦况有秦有司。","五经灰飞儒溅血，尧舜周孔何能为。","上蔡猎师妙小篆，奴视俗体徒肥皮。","东封太山南入越，大书深刻光陆离。","沙丘风腥人事变，鬼饥族赤谁嗟咨。","汉兴万事一扫去，惟有篆刻馀刑仪。","磨崖欲作不朽计，其如历数不及期。","蚩尤五兵纣漆器，人物美恶宁相疵。","我虽过秦爱遗画，南山入望频支颐。","不须峄阳访枣刻，不用迁史观雄辞。","虚堂默坐对此纸，闭眼暗想君勿嗤。","要知秦碑没字本，却类周雅无辞诗。"]},{"t":"府帅王公中秋宴客蓬莱阁分茶赏月于清白亭某以幕僚与焉坐上成二绝 其一","f":"七言绝句","c":["使君开宴小蓬瀛，幕客参陪亦与荣。","茗煮寒泉饮清白，酒斟佳月赏分明。"]},{"t":"府帅王公中秋宴客蓬莱阁分茶赏月于清白亭某以幕僚与焉坐上成二绝 其二","f":"七言绝句","c":["白发青衫老幕官，蓬莱秋月两年看。","兴来端欲乘风去，不怕琼楼玉宇寒。"]},{"t":"又和赵仲永抚干二首 其一","f":"七言律诗","c":["冰轮飞出暮云端，更向蓬莱顶上看。","端似虹桥玩金饼，绝胜华屋见银盘。","光浮酒面杯尤滑，清入诗肠句不寒。","又与鉴湖添胜事，一时宾主尽鸳鸾。"]},{"t":"又和赵仲永抚干二首 其二","f":"七言律诗","c":["千岩竞秀越王州，地胜钱塘与虎丘。","龙卧半天头吐月，鉴湖千里影涵楼。","宴开秋色平分际，人在蓬壶最上头。","不负良天更输我，此中此夜两年游。"]},{"t":"再和 其一","f":"七言律诗","c":["峥嵘高阁耸云端，万壑千岩坐上看。","八百里湖寒鉴瑩，二千年国卧龙盘。","金风吹面扫残暑，明月入怀生嫩寒。","见说神山正相偶，醉中端欲驾仙鸾。"]},{"t":"再和 其二","f":"七言律诗","c":["家在东嘉山水州，玉箫丹灶古仙丘。","两年秋月登蓬阁，千里乡心绕谢楼。","作赋端同比窗里，思归长咏大刀头。","与君何日脱尘鞅，杖屦逍遥物外游。"]},{"t":"又用看字韵酬赵仲永","f":"七言绝句","c":["红莲分幕忝同官，秋月扬辉并席看。","句好湖山添秀气，谈清齿颊带微寒。"]},{"t":"故参政李公挽诗三首 其一","f":"五言律诗","c":["一代高明学，三朝骨鲠臣。","淮南惮长孺，楚国忌灵均。","死尚忧王室，生宁问大钧。","姜山同岘首，千古泪行人。"]},{"t":"故参政李公挽诗三首 其二","f":"五言律诗","c":["方面功尤著，朝端气最刚。","身能缚元济，城不陷睢阳。","思奋少连笏，耻同袁盎堂。","永嘉瞻五马，遗爱可能忘。"]},{"t":"故参政李公挽诗三首 其三","f":"五言律诗","c":["公在南荒日，迹危名愈尊。","芝兰坐奇祸，瓜葛酝谗言。","斥去权臣力，生还圣主恩。","卫公精爽在，何用些招魂。"]},{"t":"九日与同官游戒珠寺用去年韵","f":"七言律诗","c":["九日重登古蕺山，劳生又得片时闲。","菊花今岁殊不恶，蓬鬓去年犹未班。","蓝水楚山诗兴里，鉴湖秦望酒杯间。","醉中同访右军迹，题扇桥边踏月还。"]},{"t":"显仁皇后挽词三首 其一","f":"五言律诗","c":["妫汭嫔天子，涂山毓圣人。","聪明配昭献，慈俭继宣仁。","汤沐宁私己，园陵不病民。","鸿休耀彤管，无复数娀㜪。"]},{"t":"显仁皇后挽词三首 其二","f":"五言律诗","c":["八秩年无憾，三仁谥有辉。","瑶池燕仙侣，窆石葬遗衣。","忽睹龙輴去，犹疑騩驭归。","圣情哀不尽，泪向禹陵挥。"]},{"t":"显仁皇后挽词三首 其三","f":"五言律诗","c":["代邸迎归日，炎图喜中兴。","解将天下养，惟有圣人能。","方庆朝长乐，俄惊望献陵。","寝园祗奉处，拥绋泪垂膺。"]},{"t":"胡氏挽诗","f":"五言律诗","c":["婺女生贤女，端宜配德星。","登堂饮姑乳，调胆教儿经。","子舍春犹盛，孙枝叶已青。","韩碑纪遗懿，彤管继芳馨。"]},{"t":"次韵喻叔奇追感去冬天衣之游","f":"七言律诗","c":["去年同会类高阳，蜡屐登临雅兴长。","可但山光向人好，更欣天气为吾良。","路经禹穴深怀白，目对秦峰远忆黄。","日线又添人正远，尺书千里慰相望。"]},{"t":"次韵刘判官见赠","f":"七言律诗","c":["箧藏诗墨尚澄鲜，长记东嘉共绮筵。","游宦俱为莲幕客，异乡重见菊花天。","谢池一别真成梦，鉴水相逢似有缘。","小小园林吾欲老，看君功业上凌烟。"]},{"t":"赵仲永以御茗密云龙薰衣香见赠仍惠小诗次韵","f":"七言绝句","c":["天上人回饼赐龙，香沾衣袖十分浓。","明珠照室光生艳，三绝全胜万石封。"]},{"t":"仲永再和三绝复和以酬 其一","f":"七言绝句","c":["间世宗英学海龙，交情尤为野人浓。","天香御茗分奇绝，尽是殷勤手自封。"]},{"t":"仲永再和三绝复和以酬 其二","f":"七言绝句","c":["手汲寒泉碾小龙，天香一炷满衣浓。","与君慷慨论时事，欲吐丹心上实封。"]},{"t":"仲永再和三绝复和以酬 其三","f":"七言绝句","c":["长记中秋踏卧龙，尚馀诗兴至今浓。","羡君豪迈如韩子，联句犹容李正封。"]},{"t":"寄题周尧夫碧梧轩","f":"楚辞体","c":["凤凰梧栖竹实食，胡为使之在枳棘。","开轩种梧高几尺，凤兮凰兮聊尔息。","莫羡风微燕雀高，一飞定展冲天翼。","览辉瑞世鸣朝阳，此梧长向人间碧。"]},{"t":"留别民事堂","f":"五言律诗","c":["二年宦东州，民事了无补。","俯仰愧斯堂，何以报明主。","故家萧峰下，归耕及春雨。","平生畎亩心，感槩聊自许。"]},{"t":"题双峰资深堂 其一","f":"七言绝句","c":["书生纸上诵糟粕，释子舌端谈葛藤。","道在湛然方寸地，不知深造有谁能。"]},{"t":"题双峰资深堂 其二","f":"七言绝句","c":["我到双峰寻宝月，为留一宿话资深。","但能造得儒宗语，便是能传佛陇心。"]},{"t":"题双峰资深堂 其三","f":"七言绝句","c":["雁山门户此中入，南北两峰相对尖。","我与林泉有盟约，问师觅取一峰潜。"]},{"t":"题双峰资深堂 其四","f":"七言绝句","c":["千峰已见见双峰，瓯越山川在眼中。","吾祖吹箫定何所，会须乘鹤访遗风。"]},{"t":"题双峰资深堂 其五","f":"七言绝句","c":["堂名石刻两俱存，令我深怀旧长官。","学道资深更深处，居安能使庶民安。"]},{"t":"宿灵岩赠长老敏行","f":"五言古诗","c":["篮舆谢公岭，杖屦矩罗室。","净名访维摩，一庵仅容膝。","寻僧画屏中，往往多八十。","平生看不足，灵岩最奇绝。","老禅蜀中来，心印传佛日。","脚力穷天下，称此为第一。","兹山昔未开，藏闭最深密。","倘不遇熙朝，造物肯容出。","孙公赋天台，胜地尚遗佚。","我欲续金声，愿借山中笔。"]},{"t":"己卯腊月七日解官离越十九日至家明年正月二日被命除秘书省校书郎卜以八日行书二十字","f":"五言绝句","c":["梅花照归眼，春色戒行装。","君命不俟驾，安敢怀故乡。"]},{"t":"次韵冯员仲正字湖上有作","f":"五言律诗","c":["瓯蜀异乡客，西湖同日看。","浪花随去棹，风絮逐归鞍。","水浸吴天阔，山涵佛界宽。","春光无限好，共愧缚微官。"]},{"t":"次韵赵仲永悠然阁","f":"七言律诗","c":["越绝山川深更深，不须登览自来临。","胸中丘壑忽相遇，眼底尘埃无复侵。","得趣早同彭泽径，把杯时赴广文襟。","知君指日归天禄，莫负平生阁上心。"]},{"t":"次韵皇子建王题明远楼","f":"五言古诗","c":["百尺崇珠邸，恩隆地更亲。","壮侔巢凤阁，危切饮牛津。","眼净全无碍，心明自不尘。","登高宜暇日，为善及良辰。","炳焕瞻宸画，沉潜味道真。","书中端得趣，笔下已如神。","语带江山好，名随栋宇新。","应怜天下士，蜗舍不容身。"]},{"t":"刘韶美辞试馆职","f":"五言古诗","c":["学问称博洽，向后无此刘。","太一然青藜，迟君天禄游。","给札试玉堂，故事久不修。","遴选先实才，闻之辄掉头。","我乃行秘书，肯随铅椠流。","三日扫虚室，伫想心悠悠。","张罗君不顾，窃食吾怀羞。","西风吹兼葭，倚玉嗟无由。"]},{"t":"再用前韵赠韶美","f":"五言古诗","c":["平生少相识，摸索能记刘。","东南小蓬莱，二年同宦游。","濯缨鉴湖水，佩兰以洁修。","自倚肮脏门，不撼富贵头。","西泛吴江澜，委身谩乘流。","回首望故乡，天高路遐悠。","慷慨君自喜，伊优吾亦羞。","乘桴倘有志，愿言呼仲由。"]},{"t":"次韵韶美送刘夷叔二诗 其一 悼夷叔","f":"五言古诗","c":["蜀山高岩岩，英物世非少。","青藜卯金子，高步绝云杪。","思苦鸣辄悲，词深谊难晓。","知音有古人，纸上自倾倒。","我昔贤关游，相逢粲衣表。","东归拜言赠，箧笥至今好。","重来已鬼录，魂魄蜀天渺。","蓬山访高躅，空舍不停绕。","定寻穷孟郊，相酬类双鸟。","莫作人间来，世路转难拗。"]},{"t":"次韵韶美送刘夷叔二诗 其二 赠韶美","f":"五言古诗","c":["西南有佳士，岷峨秀匈中。","标高语更妙，写出岷峨容。","青天道路难，冥冥慕蜚鸿。","翩然下人间，海阔洪涛舂。","寻幽入禹穴，杖屦谁相从。","万卷蟠腹笥，一榻眠禅丛。","时来访予语，自愧贤非戎。","世态冷处薄，交情淡中浓。","去岁鉴湖别，分甘老岩松。","行藏果谁使，离合情无穷。","田园有深约，耘耔当自充。","异时瓯蜀间，林下见两翁。"]},{"t":"皇子建王生日","f":"七言古诗","c":["黄花过后梅花前，云披爱日烘青天。","月良阴剥阳欲旋，蓂馀八荚时半千。","郁葱佳气烛星躔，帝子来从天日边。","淑质岐嶷貌端然，少亲师傅学问专。","六籍奥旨能心传，百家诸司咸穷研。","馀事翰墨工诗篇，平居为善心拳拳。","君亲忠孝尤两全，放远声色尘管弦。","明窗自结贤圣缘，吾皇知子能择贤。","断自宸衷爱不牵，九重一日丹诏宣。","欢声喜气溢幅员，愿王自爱思无愆。","仰佩天眷奉周旋，保持王体如临渊。","日亲端士远佞便，纸上兴衰鉴古先。","诞宸朱邸锡玳筵，鼎来福禄方绵绵。","不须丹灶求神仙，不用贝叶慕真诠。","诚存性尽万善圆，身与国寿俱千年。"]},{"t":"寄新历日与梦龄昌龄弟","f":"七言绝句","c":["老去惊看历日新，宦情尤忆故园春。","吾乡亲旧如相问，为道明年已五旬。"]},{"t":"送查元章二首 其一","f":"五言律诗","c":["圣主德宽大，小臣言激昂。","虏情殊未测，淮甸可无防。","直气思开日，寒威误陨霜。","芳姿等兰蕙，摧折更芬香。"]},{"t":"送查元章二首 其二","f":"五言律诗","c":["肝脑不自爱，精忠为上殚。","危言犯颜易，直道立身难。","去国名逾重，还家迹始安。","相将吾亦去，林下挂衣冠。"]},{"t":"秘书省后园脩竹可爱胡正字有诗次韵","f":"五言律诗","c":["不俗更嫌俗，风枝时拂墙。","青青映藜烛，细细杂芸香。","劲节老方见，清阴寒欲藏。","萧疏似吾辈，味向静中长。"]},{"t":"魏邦式通判挽词 其一","f":"五言律诗","c":["挺挺魏公后，重闻别乘贤。","有时同贞观，无地上凌烟。","雨足嘉禾穗，风清婺女莲。","吟魂招不返，遗恨越江边。"]},{"t":"魏邦式通判挽词 其二","f":"五言律诗","c":["耆旧嗟零落，公年又不长。","双旌空入梦，半刺横罹殃。","子舍三珠秀，吾乡一鉴亡。","平生可书事，椽笔有星郎。"]},{"t":"次韵程泰之正字雪中五绝 其一","f":"七言绝句","c":["幻玉蜚花湿帝城，蓬莱灯火冷中清。","人间草木旧相识，顷刻还惊面目生。"]},{"t":"次韵程泰之正字雪中五绝 其二","f":"七言绝句","c":["栖乌惊起天无月，化鹤归来顶不朱。","错认湖山作西子，眩人疑是玉肌肤。"]},{"t":"次韵程泰之正字雪中五绝 其三","f":"七言绝句","c":["点缀工夫巧更奇，昆崙玉果半葳蕤。","嗅梅咀雪欲肠断，况读高生人日诗。"]},{"t":"次韵程泰之正字雪中五绝 其四","f":"七言绝句","c":["预知禾麦定登场，六出搀先瑞众芳。","更喜江梅自萧洒，不缘摧压减清香。"]},{"t":"次韵程泰之正字雪中五绝 其五","f":"七言绝句","c":["卧闻征雁作回音，遥想吾庐玉满林。","乘兴扁舟定归去，草堂深处伴猿吟。"]},{"t":"泰之用欧苏颍中故事再作五绝勉强继韵 其一","f":"七言绝句","c":["君诗雅胜五言城，白雪篇章分外清。","不许同僚持寸铁，笔尖战退老书生。"]},{"t":"泰之用欧苏颍中故事再作五绝勉强继韵 其二","f":"七言绝句","c":["寒侵睡思那成梦，酒著衰颜误抹朱。","待诏先生应怯冷，餐毡使者可称肤。"]},{"t":"泰之用欧苏颍中故事再作五绝勉强继韵 其三","f":"七言绝句","c":["谷精蜚处人为日，冰鉴颁时律应蕤。","照耀元宵更盈尺，不容灯火占新诗。"]},{"t":"泰之用欧苏颍中故事再作五绝勉强继韵 其四","f":"七言绝句","c":["煮海神功不计场，逼真冷焰夺春芳。","东君深恐成堆积，急遣雷公唤阿香。"]},{"t":"泰之用欧苏颍中故事再作五绝勉强继韵 其五","f":"七言绝句","c":["夜静微闻折竹音，惊禽何处更投林。","寒生习气无繇扫，遥对湖山忍冻吟。"]},{"t":"赵仲永和东坡汝阴雪诗并举赵德麟赈济故事见示遂次其韵","f":"七言律诗","c":["不作秦人视越人，深怜里舍甑生尘。","恨无广厦容寒士，安得洪炉煖曲身。","草木照人俱有艳，珠玑满地不忧贫。","凭谁扶取浮云破，莫待功成始放春。"]},{"t":"次韵洪景卢编修省中红梅","f":"七言古诗","c":["不为怕寒贪睡迟，东君妙意端可知。","雪英零落眼界寂，放此孤瘦红南枝。","蓬莱更向逸远地，草木宁有夭饶姿。","冰容戏作桃杏色，醉脸雅与神仙宜。","江兄蜡友已前辈，黄生后出非同时。","丹心独与劲节侣，疏影共浸清涟漪。","骚人相顾最不恶，何用车马纷蚩蚩。","典衣莫惜共携酒，对华一展思乡眉。"]},{"t":"李德远寺簿敢言勇退今之古人也东嘉王某赋诗以高其行","f":"七言古诗","c":["吴山苍苍烟霭横，皇都日日春风生。","利涂捷径走轮毂，古道荆棘惟君行。","吴江洪涛拍天汹，万楫千帆日相踵。","六鳌入钓犹不归，急流知退惟君勇。","斜川胜事今临川，锦袍风月追谪仙。","芋魁豆饭吾亦有，脱屣有愧君翩然。","我辈情钟惜离索，为国惜贤情更恶。","江头送别春尚寒，回首冥鸿已寥廓。"]},{"t":"省中黄梅盛开同舍命予赋诗戏成四韵","f":"七言律诗","c":["照眼非梅亦非菊，千叶繁英刻琮玉。","色含天苑鹅儿黄，影蘸瀛波鸭头绿。","日烘喜气光烛须，雨洗道装鲜映肉。","此梅开后更无梅，莫惜攀条饮醽醁。"]},{"t":"送王嘉叟编修","f":"七言古诗","c":["上书请剑人未复，开口荐贤君又行。","堂上伊优笑绝倒，纷纷去国皆狂生。","搢绅敢言似庆历，风俗渐美如东京。","手揩老眼看除目，一迁一去知谁荣。","南昌别驾亦不恶，三王高阁寻宗盟。","吴江漫漫楚天阔，羡君一叶春舟轻。"]},{"t":"送陈阜卿出守吴兴","f":"五言古诗","c":["台阁辍名士，符竹分帝忧。","搢绅有清议，欲为朝端留。","才名四十年，肮脏成白头。","方开公道口，遽中谗人钩。","触邪孤壮志，敛惠施一州。","命义二大戒，能言亦能由。","去矣霅水清，孰障天下流。","愿言如季路，乘桴共公浮。"]},{"t":"次韵程泰之酴醾","f":"七言古诗","c":["青春果作堂堂去，啼鸟唤春春不住。","明珠万颗玉为钱，欲买风光嗟已莫。","蓬山地冷花木稀，祗有寒梅已先雨。","谁遣虬枝上高架，稍觉云阴覆行路。","雨馀景物犹未佳，叶底精神不多露。","鼻观疑闻班马香，姿比何郎更风度。","平生惜春如惜别，老眼待花如待哺。","幽亭相对止三人，草草杯盘为花具。"]},{"t":"送胡正字分韵得来字","f":"七言古诗","c":["武夷之山高崔嵬，武夷先生贤矣哉。","山中高卧似孤竹，颜苍节劲清无埃。","吾君养老过西伯，不远千里归乎来。","胸中万卷可医国，首荐廊庙真人才。","人言朝奏暮必逐，天颜独为忠言开。","崇文三馆不浪辟，端为天下收奇瑰。","平时论议即涵养，富贵岂以三缄媒。","西京老儒作符命，苍黄投阁良可哀。","何如皇朝有欧范，开口不惮干霆雷。","先生学力到前辈，一时盛事光麟台。","宸衷宵旰急忠谠，伫观前席延邹枚。","先生掉头竟不往，扁舟自载高风回。","道山游从尽英隽，顾我晚进宁容陪。","梅花满枝柳弄色，赋诗送别同衔杯。","吾庐三径亦荒草，松菊怪我何迟徊。"]},{"t":"四月四日祀赤帝于慈云岭净名寺祀毕游易安斋至江次送黄子升通判还乡","f":"五言绝句","c":["祀罢灯花喜，山游晓色新。","江头送归客，我亦是行人。"]},{"t":"送太学生徐易归天台","f":"五言律诗","c":["天台古仙山，药物固非一。","采之年可延，厥品惟参朮。","兹诚笼中物，不可亡一日。","良医苟能用，可治天下疾。"]},{"t":"章季子教授惠顾渚茶报以宣城笔戏成三绝 其一","f":"七言绝句","c":["春回顾渚雪芽生，香味尤宜秘水亭。","搜我枯肠欠书卷，饮君清德赖诗情。"]},{"t":"章季子教授惠顾渚茶报以宣城笔戏成三绝 其二","f":"七言绝句","c":["白齿新芽不出山，青囊谁遣到人间。","午窗惊觉还乡梦，纱帽笼头捧兔班。"]},{"t":"章季子教授惠顾渚茶报以宣城笔戏成三绝 其三","f":"七言绝句","c":["霅水书来寄叶嘉，中山人去代琼华。","定将绛帐铸人手，散出毫端千种花。"]},{"t":"赵仲永和胡正字竹诗见赠用韵以酬","f":"五言律诗","c":["忆昔游莲幕，获登君子墙。","蓬莱醉秋月，龙凤啜天香。","台阁子将集，山林予欲藏。","新诗似脩竹，风味更高长。"]},{"t":"张阁学挽词 其一","f":"五言律诗","c":["南渡已三纪，衣冠今几存。","伤心失遗老，回首慨中原。","去国权臣力，全躯圣主恩。","致君尧舜术，妙意托空言。"]},{"t":"张阁学挽词 其二","f":"五言律诗","c":["公在南昌日，含沙祸最奇。","语蜚无限谤，狱具不过诗。","天道何尝远，人心自太危。","盖棺公论定，盛德合丰碑。"]},{"t":"宝月师刻予旧题以寄因书二绝 其一","f":"七言绝句","c":["资深堂上偶留题，多谢高僧不扫泥。","更与慇勤琢山骨，恶诗传到浙江西。"]},{"t":"宝月师刻予旧题以寄因书二绝 其二","f":"七言绝句","c":["册府经年已倦游，梦魂随雁到峰头。","山中老宿如相问，为道归期不待秋。"]},{"t":"五月十八日去国明日宿富阳庙山怀馆中同舍","f":"五言绝句","c":["去国怀明主，离群念旧游。","翻令到家梦，终夜绕瀛洲。"]},{"t":"寄冯员仲","f":"五言绝句","c":["相见惟言去，吾今去已成。","著鞭先几日，不及送君行。"]},{"t":"钓台","f":"七言律诗","c":["汉高嫚骂四皓隐，周武干戈伯夷饿。","南阳故人幸无失，先生胡为亦高卧。","清风却在夷皓上，千古真能激贪懦。","客星夜向钓滩明，想像年时临帝座。"]},{"t":"严州龙门院满散天申节","f":"五言绝句","c":["棹弭龙门下，诚驰天阙边。","平生畎亩意，祝圣更惓惓。"]},{"t":"宿永康县黄塘店观稼有感","f":"七言绝句","c":["路入黄塘喜更疑，地名虽是里闾非。","眼中禾稼已如许，薄有田园宜早归。"]},{"t":"永康有岭名花锦被","f":"七言绝句","c":["要将山水替埃尘，六月还家不惮辛。","炎暑厌闻花锦被，清凉宜近竹夫人。"]},{"t":"舟中偶题","f":"五言绝句","c":["绿水客星濑，薰风婺女溪。","来寻处士隐，归向斗中栖。"]},{"t":"游石门洞","f":"七言律诗","c":["雁山饱见两龙湫，洗眼新观石洞流。","欲向故乡寻白鹿，先来仙隐访青牛。","破荒喜诵刘郎句，跻险思从谢客游。","天下林泉看未足，分将身世早休休。"]},{"t":"林明仲自梅屿挐舟招丁道济道揆张思豫及予同饮索诗坐间成六绝七月朔日 赠明仲","f":"七言绝句","c":["君家梅屿我梅溪，一笑相逢郡治西。","要使众山同对酒，芰荷香里具亲携。"]},{"t":"林明仲自梅屿挐舟招丁道济道揆张思豫及予同饮索诗坐间成六绝七月朔日 怀旧游","f":"七言绝句","c":["塘馀春草遥思谢，楼面苍陂重忆刘。","人昔共游今孰在，芦花飞雪上吾头。"]},{"t":"林明仲自梅屿挐舟招丁道济道揆张思豫及予同饮索诗坐间成六绝七月朔日 其一 赠诸公","f":"七言绝句","c":["五人二百六十五，尊酒相逢非偶然。","把手共为他日约，莫缘富贵负林泉。"]},{"t":"林明仲自梅屿挐舟招丁道济道揆张思豫及予同饮索诗坐间成六绝七月朔日 其二 赠诸公","f":"七言绝句","c":["遥岑出碧明双目，境入韩诗已饱参。","湖上轩窗对遥碧，新诗写出旧城南。"]},{"t":"林明仲自梅屿挐舟招丁道济道揆张思豫及予同饮索诗坐间成六绝七月朔日 题宋庄","f":"七言绝句","c":["地环碧玉轩窗瑩，舟入红云笑语香。","下笔惭无少陵句，老怀徒爱宋公庄。"]},{"t":"林明仲自梅屿挐舟招丁道济道揆张思豫及予同饮索诗坐间成六绝七月朔日 题西岑","f":"七言绝句","c":["西岑风物冠吾乡，十里烟波兴味长。","不用扁舟鉴湖去，馀生甘向此徜徉。"]},{"t":"次韵昌龄至乐斋读书","f":"五言律诗","c":["端慕颜回乐，真同陋巷居。","息心容膝地，得趣满床书。","檠短灯宵永，窗明日晷舒。","相看有脩竹，心为主人虚。"]},{"t":"宝印叔示诗且索碑刻以南明山六大字为献仍次韵","f":"七言律诗","c":["不才讵可登台省，早问君王觅闲冷。","聊寻商岭绮与园，未羡云台寇并耿。","挂碑满屋宁寮饥，嗜好与叔真相宜。","试寄南明六大字，想像年少西游时。"]},{"t":"宝印叔辩上人各赠瑞香花","f":"七言绝句","c":["小小园林意自怜，名花十八拟唐贤。","瑞香一种来潜涧，学士新添两少年。"]},{"t":"曹梦良自许峰来访留山间数日赋诗数十章复出四绝见赠次韵 其一","f":"七言绝句","c":["径荒犹有渊明菊，囊涩宁求季子金。","老矣此身何处著，入山惟恐未能深。"]},{"t":"曹梦良自许峰来访留山间数日赋诗数十章复出四绝见赠次韵 其二","f":"七言绝句","c":["谩有忠怀徒耿耿，恨无长策救元元。","张仪舌在知何用，莫莫休休且勿言。"]},{"t":"曹梦良自许峰来访留山间数日赋诗数十章复出四绝见赠次韵 其三","f":"七言绝句","c":["平生风义慕相如，笔砚从游二纪馀。","直许交情定金石，肯同馀耳但光初。"]},{"t":"曹梦良自许峰来访留山间数日赋诗数十章复出四绝见赠次韵 其四","f":"七言绝句","c":["与君连夕灯前语，胜读千年窗下书。","八斗文章千里足，未应低首掾桐庐。"]},{"t":"先人旧题东山墓亭三绝 其二","f":"七言绝句","c":["门枕青山户傍溪，青山流水助悽悽。","双亲既远神何在，对此追思独怨啼。"]},{"t":"先人旧题东山墓亭三绝 其三","f":"七言绝句","c":["新筑茅庐涧壑围，山光水色共依依。","野人不为闲中趣，谁会朝来与暮归。"]},{"t":"某辛巳秋归自武林省先陇遂修亭宇浚溪流因思先人旧诗已随屋璧坏矣尚能记忆遂追和 其一","f":"七言绝句","c":["残生无计可荣亲，一见松楸一损神。","惟有青山知此意，晨昏长戴白云巾。"]},{"t":"某辛巳秋归自武林省先陇遂修亭宇浚溪流因思先人旧诗已随屋璧坏矣尚能记忆遂追和 其二","f":"七言绝句","c":["重葺山亭浚旧溪，杖藜来往独悲悽。","追思四十年间事，风为哀号鸟为啼。"]},{"t":"某辛巳秋归自武林省先陇遂修亭宇浚溪流因思先人旧诗已随屋璧坏矣尚能记忆遂追和 其三","f":"七言绝句","c":["丘木森森已十围，满林清荫可栖依。","每忧樵牧伤松柏，游宦三年两度归。"]},{"t":"送万先之赴清湘教官","f":"七言律诗","c":["早岁声名满上庠，青衫今始赴清湘。","得官已晚岂宜冷，行路正难那更长。","平昔心期良不浅，异时官业可能量。","鹏程九万从今日，行见飞飞到帝旁。"]},{"t":"送曹梦良赴桐庐户掾 其一","f":"七言律诗","c":["年少论交老愈坚，交情尽在和韩篇。","短檠业共贤关舍，淡墨名同桂籍年。","筮仕暂为三语掾，摛词行践八花砖。","许峰佳谶亦聊耳，何止蓬莱山上仙。"]},{"t":"送曹梦良赴桐庐户掾 其二","f":"七言律诗","c":["鸡黍相寻岂偶然，论文尊酒荷留连。","秋风初送雁群至，乔木喜闻莺友迁。","劝我鉴湖行甚力，送君钓濑去无缘。","愿将清白师韩范，从此高堂有四贤。"]},{"t":"送曹梦良赴桐庐户掾 其三","f":"七言律诗","c":["需次家乡五载迟，便便腹笥愈添围。","才如子建岂论斗，性类西门能佩韦。","车马戒涂君欲去，田园迷径我初归。","男儿所尚惟名节，莫堕人间富贵机。"]},{"t":"十月朔日偶书","f":"七言绝句","c":["去年此日对清光，圣德能容一介狂。","言略施行非不遇，身虽疏外亦何妨。"]},{"t":"剪拂花木戏成二绝 其一","f":"七言绝句","c":["洒扫衡茅端欲老，剪裁花木自为春。","权门炙手非吾事，祇合丘园作散人。"]},{"t":"剪拂花木戏成二绝 其二","f":"七言绝句","c":["蔓草芟夷莫许侵，好花封植待成阴。","每于小小园林里，长抱惓惓畎亩心。"]},{"t":"小小园十月杜鹃花盛开有共蒂双头之异因以数语记之","f":"七言律诗","c":["一声杜宇啼春风，明朝绯挂千山丛。","岁寒此色岂易得，那更朵朵双头红。","共蒂联芳友于爱，一吐一含分次第。","造物私我小园林，此花大胜金腰带。"]},{"t":"题月师桂堂","f":"词","c":["道人以月名身，以桂名堂。","胸中负所有，志在丹霄旁。","冠巾倘可加，唾手得天香。","惜哉已世外，此志终莫偿。","山中作堂侔月窟，禅定吟馀思清越。","要令坐上生清风，须使心中似明月。"]},{"t":"十一月二日自金溪访钱用章于白石览山川景物之奇以东道之姓为韵","f":"词","c":["朝离文君故宅边，莫寻谢守旧行田。","黄羊先示神仙迹，白石俄开洞府天。","两派?峥鸣玉涧，一声欸乃钓鱼船。","王孙占得湖山胜，明月清风不计钱。"]},{"t":"同钱用明用章游白石岩","f":"五言古诗","c":["谢公好山水，得郡古东瓯。","造物惜佳境，雅志多不酬。","松萝蔽雁荡，烟霭埋龙湫。","行田经白石，不到仙山头。","寥寥数百年，天付黄冠流。","巍然万仞崖，壁立东南州。","谁将补天手，化出白玉楼。","两龛藏洞府，中有群仙游。","上通尺五天，下接三神洲。","飞泉落岩腰，碧涧鸣山陬。","群峰真培塿，沧海为渠沟。","隘视人间世，万象同蜉蝣。","我家雁山阳，崎岖厌经丘。","翩翩钱公子，呼我寻岩幽。","初惊小雨密，忽扫群阴浮。","杖屦穷巑岏，一洗尘埃眸。","山林有真乐，富贵何足求。","但愿乞二山，不愿万户侯。"]},{"t":"又书岩上","f":"七言律诗","c":["十里湖山翠黛横，两溪寒玉斗琮琤。","路从飞鸟上头过，人在白云高处行。","岩下行田谢康乐，洞中辟谷李先生。","凭栏不瞰人间世，转觉此心名利轻。"]},{"t":"屑玉泉","f":"七言绝句","c":["白石岩腰屑玉泉，佳名初自长官传。","浑疑齿颊冰霜论，终日霏霏落半天。"]},{"t":"李少和像","f":"七言绝句","c":["少和辛苦学飞仙，遗像今犹在洞天。","都似先生能辟谷，何须太守为行田。"]},{"t":"游东际","f":"五言律诗","c":["白石三峰下，悬崖七际流。","穿云来汩汩，朝海去悠悠。","石是谁家妇，龙居第几湫。","平生不行险，到此即回头。"]},{"t":"次韵宝印叔观海三绝 其一","f":"七言绝句","c":["载地浮天浩莫穷，气营楼阁耸虚空。","道人妙得观澜术，万里沧溟碧眼中。"]},{"t":"次韵宝印叔观海三绝 其二","f":"七言绝句","c":["榴屿何年改玉环，望中犹是旧青山。","遗民不记当时事，惟有潮声日往还。"]},{"t":"次韵宝印叔观海三绝 其三","f":"七言绝句","c":["误入蓬莱朝未央，至今魂梦记微茫。","扁舟欲效鸱夷子，遥望沧波兴已狂。"]},{"t":"李镇夫辟圃筑堂效孟氏之养吾表兄杖屦其间得日涉之趣某来游名堂曰双植因书三绝 其一","f":"七言绝句","c":["不到君家几换春，眼中风物一番新。","吾园小小知何用，不似兹园可养亲。"]},{"t":"李镇夫辟圃筑堂效孟氏之养吾表兄杖屦其间得日涉之趣某来游名堂曰双植因书三绝 其二","f":"七言绝句","c":["琴书得趣有真乐，轩冕倘来何足干。","种德种花兼著力，要须留与子孙看。"]},{"t":"李镇夫辟圃筑堂效孟氏之养吾表兄杖屦其间得日涉之趣某来游名堂曰双植因书三绝 其三","f":"七言绝句","c":["绕堂花木随宜种，堆案文书取次翻。","我待衣冠挂林下，杖藜时复到君园。"]},{"t":"刘长方自豫章寄书称砮焦蛎房之美恨未知味书一绝以寄之","f":"七言绝句","c":["珠屿小蛎圆带石，砮焦巨房深若杯。","吾乡此味亦不恶，故人游宦盍归来。"]},{"t":"宝印叔得小假山以长篇模写进士钦逢辰和之某次韵并简钦","f":"七言古诗","c":["越绝天台温雁荡，万壑千岩各形状。","钱塘风物更奇绝，杖屦年时记曾访。","归来戏辟小园林，十里西湖藏瓮盎。","悠然入眼皆吾山，罗列轩窗一何壮。","止庵道人真有道，种竹莳花近丘圹。","何人好事赠假山，潜涧新添小屏嶂。","却疑迁徙从平泉，更恐飞来自秦望。","世间赝物何止此，沙佛儒衣龙亦象。","道人于物意岂留，异日从教散天壤。","花木篇章两游戏，林下高风真可尚。","来游莲社有诗人，句比昌黎更豪放。","我休说假复论真，真假通同归一相。"]},{"t":"次韵昌龄西园十咏 其一 黄杨藓复有生意","f":"七言绝句","c":["黄杨庚甲与吾同，树已萧疏我亦翁。","藤蔓稍除苔藓去，岁寒犹解傲霜风。"]},{"t":"次韵昌龄西园十咏 其二 莆萄","f":"七言绝句","c":["满架龙须卷复伸，堆盘马乳酿青春。","泼醅一斗宜延客，莫博凉州学汉人。"]},{"t":"次韵昌龄西园十咏 其三 脩竹","f":"七言绝句","c":["至乐斋西碧玉竿，清阴时过酒杯寒。","明年看长纤纤笋，解箨当为汉帝冠。"]},{"t":"次韵昌龄西园十咏 其四 梅","f":"七言绝句","c":["拂云脩竹绕吾家，竹里仍栽第一花。","好句更同林处士，月黄昏后影横斜。"]},{"t":"次韵昌龄西园十咏 其五 桃","f":"七言绝句","c":["欲留王母盘中核，兼采秦人洞里薪。","此事渺茫花笑我，不如聊赏故园春。"]},{"t":"次韵昌龄西园十咏 其六 李","f":"七言绝句","c":["长念诗人咏子嗟，团栾绕树日攲斜。","冰盘行荐炎天实，不用东门学种瓜。"]},{"t":"次韵昌龄西园十咏 其七 杉","f":"七言绝句","c":["记得先人手自栽，森然千尺尽成材。","翠丝结作思人树，它日儿孙岂忍摧。"]},{"t":"次韵昌龄西园十咏 其八 桂","f":"七言绝句","c":["丹霄休叹路难通，学取燕山种桂丛。","异日天香满亭院，吾庐当似广寒宫。"]},{"t":"次韵昌龄西园十咏 其九 柳","f":"七言绝句","c":["何幸先人有弊庐，不妨同种柳千株。","垂阴覆地宁无日，作雪漫天肯似榆。"]},{"t":"次韵昌龄西园十咏 其十 菊","f":"七言绝句","c":["百花春放菊秋荣，霜里鲜鲜照眼明。","岁晚不妨开自好，何须三嗅泣繁英。"]},{"t":"题如存亭壁 其一","f":"七言绝句","c":["不见慈亲已一星，佳城松柏惨然青。","此生难报劬劳德，空对铭碑涕泗零。"]},{"t":"题如存亭壁 其二","f":"七言绝句","c":["年来游宦远松楸，越雪吴霜带满头。","乞得祠宫养衰病，白岩香火共僧修。"]},{"t":"刘义夫欲与先陇植兰寄数根","f":"七言绝句","c":["思亲何忍陟南陔，采得幽兰祇自哀。","寄与东山刘孝子，佳城侧畔好亲栽。"]},{"t":"义夫许赠丁香蜡梅","f":"七言绝句","c":["刘郎不独种桃花，蜡蕊柔香更可嘉。","臭味相同林下友，从今花木亦通家。"]},{"t":"义夫以赵清献谏垣集易柳文次其韵","f":"七言绝句","c":["文集何须较少多，有无相易共渐磨。","宪台清献柳州柳，唐宋人才未易过。"]},{"t":"雁山僧景暹求文记本觉殿","f":"七言绝句","c":["归来欲效老夫潜，喜见游方旧杜暹。","本觉殿成功德满，愧无笔力助庄严。"]},{"t":"又六言","f":"词","c":["笔下何曾有口，囊中更愧无钱。","聊把一言赞叹，助成此段因缘。"]},{"t":"人日有雪竹间种兰","f":"五言律诗","c":["人日又飞雪，竹林仍种兰。","阳浮屑琼玖，风泛馥檀栾。","花点黄金胜，丛依碧玉竿。","世间桃李眼，肯向此中看。"]},{"t":"张思豫主簿送丹桂蜡梅 其一","f":"七言绝句","c":["通家天上张公子，桂种遥分月窟香。","三径殷勤自栽植，异时会见五枝芳。"]},{"t":"张思豫主簿送丹桂蜡梅 其二","f":"七言绝句","c":["莲幕何人送此花，不容一蕊污贫家。","归来自觅清河种，馨德如人最可嘉。"]},{"t":"余全之赠菊栽二十品并示三十绝走笔二绝酬之 其一","f":"七言绝句","c":["老觉山林兴味长，归来三径叹荒凉。","分君嘉菊二十品，增我东园十八香。"]},{"t":"余全之赠菊栽二十品并示三十绝走笔二绝酬之 其二","f":"七言绝句","c":["余郎萧洒似何郎，事业它年未易量。","寄我新诗三十绝，笔头直与菊争芳。"]},{"t":"二月二日焚黄天色开霁宾游并集存没有光悲痛之馀因成鄙语","f":"七言律诗","c":["三釜深悲不逮亲，九天命下贲双坟。","痛将泪杂香醪奠，忍见衣随告墨焚。","漠漠浓阴初阁雨，晖晖煖日旋披云。","馀生难报劬劳德，犹有孤忠可报君。"]},{"t":"送陈元佐游剡","f":"五言律诗","c":["杖屦昔游剡，梦魂犹至今。","欣闻戒行李，遥访旧同襟。","敩学功相半，渊源力可寻。","池中神鲤足，时为寄乡音。"]},{"t":"双桂","f":"五言绝句","c":["先人植双桂，馨德满吾庐。","不老儿孙长，联芳合似渠。"]},{"t":"东篱","f":"五言绝句","c":["我岂规彭泽，兹篱偶在东。","悠然见山处，仍向菊花丛。"]},{"t":"左原诗三十二首 其一 东高山","f":"七言绝句","c":["峰头日出已停午，山半云横疑在天。","要使名如越山重，直须人似谢公贤。"]},{"t":"左原诗三十二首 其二 西高山","f":"七言绝句","c":["压顶花枝红欲燎，导前旌节闹如诃。","倚窗拄颊时时好，何止朝来爽气多。"]},{"t":"左原诗三十二首 其三 南高山","f":"七言绝句","c":["山后风来闻县鼓，荡中秋至集宾鸿。","我归种菊东篱下，长在悠然眼界中。"]},{"t":"左原诗三十二首 其四 北高山","f":"七言绝句","c":["群山如囿秀回环，秀拔群山是北山。","我恐山中猿鹤怨，移文未至已先还。"]},{"t":"左原诗三十二首 其五 龟山","f":"七言绝句","c":["众山环绕一山横，形似真龟势欲行。","不向九江资纳锡，临溪曳尾自全生。"]},{"t":"左原诗三十二首 其六 卧虎山","f":"七言绝句","c":["昂然虎踞一原东，回首眈眈气象雄。","不放众山随逝水，溪头高卧自威风。"]},{"t":"左原诗三十二首 其七 梅溪","f":"七言绝句","c":["我向梅花溪上家，几看清浅浸横斜。","手栽木已如人老，雪鬓萧疏对雪花。"]},{"t":"左原诗三十二首 其八 杨溪","f":"七言绝句","c":["一涧泓澄会众流，脉分俄类婺溪头。","临溪更种青青木，故事端同柳柳州。"]},{"t":"左原诗三十二首 其九 戏綵岩","f":"七言绝句","c":["烟霞屏障列西岑，戏綵标名自始今。","我过岩前每流涕，斑衣空有老莱心。"]},{"t":"左原诗三十二首 其十 杜鹃岩","f":"七言绝句","c":["游宦三年乐事违，岩花笑我鸟催归。","归来又被岩花笑，笑我登岩何太稀。"]},{"t":"左原诗三十二首 其十一 棋盘岩","f":"七言绝句","c":["杜鹃岩北一拳石，石面平平堪弈棋。","路僻山深罕人到，烂柯仙客未应知。"]},{"t":"左原诗三十二首 其十二 撒水岩","f":"七言绝句","c":["龙卧灵湫志未伸，时时喷水撒行人。","虽然未救苍生旱，聊欲澄清世上尘。"]},{"t":"左原诗三十二首 其十三 松罗岩","f":"七言绝句","c":["插天万仞绝攀跻，岩顶松罗不是栽。","廊庙须材作梁栋，人间斤斧可能来。"]},{"t":"左原诗三十二首 其十四 障岩","f":"七言绝句","c":["岩如法吏面清泠，石似端人真直方。","谁解移兹障边境，犬羊安敢肆猖狂。"]},{"t":"左原诗三十二首 其十五 人面岩","f":"七言绝句","c":["看尽人间古与今，苍颜一任藓苔侵。","岂惟有面如人面，更喜无心似兽心。"]},{"t":"左原诗三十二首 其十六 天柱岩","f":"七言绝句","c":["雁山一柱插云霄，三井松罗柱亦高。","蓬荜深怀杞人念，擎天端赖柱坚牢。"]},{"t":"左原诗三十二首 其十七 幞头岩","f":"七言绝句","c":["闹处身宜及早抽，山林迟我挂冠游。","不须花里寻腰带，且向田间置幞头。"]},{"t":"左原诗三十二首 其十八 宋家尖","f":"七言绝句","c":["皇恩西被复东渐，四海苍生尽仰瞻。","畎亩微臣尤戴宋，结庐长向此峰尖。"]},{"t":"左原诗三十二首 其十九 小雁荡","f":"七言绝句","c":["归雁行飞集涧阿，不贪江海稻粱多。","峰头一荡虽然小，饮啄犹堪避网罗。"]},{"t":"左原诗三十二首 其二十 左岭","f":"七言绝句","c":["北望吾庐山最好，南通萧寺境逾幽。","白云夜向原中宿，几度随人过岭头。"]},{"t":"左原诗三十二首 其二十一 左湖","f":"七言绝句","c":["渔樵欸乃日相呼，舟楫生涯在画图。","我与渔樵同隐逸，不须乞作自家湖。"]},{"t":"左原诗三十二首 其二十二 莼湖","f":"七言绝句","c":["水晶银线满湖中，遥与吴江气象同。","我辈他年厌游宦，思归应不待秋风。"]},{"t":"左原诗三十二首 其二十三 南瀑布","f":"七言绝句","c":["飞瀑来从小雁荡，灵源颇类大龙湫。","矩罗尊者不须占，乞与山翁取次游。"]},{"t":"左原诗三十二首 其二十四 北瀑布","f":"七言绝句","c":["兹潭谁主复谁宾，清世宁容有隐沦。","独我山林养衰病，不妨来作主潭人。"]},{"t":"左原诗三十二首 其二十五 嘶水涧","f":"七言绝句","c":["岭头寒涧远无声，夜静风恬忽自鸣。","山水有灵人不识，老农常用卜阴晴。"]},{"t":"左原诗三十二首 其二十六 雁潭","f":"七言绝句","c":["九日登临涧水滨，荡中征雁亦来宾。","如今雁至应相感，不见名潭旧主人。"]},{"t":"左原诗三十二首 其二十七 三井","f":"七言绝句","c":["源泉高似银河落，石井泓然鼎足分。","闻说井中鱼已化，定从三级上青云。"]},{"t":"左原诗三十二首 其二十八 孝感井","f":"七言绝句","c":["纶竿临井重欷歔，诚感幽潜遂获鱼。","解道随钩得玄鲫，秘书好句实堪书。"]},{"t":"左原诗三十二首 其二十九 白岩庵","f":"七言绝句","c":["飞凤吹归思竹实，蟠龙高卧恋山泉。","吾家松槚今三世，僧舍钟鱼已百年。"]},{"t":"左原诗三十二首 其三十 贾公庵","f":"七言绝句","c":["贾公名德重吾乡，慈母难兄窆此岗。","手种松楸及因果，青山流水共高长。"]},{"t":"左原诗三十二首 其三十一 如在亭","f":"七言绝句","c":["东山一到一沾巾，记得先人昔念亲。","强把兹亭号如在，松悲柏惨见无因。"]},{"t":"左原诗三十二首 其三十二 如存亭","f":"七言绝句","c":["北堂犹绿旧时萱，寒暑无繇复凊温。","戏綵岩边白云下，慈颜彷佛尚如存。"]},{"t":"小小园纳凉","f":"七言绝句","c":["屏迹丘园世事轻，澹然滋味似孤僧。","平生愿学昌黎伯，宰相三书独不能。"]},{"t":"赠甥万膺","f":"七言绝句","c":["诗书为田笔砚耕，著意治此清白生。","它年门户大可必，东平有孙吾有甥。"]},{"t":"万孝杰用韵见寄酬之","f":"七言绝句","c":["堂有慈亲养且耕，游从毛颖楮先生。","新诗寄我尤清绝，深喜牢之有外甥。"]},{"t":"题从侄慎庄","f":"五言律诗","c":["风雨漂我庐，无地寄食宿。","小阮知所敦，舍我道旁屋。","震凌得帡幪，幸免泥涂辱。","明白归旧巢，鹪鹩一枝足。"]},{"t":"万孝全惠小龙团","f":"七言绝句","c":["贡馀龙饼非常品，绝胜卢仝得月团。","岂有诗情可尝此，荷君分贶及粗官。"]},{"t":"赴召","f":"七言绝句","c":["圣主龙飞才十日，微臣得郡古严陵。","诏书又趣归天阙，愿竭孤忠赞中兴。"]},{"t":"曹梦良赠炭戏成一绝","f":"七言绝句","c":["乌龙书至送乌薪，郎舍严冬觉有春。","未暇吞为哑口汉，旦须暖作直身人。"]},{"t":"宿学呈同官","f":"五言律诗","c":["不听梧桐雨，回头已六年。","齑盐谙旧味，灯火结前缘。","进学思韩愈，同襟有郑虔。","诸生不待劝，忠孝素惓惓。"]},{"t":"某去五月罢馆职还乡涂中以诗寄同舍云去国怀明主离群念旧游翻令到家梦中夜绕瀛洲今以史职复至道山访旧或迁或去惟后园脩竹乃故人也感叹良久因成短篇","f":"五言律诗","c":["蓬莱隔弱水，三年两来游。","群仙各何之，翩然蜕神洲。","园中旧箨龙，劲节含清幽。","手摘岁寒叶，恍惚乘归舟。"]},{"t":"冯员仲赴阙奏事士君子咸欲其留闻为魏公所辟势不可夺遂成鄙语兼简查元章","f":"五言律诗","c":["名德重夷夏，皇朝两魏公。","平淮已得愈，论将更资冯。","报主男儿志，知恩国士风。","尽收良马去，冀北遂群空。"]},{"t":"程泰之郎中以诗三绝觅省中梅花因次其韵 其一","f":"七言绝句","c":["长记蓬山旧赏梅，芳樽一笑共君开。","重游未见梅花面，应误君诗得得来。"]},{"t":"程泰之郎中以诗三绝觅省中梅花因次其韵 其二","f":"七言绝句","c":["诗似西湖处士诗，十篇三绝斗清奇。","更将正味森严句，压倒屋檐斜入枝。"]},{"t":"程泰之郎中以诗三绝觅省中梅花因次其韵 其三","f":"七言绝句","c":["竹亭不到几经时，来往逢梅似退之。","遥想吾庐溪上好，十分乡思又关眉。"]},{"t":"依韵奉酬胡秘监","f":"七言绝句","c":["平生恨未识刚者，今日岂期亲见之。","欲把江梅比孤洁，江梅无此岁寒枝。"]},{"t":"次韵胡秘监酴醾","f":"五言古诗","c":["红紫纷争先，酴醾分甘晚。","谁栽群玉府，童童翠张幰。","华共芸芬香，韵随官逸远。","奚用燃青藜，端能照书苑。","先生海上归，平步到蓬巘。","招邀饮醇酎，刚肠出清婉。","遥思吴宫魂，故作楚辞挽。","勿为花所留，兴尽要知返。"]},{"t":"馆中三月晦日闻莺胡邦衡有诗用东坡酴醾韵有君侧无谗人发口不须婉句某次韵","f":"五言古诗","c":["久伤伐木废，每叹吾生晚。","黄鸟从何来，乔林绿垂幰。","忽作相呼声，朋来无近远。","高翥凌云烟，斜飞集池苑。","中有幽谷姿，迟迟下遥巘。","群音巧相和，出语独不婉。","哑哑如老乌，闻者弓欲挽。","知心有杜鹃，劝尔故园返。"]},{"t":"上赐讲读官建茶某以说书与焉以十饼分赠太学同舍苪太博有诗次韵","f":"七言律诗","c":["天表初容咫尺亲，云龙重拜太官珍。","赐从明主恩尤渥，分及清流事更新。","搜卷要须尝七椀，乘风便合到三神。","诸公异日沾君贶，愿寄江湖老散人。"]},{"t":"四月从驾诣德寿宫与诸公会食于和乐楼是日借洪景严承旨马戏云从驾滥骑承旨马朝天叨缀舍人班异日再集胡舍人邦衡云不可不成篇也遂于楼中足之","f":"七言律诗","c":["殿坳经幄侍清閒，学术空疏愧在颜。","从驾滥骑承旨马，朝天叨缀舍人班。","登楼虽喜民和乐，论事还惊世险艰。","圣主英姿同艺柤，诸君何苦恋湖山。"]},{"t":"用登和乐楼韵酬胡邦衡送别兼简刘韶美秘监","f":"七言律诗","c":["未访鄱阳范与颜，雁山深处且投閒。","紫泥长记曾同召，丹陛何繇更对班。","我愧未行平日志，公应不创昔时艰。","笔端能制人生死，兼有刘郎在道山。"]},{"t":"去国","f":"五言绝句","c":["去国常忧国，还家未有家。","君恩报无所，含愧出京华。"]},{"t":"重游钓台 其一","f":"七言绝句","c":["三年两溯钓滩涛，来往何曾补一毫。","圣主雅恢光武量，微臣当遂子陵高。"]},{"t":"重游钓台 其二","f":"五言绝句","c":["弭棹祠堂下，一天星斗明。","客星寻不见，影浸钓滩清。"]},{"t":"过婺女同年王节推黄教授乡人华主簿会饮双溪楼","f":"七言律诗","c":["年时尝泛婺溪舟，未上清风八咏楼。","天为故人偿夙愿，水知吾辈喜清流。","沈郎不为吟诗瘦，王粲长怀去国忧。","明日山川共人远，乡情年契两悠悠。"]},{"t":"游仙都","f":"七言律诗","c":["皇都归客过仙都，厌看西湖看鼎湖。","洞接龙泓片云近，山分雁荡一峰孤。","香清天上碧华落，音好林间青鸟呼。","天遣林泉慰吾辈，不容身世老迷涂。"]},{"t":"游洞溪","f":"七言绝句","c":["段公不到溪岂好，李守已亡诗更奇。","偶向思贤亭上坐，爱溪兼爱昔人诗。"]},{"t":"重游石门洞 其一","f":"五言绝句","c":["石洞几时辟，石门长不扃。","贪看一派水，三载两回经。"]},{"t":"重游石门洞 其二","f":"五言绝句","c":["谁把银河水，直从天半倾。","好流人世去，一洗四维清。"]},{"t":"寄题喻叔奇亦好园","f":"七言律诗","c":["喻子有园堪养亲，栽花种竹清且新。","堂中戏罢即策杖，在家有此何忧贫。","弟兄既好园亦好，大胜吾家园小小。","两园松竹怀主人，他日归来各须早。"]},{"t":"种蔬","f":"五言古诗","c":["归来日弹铗，食无肉与鱼。","却将种花地，町畦毓嘉蔬。","骄阳每抱瓮，时雨亲荷锄。","青青有生意，令我颜色舒。","宁忧馑与饥，亦有瓶中储。","前身老阇梨，蔬气端未除。","文字亦宿业，复生鱼蠹书。","蠹书仍食蔬，苦淡味有馀。","况兹清净根，分来自僧居。","端能纳须弥，聊尔秀郊墟。","洗我腥膻肠，襟宇生清虚。","岂惟陶渊明，吾亦爱吾庐。","荒园涉成趣，枯藤当安舆。","困枕案头卷，饥著盘中菹。","孔门陈蔡色，借问何如予。"]},{"t":"予素不善棋孙先觉万大年林大和见访戏与对垒偶皆胜之因作数语","f":"五言古诗","c":["予手不善谈，临局气先怯。","偶逢孙万林，三战辄三捷。","都缘敌不勍，非以台威胁。","孺子滥成名，凯奏意殊惬。","三君皆壮士，小挫未肯厌。","予今务持胜，坚壁不容劫。"]},{"t":"大年和棋诗复次前韵","f":"五言古诗","c":["君棋如龙且，初笑韩信怯。","我棋似公瑾，赤壁真横捷。","但知贪旁角，不觉攻背胁。","主人本无竞，胜负两俱惬。","嘉宾傥再集，鏖战定谁厌。","新篇尤逼人，我辈徒劫劫。"]},{"t":"太白昼见","f":"七言古诗","c":["煌煌太白生东方，追逐残月生光芒。","太阳中天不肯藏，过午一点犹微茫。","太史占之此何祥，咸忧兵起人流亡。","金行用事多灾伤，大风地震水旱蝗。","有一于此宜预防，杂然并见何以当。","臣言天意未可量，滔天赤地兴尧汤，偃禾拔木悟成王。","宋景一言国乃昌，灾异不作忧楚庄。","吾皇修德应彼苍，去谗远佞任忠良。","推诚纳谏正纪纲，内修政事仍外攘。","誓雪国耻还封疆，强虏当弱吾当强。","天戒为福非为殃，愿勿徒以虚文禳。"]},{"t":"荆妇夜绩","f":"五言律诗","c":["凉飙堕黄叶，促织催女工。","鬓丝不堪织，细君哀我穷。","青灯绩深夜，绩成寒素风。","愿为隐者衣，德耀随梁鸿。"]},{"t":"术者谓予命犯元辰故每仕辄已予笑曰有是哉戏作问答语","f":"七言律诗","c":["问君胡为入台省，问君胡为官辄冷。","宣尼犹且畏元辰，羊鼠龙猪作君梗。","退之宿直斗牛箕，声名谤毁常相随。","死生穷达端有命，予知之矣当安之。"]},{"t":"再至双植堂呈表兄李克明","f":"五言律诗","c":["此日一樽酒，再游双植堂。","湖山浮野色，草木带秋光。","东道德已熟，西风花更香。","相看俱老矣，会合意尤长。"]},{"t":"九日寄表叔贾司理","f":"七言古诗","c":["忆昔从师学弦诵，年与贾生相伯仲。","九日登高鹿岩脊，感物题诗笔初弄。","旧游回首半零落，三十六年真一梦。","当时唱和三四老，尚有残篇可吟讽。","今年节物身在家，行乐山间谩随众。","弟兄劝我登高山，身似驽骀不容鞚。","河东先生今靖节，有酒宁须白衣送。","朋尊聊献菲蒙泉，赐茗仍分小团凤。","愿公一饮寿千龄，三物年年敢驰贡。"]},{"t":"九日不登高与兄弟邻里就敝舍饮菊","f":"五言律诗","c":["中秋对明月，九日逢黄花。","节物岂不好，而况身在家。","樽酒醵邻里，盘餐饤鱼虾。","何必登高山，清欢自无涯。"]},{"t":"仙居陈少曾寄锦石杯书至乃九日也方与坐客把菊遂用以劝酒","f":"七言绝句","c":["九日登临有雁来，书传坐上手亲开。","呼儿满酌黄花酒，为子深倾锦石杯。"]},{"t":"仆夫浚井得双鲫一鳗未及烹也藏之泥水间予见而放之因作数语","f":"七言律诗","c":["三秋不雨泉脉枯，仆夫浚井欣得鱼。","刀砧已具未及杀，我偶见之鱼再活。","亲投不敢使校人，圉圉洋洋生意新。","莫嫌井小思沧海，尺水相忘聊自在。"]},{"t":"得张大猷尚书书云比每进对屡以待御为言而邦衡舍人言尤数切云云某为群邪所疾独见知二公因读邦衡和和乐楼诗复用前韵","f":"七言律诗","c":["一月霜台屡犯颜，未回天听已身閒。","爱君忧国寸心赤，感物伤时双鬓班。","文举才疏意徒广，子云思苦语尤艰。","尚书左史虽知我，超海应难挟太山。"]},{"t":"次韵题宝印叔兰若堂","f":"五言律诗","c":["何处名兰若，依山结草堂。","花枝法雨润，心地佛灯光。","浮世嚣尘隔，空门岁月长。","林间有啼鸟，听法亦来翔。"]},{"t":"藤杖","f":"七言绝句","c":["头角槎牙万岁藤，遍身节目更棱棱。","山僧赠我非无意，要我清闲亦似僧。"]},{"t":"予还自武林葺先人弊庐净扫一室晨起焚香读书于其间兴至赋诗客来饮酒啜茶或弈棋为戏藏书数百卷手自暴之有小园时策杖以游，时遇秋旱驱家僮浚井汲水浇花良天佳月与兄弟邻里把酒杯同赏过重九方见菊以泛觞有足乐者每览镜见苍颜白发亦聊自叹也作小诗十五首 其一 扫室","f":"五言绝句","c":["洒扫学者事，陈蕃胡不然。","要令天下净，端自室中先。"]},{"t":"予还自武林葺先人弊庐净扫一室晨起焚香读书于其间兴至赋诗客来饮酒啜茶或弈棋为戏藏书数百卷手自暴之有小园时策杖以游，时遇秋旱驱家僮浚井汲水浇花良天佳月与兄弟邻里把酒杯同赏过重九方见菊以泛觞有足乐者每览镜见苍颜白发亦聊自叹也作小诗十五首 其二 焚香","f":"五言绝句","c":["扫地眼尘净，焚香心境清。","案头时一炷，邪虑不应生。"]},{"t":"予还自武林葺先人弊庐净扫一室晨起焚香读书于其间兴至赋诗客来饮酒啜茶或弈棋为戏藏书数百卷手自暴之有小园时策杖以游，时遇秋旱驱家僮浚井汲水浇花良天佳月与兄弟邻里把酒杯同赏过重九方见菊以泛觞有足乐者每览镜见苍颜白发亦聊自叹也作小诗十五首 其三 读书","f":"五言绝句","c":["入政惭无学，还家更读书。","翻同小儿辈，相共惜居诸。"]},{"t":"予还自武林葺先人弊庐净扫一室晨起焚香读书于其间兴至赋诗客来饮酒啜茶或弈棋为戏藏书数百卷手自暴之有小园时策杖以游，时遇秋旱驱家僮浚井汲水浇花良天佳月与兄弟邻里把酒杯同赏过重九方见菊以泛觞有足乐者每览镜见苍颜白发亦聊自叹也作小诗十五首 其四 赋诗","f":"五言绝句","c":["秋兴最难遣，诗怀如乱云。","虽无少陵笔，一饭不忘君。"]},{"t":"予还自武林葺先人弊庐净扫一室晨起焚香读书于其间兴至赋诗客来饮酒啜茶或弈棋为戏藏书数百卷手自暴之有小园时策杖以游，时遇秋旱驱家僮浚井汲水浇花良天佳月与兄弟邻里把酒杯同赏过重九方见菊以泛觞有足乐者每览镜见苍颜白发亦聊自叹也作小诗十五首 其五 饮酒","f":"五言绝句","c":["我意岂在酒，衔杯聊乐天。","客来同一醉，客去独高眠。"]},{"t":"予还自武林葺先人弊庐净扫一室晨起焚香读书于其间兴至赋诗客来饮酒啜茶或弈棋为戏藏书数百卷手自暴之有小园时策杖以游，时遇秋旱驱家僮浚井汲水浇花良天佳月与兄弟邻里把酒杯同赏过重九方见菊以泛觞有足乐者每览镜见苍颜白发亦聊自叹也作小诗十五首 其六 啜茶","f":"五言绝句","c":["滥与金华讲，赐沾龙凤团。","却归林下饮，更愧是粗官。"]},{"t":"予还自武林葺先人弊庐净扫一室晨起焚香读书于其间兴至赋诗客来饮酒啜茶或弈棋为戏藏书数百卷手自暴之有小园时策杖以游，时遇秋旱驱家僮浚井汲水浇花良天佳月与兄弟邻里把酒杯同赏过重九方见菊以泛觞有足乐者每览镜见苍颜白发亦聊自叹也作小诗十五首 其七 弈棋","f":"五言绝句","c":["光景老尤惜，忍销枰弈间。","娱宾欠丝竹，一局战清闲。"]},{"t":"予还自武林葺先人弊庐净扫一室晨起焚香读书于其间兴至赋诗客来饮酒啜茶或弈棋为戏藏书数百卷手自暴之有小园时策杖以游，时遇秋旱驱家僮浚井汲水浇花良天佳月与兄弟邻里把酒杯同赏过重九方见菊以泛觞有足乐者每览镜见苍颜白发亦聊自叹也作小诗十五首 其八 暴书","f":"五言绝句","c":["秋日更可畏，所宜惟暴书。","反身还自笑，均是蠹书鱼。"]},{"t":"予还自武林葺先人弊庐净扫一室晨起焚香读书于其间兴至赋诗客来饮酒啜茶或弈棋为戏藏书数百卷手自暴之有小园时策杖以游，时遇秋旱驱家僮浚井汲水浇花良天佳月与兄弟邻里把酒杯同赏过重九方见菊以泛觞有足乐者每览镜见苍颜白发亦聊自叹也作小诗十五首 其九 策杖","f":"五言绝句","c":["园小日思涉，山高时欲登。","老来疲脚力，兴至策枯藤。"]},{"t":"予还自武林葺先人弊庐净扫一室晨起焚香读书于其间兴至赋诗客来饮酒啜茶或弈棋为戏藏书数百卷手自暴之有小园时策杖以游，时遇秋旱驱家僮浚井汲水浇花良天佳月与兄弟邻里把酒杯同赏过重九方见菊以泛觞有足乐者每览镜见苍颜白发亦聊自叹也作小诗十五首 其十 汲水","f":"五言绝句","c":["山中久不雨，汲水欲何从。","一夜井泉达，灵鳗恐是龙。"]},{"t":"予还自武林葺先人弊庐净扫一室晨起焚香读书于其间兴至赋诗客来饮酒啜茶或弈棋为戏藏书数百卷手自暴之有小园时策杖以游，时遇秋旱驱家僮浚井汲水浇花良天佳月与兄弟邻里把酒杯同赏过重九方见菊以泛觞有足乐者每览镜见苍颜白发亦聊自叹也作小诗十五首 其十一 浇花","f":"五言绝句","c":["花木正憔悴，秋阳那更骄。","驱童绠深井，聊助化工浇。"]},{"t":"予还自武林葺先人弊庐净扫一室晨起焚香读书于其间兴至赋诗客来饮酒啜茶或弈棋为戏藏书数百卷手自暴之有小园时策杖以游，时遇秋旱驱家僮浚井汲水浇花良天佳月与兄弟邻里把酒杯同赏过重九方见菊以泛觞有足乐者每览镜见苍颜白发亦聊自叹也作小诗十五首 其十二 赏月","f":"五言绝句","c":["还舍八十日，三逢明月圆。","停杯试一问，归去定何年。"]},{"t":"予还自武林葺先人弊庐净扫一室晨起焚香读书于其间兴至赋诗客来饮酒啜茶或弈棋为戏藏书数百卷手自暴之有小园时策杖以游，时遇秋旱驱家僮浚井汲水浇花良天佳月与兄弟邻里把酒杯同赏过重九方见菊以泛觞有足乐者每览镜见苍颜白发亦聊自叹也作小诗十五首 其十三 采菊","f":"五言绝句","c":["既晚开何益，采之聊泛觞。","书生自头白，奚用泣馨香。"]},{"t":"予还自武林葺先人弊庐净扫一室晨起焚香读书于其间兴至赋诗客来饮酒啜茶或弈棋为戏藏书数百卷手自暴之有小园时策杖以游，时遇秋旱驱家僮浚井汲水浇花良天佳月与兄弟邻里把酒杯同赏过重九方见菊以泛觞有足乐者每览镜见苍颜白发亦聊自叹也作小诗十五首 其十四 览镜","f":"五言绝句","c":["可正宜频览，无尘亦自磨。","少陵今老矣，功业欲如何。"]},{"t":"予还自武林葺先人弊庐净扫一室晨起焚香读书于其间兴至赋诗客来饮酒啜茶或弈棋为戏藏书数百卷手自暴之有小园时策杖以游，时遇秋旱驱家僮浚井汲水浇花良天佳月与兄弟邻里把酒杯同赏过重九方见菊以泛觞有足乐者每览镜见苍颜白发亦聊自叹也作小诗十五首 其十五 浚井","f":"五言绝句","c":["旱久井垂涸，汲多泉更浑。","浚教泥净尽，何患不逢原。"]},{"t":"酬林明仲寄书并长篇","f":"七言律诗","c":["江头一别九十日，路隔烟波望欲迷。","风送雁群来雁荡，书从梅屿到梅溪。","羡君笔力能豪健，赠我诗篇过品题。","谢客江山富观览，城南何日手重携。"]},{"t":"昌龄欲游白石兴尽而止予亦思前年之游遂次其韵","f":"七言律诗","c":["前年蜡屐远寻幽，洞府曾经一宿留。","诗句亲题碧云里，梦魂时到白岩头。","风生见说欲飞去，兴尽何如且罢休。","他日相呼老兄弟，飘然杖屦共翱游。"]},{"t":"洪丞不负轩","f":"五言律诗","c":["坐此轩无愧，问君何以能。","所行皆是学，不负岂惟丞。","凫鹜文书静，槐松诗思凝。","博陵徒种绩，践履亦何曾。"]},{"t":"周丞奉挽诗","f":"五言律诗","c":["平生义方教，真是起家媒。","有子愿已足，无心官自来。","兴随鸠杖逸，情为雁行哀。","想见长塘水，凄凉绕夜台。"]},{"t":"黄岩赵十朋贤士也有诗云四枚豚犬教知书二顷良田尽有馀鲁酒三杯棋一局客来浑不问亲疏予亦有东皋二顷，两子皆学读书客至则弈棋饮酒遂用赵君诗意成一绝","f":"七言绝句","c":["薄有田园种斗升，两儿传授读书灯。","客来一局三杯酒，王十朋如赵十朋。"]},{"t":"陈商英挽词","f":"七言律诗","c":["贵似金张富石崇，纷纷老死利名中。","退居不见香山老，肥遁谁知秀野翁。","溪上园因种花辟，床头金为好宾空。","潸然痛念公兄弟，二十年前笔砚同。"]},{"t":"陈商霖挽词","f":"七言律诗","c":["畴昔游从分不轻，十年乡校读书灯。","德星会聚三兄弟，诗社追随八友朋。","去国悲凉老王粲，还乡牢落失陈登。","诵君生死炎凉句，斜日寒天涕满膺。"]},{"t":"万清之有诗三绝呈司理贾丈并简某因次其韵 其一","f":"七言绝句","c":["灯花端为故人然，留客殷勤为击鲜。","更觉门阑增喜气，冰清玉润两俱贤。"]},{"t":"万清之有诗三绝呈司理贾丈并简某因次其韵 其二","f":"七言绝句","c":["世路尘埃逐日生，鹿岩高卧自风清。","吾皇有诏求遗逸，行见临雍拜老更。"]},{"t":"万清之有诗三绝呈司理贾丈并简某因次其韵 其三","f":"七言绝句","c":["甘言耻效蜜翁翁，逆耳空馀畎亩忠。","愿子他年似房杜，好将一语记文中。"]},{"t":"再用前韵 呈司理","f":"七言绝句","c":["论文尊酒意欢然，蜡炬高烧夜色鲜。","得婿端同权相国，传经更似老韦贤。"]},{"t":"再用前韵 酬清之","f":"七言绝句","c":["僚婿欣逢旧友生，人如王谢气尤清。","十年前已心相许，细看新诗貌愈更。"]},{"t":"再用前韵 赠大老","f":"七言绝句","c":["士论乡评重乃翁，贤如狐突教儿忠。","治安策就君宜献，宣室开时夜正中。"]},{"t":"未腊而雪丰年兆也大老有诗次韵 其一","f":"七言绝句","c":["明年禾黍定千钟，瑞雪搀先舞晓风。","更愿平淮捷书至，西平禽贼献司空。"]},{"t":"未腊而雪丰年兆也大老有诗次韵 其二","f":"七言绝句","c":["主人开燕倒金钟，坐客俱吟柳絮风。","应念人间有贫者，炉星拨尽酒瓶空。"]},{"t":"雪中寄梅花与清之大老","f":"七言绝句","c":["天花除恼腊前雪，香蕊报春溪上梅。","分赠鹿岩龙穴友，异时俱是百花魁。"]},{"t":"题梦龄五桂堂","f":"七言律诗","c":["我昔曾栽会趣堂，子今封植更芬芳。","胜它福峙三珠树，赛却东嘉五马坊。","靖节柳青宁耐久，大夫松老恨无香。","何如移得蟾宫种，不愧灵椿窦十郎。"]},{"t":"寄鲤鱼与万大年","f":"七言绝句","c":["江枫摇落江梅破，江上诗人有佳句。","欲于龙穴觅明珠，试遣鲤鱼传尺素。"]},{"t":"梁府君挽诗","f":"七言律诗","c":["两郡三乡赖保全，乃翁剑学不虚传。","黄巢讵敢臣周朴，赵胜那能爵鲁连。","仁里化成儒气象，心田种得佛因缘。","奇儿自是青云士，行见荣光烛九泉。"]},{"t":"永嘉卢仲脩永年袖文见访酬以短句","f":"五言律诗","c":["地僻原名左，天寒岁欲徂。","遥遥屈佳客，得得访潜夫。","一第且慁子，八篇真起予。","蜚声参四杰，谁复敢前卢。"]},{"t":"林明仲和诗复用前韵","f":"七言律诗","c":["屡战夷吾卒霸齐，棘栖鸾凤暂沉迷。","探春想见登梅屿，乘兴何妨从雪溪。","楼上清欢庾公兴，桥间壮志马卿题。","四场笔力媒身策，平步青云岂待携。"]},{"t":"张器先和诗复用前韵","f":"七言律诗","c":["心欲齐贤愧未齐，远蒙佳句警昏迷。","音如鼓瑟铿清庙，味似煎茶斗建溪。","忧国非同长卿病，感时端类少陵题。","二松岂是淹贤地，凫鹜文书谩抱携。"]},{"t":"寄蒲墨与明仲","f":"五言绝句","c":["四友共文房，蒲君最异常。","研磨发文采，好去奉仇香。"]},{"t":"寄沈敦谟","f":"七言绝句","c":["二十年前旧友生，缄封远寄见交情。","旧游回首多零落，大器如君合晚成。"]},{"t":"送谢任之 其一","f":"七言绝句","c":["七岁吾从乃祖游，童蒙深愧未能求。","堪嗟四十五年事，昔未裹头今白头。"]},{"t":"送谢任之 其二","f":"七言绝句","c":["梅溪辟馆子来游，回首如今二十秋。","端似韩张互传授，要令编刬绍箕裘。"]},{"t":"送谢任之 其三","f":"七言绝句","c":["去年还家已半年，盍簪尊酒数留连。","岁穷送别溪头路，手把梅花思黯然。"]},{"t":"题双瀑","f":"七言律诗","c":["女娲石烂几经修，天漏犹馀两派流。","离合无心元不静，朝宗得路却相投。","干云宝剑真同气，出荡神龙不异湫。","何用筑门防俗驾，林泉自是少人游。"]},{"t":"张器先复和诗作五言以寄","f":"五言律诗","c":["短棹别孤屿，故山归左原。","遥烦雁足字，重到雀罗门。","岁月添新老，文章忆旧论。","见诗如见面，气象有馀温。"]},{"t":"万孝全赠金华洞石名雪洒遥峰作进退诗次韵","f":"七言律诗","c":["天辟金华一洞奇，洞中石是化羊遗。","浑疑雪向闽山落，更讶峰从天竺飞。","溪上又添乘棹兴，案头如照读书时。","故人重我膏肓疾，田不荒芜应亦归。"]},{"t":"元宵邻里携具就弊庐张灯辞之不获因成一绝","f":"七言绝句","c":["凶年犹幸在家乡，邻里相过具豆觞。","我辈忍将灯照眼，游人多是火烧肠。"]},{"t":"祈雨不应","f":"七言绝句","c":["歉岁还乡益困穷，瓶无储粟酒尊空。","醉经且学文中子，闵雨难祈应上公。"]},{"t":"自秋七月不雨至于春二月十九日仅得雨昌龄作贺诗予未及和而雨止矣遂次韵以闵之 其一","f":"七言绝句","c":["水旱年年费请求，仰勤汤祷与尧畴。","何时三十六雨足，当宁免怀云汉忧。"]},{"t":"自秋七月不雨至于春二月十九日仅得雨昌龄作贺诗予未及和而雨止矣遂次韵以闵之 其二","f":"七言绝句","c":["一杯未吸瓮头春，三叠聊攲雨裛尘。","不用遽兴风伯讼，弘羊真是可烹人。"]},{"t":"社日喜雨复用前韵 其一","f":"七言绝句","c":["社日檐间不断流，渊明欣欲事西畴。","愿言一饱均黎庶，瓶粟无储不用忧。"]},{"t":"社日喜雨复用前韵 其二","f":"七言绝句","c":["欲放乾坤万里春，要须先洗庾公尘。","朝绅贺雨诗多少，谁是诗中讽谏人。"]},{"t":"家食遇歉有饭不足之忧妻孥相勉以固穷因录其语","f":"词","c":["渊明事高尚，瓶中缺储粟。","鲁公凛名节，乞米给饘粥。","广文富才名，官冷饭不足。","少陵老风骚，橡栗拾山谷。","嗟予何为者，处世真碌碌。","谋生一何拙，甔石无储蓄。","三年两去国，囊橐罄水陆。","还家索租苗，不了腊与伏。","前秋遭飓风，摧折数间屋。","今年丁大侵破甑尘可掬。","绝粮瘦百指，告籴走群仆。","乡邻苟不救，定恐填沟渎。","家藏千卷书，父子忍饥读。","一字不堪煮，何以充我腹。","细君笑谓我，子命难食肉。","去岁官台省，侥倖食君禄。","有口不三缄，月奏知几牍。","圣主倘不容，宁免远窜逐。","归来固已幸，富贵非尔福。","东皋二顷田，得雨尚可谷。","子耕我当耘，固穷待秋熟。"]},{"t":"闻小使胡昉抗虏不屈上甚嘉之有旨命右揆抚师仍有和不可成之语皆出睿断宗社之福也昌龄有诗次韵","f":"七言律诗","c":["用儒端可复侵疆，活国何劳别取方。","文帝要须亲御马，子卿宁患远看羊。","抚师暂屈黄扉老，论将宁咨白首郎。","行见车书混天下，岂容南北分三光。"]},{"t":"昌龄四月十九日得男请名于予命之曰迟","f":"七言律诗","c":["端似中山梦得诗，海中仙果子生迟。","况当首夏清和后，更遇千秋启建时。","祝尔愿同彭祖寿，命名聊效小苏儿。","吾家种德已数世，庭户合生兰与芝。"]},{"t":"山丹花","f":"五言律诗","c":["四月相将莫，山丹开始都。","真心本来赤，正色自然朱。","百合晚仍俗，石榴繁更粗。","谁将仙灶药，花里著工夫。"]},{"t":"七月三日至鄱阳 其一","f":"七言绝句","c":["我来鄱君山水州，山水入眼常迟留。","绝境遥通云锦洞，清音下瞰琵琶洲。"]},{"t":"七月三日至鄱阳 其二","f":"七言绝句","c":["干越亭前晚风起，湖入鄱阳三百里。","晓来一雨洗新秋，身在江东画图里。"]},{"t":"次韵何宪子应喜雨","f":"七言律诗","c":["亢阳谁谓不为灾，饥馑连年甑有埃。","旱魃忽随冤狱散，雨师遥逐使车来。","平反尽欲归中典，调燮端宜位上台。","更喜诗如杜陵老，江流坐稳兴悠哉。"]},{"t":"登绮霞亭用喜雨韵","f":"七言律诗","c":["六月西征遇旱灾，脩途千里踏尘埃。","雷公俄唤阿香去，霖雨便随流火来。","天入沧浪游楚越，云翻䆉稏忆温台。","绮霞亭上一回首，满目湖山壮矣哉。"]},{"t":"追和范文正公鄱阳诗 郡斋即事","f":"七言律诗","c":["理郡端如理乱丝，范公往矣欲谁师。","典刑犹有堂中像，光艳长存壁上诗。","未报国恩嗟老去，不逢人杰恨生迟。","一尊坐对鄱江月，耿耿忠怀祇自知。"]},{"t":"追和范文正公鄱阳诗 游芝山寺","f":"五言律诗","c":["出郭上崔嵬，山川亦壮哉。","三芝谁采去，五老欲飞来。","怀古情无尽，思乡首屡回。","论文一尊酒，天色为吾开。"]},{"t":"追和范文正公鄱阳诗 登绮霞亭用碧云轩韵","f":"五言律诗","c":["郡亭临大泽，霞障截尘纷。","有色祇因日，无心元是云。","沧浪随郭转，欸乃隔江闻。","文正已仙去，佳名千载芬。"]},{"t":"追和范文正公鄱阳诗 降圣节诣天庆观因谒颜鲁公范文正公祠堂用赠御赐名道士韵","f":"七言绝句","c":["颜范遥同异代心，琳宫香火道缘深。","诗家风味今谁在，定访弥明与共吟。"]},{"t":"追和范文正公鄱阳诗 观文正像用赠传神道士韵","f":"七言绝句","c":["天然形貌写何难，难得灵台上笔端。","朋党论兴三出日，不知谁作正人看。"]},{"t":"追和范文正公鄱阳诗 移竹植郡斋之东用怀庆朔堂韵","f":"七言绝句","c":["手移修竹傍墙栽，老眼青青为竹开。","独坐书斋谁是伴，清风时作故人来。"]},{"t":"十月望日同官会饭荐福送酒","f":"七言绝句","c":["鄱水同僚总不群，公馀相与共论文。","远公莲社恐无酒，辄效江州王使君。"]},{"t":"生日示闻诗闻礼","f":"七言古诗","c":["哀哀父母生我劳，生日不见徒悲号。","今年偶然梦三刀，二千石向鄱阳叨。","身虽五马已二毛，烹羊击鲜斫蟹螯。","殷勤为寿劳尔曹，愿尔它年著綵袍。","二亲无恙年俱高，更与诸孙持寿醪。","满堂宾客来英豪，会看醉脸如仙桃。"]},{"t":"木蕴之即席和文字韵诗酬以二绝 其一","f":"七言绝句","c":["少年才气已超群，场屋能摛锦绣文。","糠秕在前真有愧，春风得意岂如君。"]},{"t":"木蕴之即席和文字韵诗酬以二绝 其二","f":"七言绝句","c":["回头遥念荡中群，把酒欣论坐上文。","臭味聊将比兄弟，大冯君与小冯君。"]},{"t":"观郡守题名再书一绝","f":"七言绝句","c":["滥与江湖岳牧群，于中最慕范希文。","人才相远心相似，均是忧时与爱君。"]},{"t":"项服善知县和诗酬以三绝并简林致一教授 其一","f":"七言绝句","c":["胆落庭中雁鹜群，宁容摘纸舞微文。","鄱阳贤令知多少，惟有鄱君与项君。"]},{"t":"项服善知县和诗酬以三绝并简林致一教授 其二","f":"七言绝句","c":["牧养功成鲜败群，弦歌声里出诗文。","只愁桃李春风近，卧辙无由驻令君。"]},{"t":"项服善知县和诗酬以三绝并简林致一教授 其三","f":"七言绝句","c":["无钱令尹陶彭泽，有道先生郑广文。","预约它年还故里，共骑白鹿效文君。"]},{"t":"题荐福寺莫莫堂","f":"七言绝句","c":["休休有室宜归早，莫莫名堂去恨迟。","禅老相逢应笑我，休休莫莫定何时。"]},{"t":"哭冯员仲 其一","f":"五言律诗","c":["一代奇男子，哀哉命止斯。","共天终不忍，蹈海亦何辞。","下惠已三黜，照邻俄五悲。","烦言何足辨，公论不容欺。"]},{"t":"哭冯员仲 其二","f":"五言律诗","c":["身为多才误，朝无一日安。","宁为独醒鬼，不作附炎官。","梦断吴江冷，魂归蜀道难。","郡斋挥老泪，重取近书看。"]},{"t":"陆居士挽诗","f":"五言律诗","c":["槐市访同舍，麟经推阿戎。","传家知有子，种德本由公。","遗训皆新语，多男类陆终。","佳城在何处，楚尾白云中。"]},{"t":"洪帅陈阜卿寄笋","f":"七言绝句","c":["均是蓬山逸远官，梦中犹问竹平安。","箨龙寄我知君意，要使刚肠饱岁寒。"]},{"t":"次韵何子应题不欺室","f":"七言古诗","c":["公如忧国房玄龄，我如郑公思批鳞。","隆兴天下同贞观，愿为贤相为良臣。","我去公来不同日，各展忠怀对宣室。","江湖邂逅论赤心，更约联翩书史笔。","坤爻敬义诚君子，可惜作铭人已死。","八十四字腾光芒，便是千年不欺史。"]},{"t":"郡斋对雪","f":"七言律诗","c":["平生为雪牵诗兴，今日无诗奈雪何。","净几翻书拥炉读，冷斋呵砚带冰磨。","寒江独钓句思柳，银海光摇人忆坡。","欲两三杯贺丰岁，却忧疆埸正干戈。"]},{"t":"子应和诗再用前韵","f":"七言律诗","c":["江东腊雪为谁多，清逼官梅兴动何。","堂坐玉芝劳想像，句工冰柱老研磨。","赓酬往事思蓬岛，灾异狂言忤谏坡。","听取金华新号令，要须白战不持戈。"]},{"t":"祠颜范二公","f":"七言律诗","c":["鄱江善政九贤人，文正文忠更绝伦。","桃李旧邦千里爱，丹青遗像两朝臣。","不同赤土祠刘阮，端胜睢阳庙远巡。","安得神仙返魂药，九原唤起静边尘。"]},{"t":"题何子应金华书院图","f":"词","c":["君不见杜陵野客老更狂，浣花溪上结草堂。","又不见谪仙世人皆欲杀，匡山读书头如雪。","二公同时鸣有唐，文章万丈光艳长。","钧天无人帝呼去，草堂书馆今荒凉。","太平宰相张居士，外甥似舅金华子。","胸中万卷杜陵翁，笔下千篇谪仙李。","向来衣冠拜伪楚，我乃宋臣惟有死。","何曾著眼痴宰相，况肯低颜骢御史。","天边卿月落九疑，口诵离骚吊湘水。","诛茅筑室小东山，天下苍生望公起。","种梅志欲调商鼎，持斧梦刀聊尔耳。","公生长安我东嘉，天遣邂逅鄱江涯。","笔头一语真戏剧，却将铁面拟金华。","金华自是金闺彦，金口褒扬两朝眷。","末须归去金华山，行将入侍金华殿。"]},{"t":"闰月三白三首 其一","f":"五言律诗","c":["闰月生明后，江天未腊时。","风翻禹门浪，花糁月宫枝。","照夜皎珠树，秀庭祥玉芝。","定知年大有，何止麦相宜。"]},{"t":"闰月三白三首 其二","f":"五言律诗","c":["迎腊雪三白，未春花万株。","神山森玉府，天象粲台符。","词吐水流峡，鼎成风击湖。","鬓边丝可织，四皓盍添吾。"]},{"t":"闰月三白三首 其三","f":"五言律诗","c":["占尽一阳月，分为六出时。","韦编照清夜，塞管落南枝。","献中荆山玉，开成庙柱芝。","人间瑞已定，过此却非宜。"]},{"t":"又和项服善二首 其一","f":"五言律诗","c":["风云频惨淡，草木屡苍颜。","诗里报琼玖，宫中归玉环。","帝庭侯帛至，佛殿宝珠还。","更有人清白，鄱阳似鲁山。"]},{"t":"又和项服善二首 其二","f":"五言律诗","c":["梅蕊开仍落，同云合末离。","添为五大老，真是四无私。","天女来成粲，冰蚕老欲丝。","梨花一枝雨，冷艳可能欺。"]},{"t":"又用时字韵","f":"五言律诗","c":["黄竹成章日，阳春众和时。","玉阶谈战陈，琼燕赐花枝。","陶径还飞絮，商山欠采芝。","西畴农事及，归去正吾宜。"]},{"t":"和洪景卢用三白韵作四白诗 其一","f":"五言律诗","c":["大似佛世界，端如玉烛时。","穆家兄弟味，杨氏子孙枝。","鄞海明瑶柱，鄱亭望秀芝。","祁寒繇政拙，去倍二诚宜。"]},{"t":"和洪景卢用三白韵作四白诗 其二","f":"五言律诗","c":["楚士照千乘，韩梨夸数株。","舜门纷执玉，尧岳衒分符。","宝结文房友，鉴明狂客湖。","郊圻正多垒，兵会忆夷吾。"]},{"t":"腊尽日又雪洪复作五白诗再和 其一","f":"五言律诗","c":["天地俱同数，嘉平欲尽时。","柳飘彭泽絮，松压大夫枝。","越绝山飞泄，文登石产芝。","滥骑为郡马，深愿谷相宜。"]},{"t":"腊尽日又雪洪复作五白诗再和 其二","f":"五言律诗","c":["日掩云间色，榆栽天上株。","芳联仙桂籍，穷送旧桃符。","远岫明庐阜，澄江接带湖。","宣麻开晋国，入蔡忆金吾。"]},{"t":"次韵何子应得宣城笔","f":"七言绝句","c":["金华手握管城子，端类睢阳太守须。","须笔有神人不识，怒时真可气吞胡。"]},{"t":"闻捷报用何韵","f":"七言绝句","c":["淮甸流离唐赤子，将军奇特魏黄须。","愿将银管书忠谊，粪土东京赵与胡。"]},{"t":"不欺室三字参政张公书也笔力劲健如端人正士俨然人望而敬之因成古诗八韵","f":"七言古诗","c":["云山老人国大老，历代遗编饫探讨。","馀事游神翰墨间，乘兴濡毫快挥扫。","严霜烈日如鲁公，抉石奔泉陋徐浩。","国朝君谟书第一，大字劣于行与草。","云山心画无不长，笔力纵时书更好。","我来求字盖求人，不为有官缘有道。","紫岩之铭云山笔，不欺室中双至宝。","玉箫峰下梅花溪，愿学云山归去早。"]},{"t":"出郊遇雪","f":"七言绝句","c":["小队出郊聊习战，朔风吹雪似催诗。","皇天有意诛骄虏，正类元戎破蔡时。"]},{"t":"何子应以蜀中文房四宝分赠洪景卢王嘉叟某与焉因成一绝","f":"七言绝句","c":["江左风流属宪台，笔端妙语出琼瑰。","滥居益友三人列，误辱文房四宝来。"]},{"t":"送翁东叟教授 其一","f":"七言律诗","c":["鄱阳江上五见雪，鄱江楼上风栗烈。","广文先生不畏冷，弭棹登楼兴清绝。","笔端妙语出离骚，酒后刚肠吐名节。","芝堂假守老乡人，明日仙舟那忍别。"]},{"t":"送翁东叟教授 其二","f":"七言律诗","c":["三十年间旧友生，眼青头白见交情。","官于湖北况尤冷，诗不江西语自清。","行李少留吴芮国，梦魂先到谢公城。","扁舟便合相随去，薄有田园正可耕。"]},{"t":"和宝印叔见寄 其一","f":"七言绝句","c":["官舍萧条怯莫冬，衰颜得酒晕生红。","遥思兰若堂中老，非柏非松自耐风。"]},{"t":"和宝印叔见寄 其二","f":"七言绝句","c":["滥乘五马二毛侵，雪满鄱江坐拥衾。","二叔年高兄弟远，归期当不待秋砧。"]},{"t":"用韵寄二弟 其一","f":"七言绝句","c":["六月离家忽莫冬，郡斋清夜拥炉红。","细看庆朔堂前雪，正似梅花溪上风。"]},{"t":"用韵寄二弟 其二","f":"七言绝句","c":["甚矣今年老见侵，玉芝堂冷敝衣衾。","梦魂夜夜寻兄弟，率饮亭前坐石砧。"]},{"t":"送蔡倅","f":"七言律诗","c":["白首论文得蔡侯，江东尊酒半年游。","龙头家世高千佛，骥足声名重一州。","方喜同僚吴芮国，不堪回首仲宣楼。","送君撩我思乡意，薄有田园归去休。"]},{"t":"齿落","f":"五言律诗","c":["五十行将四，浮生已向残。","齿疏方咄柳，牙落遽惊韩。","犹讶年初龀，翻疑颊未丹。","定知从此去，梨栗怯堆盘。"]},{"t":"次韵李怀安赠何宪五绝 其一","f":"七言绝句","c":["元老登朝首剡章，危言凛凛动明光。","掉头却向江湖去，不肯伊优上北堂。"]},{"t":"次韵李怀安赠何宪五绝 其二","f":"七言绝句","c":["伊洛横渠造道深，谁传衣钵见贞心。","儒宗赖有金华子，后学宁忧不嗣音。"]},{"t":"次韵李怀安赠何宪五绝 其三","f":"七言绝句","c":["梦魂闻说到无何，曾共神官壮者哦。","妙墨雄文满天下，士衡应亦患才多。"]},{"t":"次韵李怀安赠何宪五绝 其四","f":"七言绝句","c":["炙手权门尽好官，云山高卧老江干。","相期晚景全名节，富贵何须著眼看。"]},{"t":"次韵李怀安赠何宪五绝 其五","f":"七言绝句","c":["元白诗筒数往还，小生阁笔愧言艰。","异时应起鄱江念，公在金华我雁山。"]},{"t":"李怀安拥麾入蜀道出鄱江见赠二诗依韵奉酬 其一","f":"七言律诗","c":["不肯随群慕鹤轩，慨然丹陛吐危言。","坐看蜀道平如地，可见忠臣勇似尊。","驷马桥边驱弩矢，杜鹃声里拥旂幡。","要须入境询风俗，首访严遵李仲元。"]},{"t":"李怀安拥麾入蜀道出鄱江见赠二诗依韵奉酬 其二","f":"七言律诗","c":["一麾出守楚东城，邂逅论交愧孔程。","元礼仙舟行色好，子猷雪棹去心轻。","虎符稔服君家世，雁荡行逃我姓名。","酒盏诗篇话时事，江湖何日更寻盟。"]},{"t":"国娘生日","f":"五言律诗","c":["往岁王司业，初生嫡女孙。","命名聊志喜，曰国不忘恩。","日在元正次，身居辈行尊。","愿如班与孟，贤淑振吾门。"]},{"t":"陈阜卿书云闻诗筒甚盛可使流传江西否戏用竹萌韵以寄","f":"七言绝句","c":["江西大帅本仙官，馀事篇章过定安。","欲遣诗筒寄诗伯，恐嫌白俗孟郊寒。"]},{"t":"次何宪韵","f":"七言律诗","c":["毛颖神明更好须，飞腾入月跨蟾蜍。","谁将银管为封邑，端为金华妙简书。","凤翥龙蟠文未称，日光玉洁字还疏。","何如今代何平叔，笔阵词源总莫如。"]},{"t":"金华先生有奇石名碧远携来自蜀陈洪州以诗觅之金华辍所嗜以赠亦一段奇事也予家雁荡群峰错峙皆几案间物因和二公诗颇起乡思寓意断章","f":"七言律诗","c":["二公心古貌清癯，趣在林泉世味疏。","寸碧来从锦江远，九疑分向锡山居。","山中丘壑奴金谷，笔下波澜陋石渠。","我有千峰藏雁荡，擎天一柱插空虚。"]},{"t":"嘉叟宗丞得郡喜成一绝","f":"七言绝句","c":["邸报初闻见姓名，甘棠家世旧专城。","伯鱼诗礼趋庭处，五马旌旗夹道迎。"]},{"t":"人日雨次何宪韵","f":"五言律诗","c":["元正作佳天，涉七弄春气。","好雨亦知时，绿波行何济。","新诗如蜀州，句有梅柳味。","七升年定丰，一石公当醉。"]},{"t":"子应赠蜀中石刻十卷诗以谢之","f":"七言律诗","c":["金华石刻满西州，不惜明珠辄暗投。","诗泣鬼神追雅颂，义深君父妙春秋。","随身连轸崔评事，插架悬签李邺侯。","扫室焚香读终卷，光芒万丈照螺洲。"]},{"t":"次韵嘉叟读和韩诗","f":"五言古诗","c":["孔孟久不作，况雄莫能和。","韩公生有唐，力欲拯颓挫。","文兴八代衰，学救诸子过。","佛老蔓中华，微公衽其左。","馀事以诗鸣，语险鬼胆破。","汗澜高驾天，捷敏剧飞笴。","骑龙归帝旁，玉日人间堕。","汗流籍湜辈，圭璧分半个。","柳和词拟骚，郊联语成些。","咸知太山仰，谁继北窗卧。","我本齑盐生，久供笔砚课。","幽香摘天葩，光艳拾珠唾。","后公三百年，杖屦无从荷。","世无六一翁，孰知珍古货。","巴词拟阳春，僭窃罪宜坐。","神交有吾宗，涉世同坎轲。","学继青箱玉，诗高碧纱播。","勉令添和篇，才薄知何奈。","谬同赤效白，深愧愈知贺。","世事置勿论，蚊睫虫容么。"]},{"t":"元夕次何宪韵 其一","f":"七言绝句","c":["火树银花遍九衢，天移星斗下空虚。","心忧机妇寒窗士，诗句分明似谏书。"]},{"t":"元夕次何宪韵 其二","f":"七言绝句","c":["鄱阳灯火类残星，风雨那堪更满城。","为郡何如在家好，长檠不似短檠明。"]},{"t":"送何宪行部趣其早还","f":"七言绝句","c":["九郡饥民望使轺，阳春有脚不辞遥。","更须速返鄱君国，莫遣诗筒久寂寥。"]},{"t":"种金沙花戏呈景卢","f":"七言绝句","c":["春光骀荡楚天涯，李白桃红次第花。","未向名园看铁树，聊于郡圃种金沙。"]},{"t":"郡圃栽花","f":"七言律诗","c":["公馀吏隐不相赊，杖屦园林赏物华。","五柳宅边谁种柳，百花楼畔谩栽花。","池塘有梦吟春草，屏障无心恋绮霞。","来岁游人应话我，雁山深处老桑麻。"]},{"t":"二月朔日同嘉叟蕴之访景卢别墅用郡圃栽花韵即席唱和 其一","f":"七言律诗","c":["鄱水芝山四望赊，雨馀风物陪光华。","名园种果仍修果，妙手栽花似判花。","行见晋公开绿野，聊从子美酌流霞。","坐间宾主皆人杰，我质如蓬赖倚麻。"]},{"t":"二月朔日同嘉叟蕴之访景卢别墅用郡圃栽花韵即席唱和 其二","f":"七言律诗","c":["野处名园境界赊，夷坚博物似张华。","参天先种柳州柳，照眼兼看花县花。","即席赋诗袍夺锦，论文对酒脸生霞。","自惭衰病陪行乐，策杖登城脚欲麻。"]},{"t":"还舍复用前韵以寄","f":"七言律诗","c":["负郭园林路不赊，杖藜徐步赏韶华。","芹宫地近分流水，芝岭风高送落花。","檐外梨枝春带雨，城头桃树晚蒸霞。","行看共掌丝纶美，宁复丘中咏有麻。"]},{"t":"景卢嘉叟各和诗五首复用前韵","f":"七言律诗","c":["草堂相去不多赊，雨后登临唤革华。","心喜渊明尊有酒，眼惊太白笔生花。","来看四泽满时水，归见九光披处霞。","得两使君诗十首，郡斋传写费川麻。"]},{"t":"用韵怀何卿","f":"七言律诗","c":["送别鄱江日未赊，诗人相问忆金华。","乌衣巷口见归燕，万里桥西思浣花。","持节要先苏赤子，摄身未用踏苍霞。","行将归侍玉皇案，不比少陵鞋用麻。"]},{"t":"嘉叟和诗至七篇有何时五亩成归计来作邻翁伴艺麻之句某乡心方切复用韵","f":"七言律诗","c":["学继初寮事业赊，闭门宁悔读南华。","符分兴化日烘荔，室寓维摩天雨花。","故里君应怀北岳，归心我已到飞霞。","休休莫莫宜闲处，耕有添丁妇织麻。"]},{"t":"州宅十二咏 平政堂","f":"五言绝句","c":["恺悌周君子，循良汉守臣。","如今坐堂上，端是政平人。"]},{"t":"州宅十二咏 玉芝堂","f":"五言绝句","c":["不是因三秀，名堂意自深。","要居森戟地，毋忘采芝心。"]},{"t":"州宅十二咏 庆朔堂","f":"五言绝句","c":["昔日栽花者，官移花未开。","旧花今岂在，犹说范公栽。"]},{"t":"州宅十二咏 退思轩","f":"五言绝句","c":["会得名轩意，公馀坐片时。","退思何及矣，未退早须思。"]},{"t":"州宅十二咏 九贤堂","f":"五言绝句","c":["犹起才难叹，同时九乱臣。","鄱阳千载守，贤岂许多人。"]},{"t":"州宅十二咏 四贤堂","f":"五言绝句","c":["谁品鄱阳守，四人贤不知。","如何尧舜世，能使野无遗。"]},{"t":"州宅十二咏 四望亭","f":"五言绝句","c":["有泽宜观水，无檐不见山。","鄱君千里国，俯仰一亭间。"]},{"t":"州宅十二咏 绮霞亭","f":"五言绝句","c":["孤鹜同飞处，澄江共赋时。","晚来亭上看，真是谢公诗。"]},{"t":"州宅十二咏 清香亭","f":"五言绝句","c":["高架添风韵，芳醪共姓名。","苏州凝燕寝，疑是此香清。"]},{"t":"州宅十二咏 百花楼","f":"五言绝句","c":["昔日风流守，公馀种百花。","春风不检点，红紫落谁家。"]},{"t":"州宅十二咏 鄱江楼","f":"五言绝句","c":["郭外山横阁，江边水照楼。","粗官无暇日，何以得消忧。"]},{"t":"州宅十二咏 蜀锦亭","f":"五言绝句","c":["亭废名犹在，春来花自芳。","犹馀蜀中锦，爱惜比甘棠。"]},{"t":"州宅十二咏 景卢赠人面竹杖","f":"七言律诗","c":["奔走方嗟力不任，得公一杖直千金。","竹能有面如人面，人亦虚心似竹心。","渡水只愁龙欲化，入山应与凤联吟。","翰林虞部相酬赠，同舍交情复见今。"]},{"t":"乡人项服善宰鄱阳有政声人惜其去用郡圃栽花韵作诗数篇叙别遂和以送之 其一","f":"七言律诗","c":["七岁名师世胄赊，云孙行实副文华。","仁心驯及鲁恭雉，和气种成潘岳花。","清白见知鄱水月，高明相照楚天霞。","送君撩我思乡意，遥想吾庐日长麻。"]},{"t":"乡人项服善宰鄱阳有政声人惜其去用郡圃栽花韵作诗数篇叙别遂和以送之 其二","f":"七言律诗","c":["鄱江同事半年赊，直谅何人似去华。","吏报圜扉多鞠草，民歌枯木再生花。","暂留萧寺行逢雨，剩作新诗语带霞。","褒德自应侯卓茂，清朝知己况如麻。"]},{"t":"乡人项服善宰鄱阳有政声人惜其去用郡圃栽花韵作诗数篇叙别遂和以送之 其三","f":"七言律诗","c":["江东回首莫云赊，寒食令人感岁华。","皎皎丹心惟望日，星星短发不簪花。","书传何处山名雁，酒忆吾乡水似霞。","故旧相逢如问我，为言多病服天麻。"]},{"t":"乡人项服善宰鄱阳有政声人惜其去用郡圃栽花韵作诗数篇叙别遂和以送之 其四","f":"七言律诗","c":["公真有德如元令，我愧无才似李华。","话别芝堂倾竹叶，送行鄱水涨桃花。","眼看三匝乌逢月，心羡齐飞鹜趁霞。","它日相期访刘阮，分桃采药饮胡麻。"]},{"t":"予向年少不自量因读韩诗辄和数篇未尝敢出以示人盖二十年矣近因嘉叟见之不能自掩且赠以长篇蒙景卢继和用韵以谢","f":"五言古诗","c":["少小思尚奇，薰风琴欲和。","规模与时背，场屋屡摧挫。","大道窥五原，高论读二过。","神游京城南，思渺蒸水左。","竹看金影碎，菊撷霜风破。","论文摩巨刃，荐士躬彊笴。","萧兰发秋怀，木雁吟齿堕。","飞飞双鸟鸣，不数鹂两个。","幽幽十琴操，可仆兰台些。","光馀万丈长，照我一床卧。","未终三百篇，正坐短檠课。","不敢示友朋，惧遭泥滓唾。","文章吉太守，臭味夙相荷。","索我旧诗案，赠以千金货。","郡斋哦好句，艳艳月照坐。","端如陈琳檄，快读痊轗轲。","滥把江湖麾，谬声惭日播。","祈寒兼苦雨，怨嗟吾岂奈。","窃效衡山祷，因思鉴湖贺。","鹏鴳各逍遥，溟蓬无巨么。"]},{"t":"次韵陈阜卿读洪景卢追和玉板诗 其一","f":"七言绝句","c":["风采棱棱御史官，旌麾所至庶民安。","渭川千亩填匈臆，散作毫端风雨寒。"]},{"t":"次韵陈阜卿读洪景卢追和玉板诗 其二","f":"七言绝句","c":["前世书鱼化宰官，肺肠元与竹相安。","侯生韩子相酬赠，诗句惊人魂胆寒。"]},{"t":"次韵何宪脩途倦游怀鄱阳唱和之乐","f":"七言律诗","c":["马上诗成驿使驰，社中犹恨使来迟。","不堪冀北群空后，况是江东日莫时。","春半莺犹懒呼唤，雨多鸠亦厌分离。","论文尊酒何时共，公说归期我去期。"]},{"t":"次韵何宪太平道中书事","f":"五言律诗","c":["明刑清诏使，行部近清明。","况有太平象，想亡愁叹声。","问民知疾苦，按郡戒将迎。","更向金陵看，六朝馀故城。"]},{"t":"次韵何宪题鲁池州通隐堂","f":"五言律诗","c":["朝市隐诚好，山林通更嘉。","出非专为米，去亦不期瓜。","下惠何妨介，东方未用夸。","池州知此道，无愧仲连家。"]},{"t":"芝山劝农","f":"七言绝句","c":["出门非为采灵芝，端为农时不可违。","我欲劝农农劝我，田园薄有早须归。"]},{"t":"二月十五日祈晴十七日雷雨再作","f":"七言律诗","c":["清香一瓣乞晴回，准拟阳光万里开。","风伯未吹云阵破，雷公又唤雨声来。","补天石烂畴能鍊，陷泞车深不易推。","谁坐黄堂称太守，深惭无术救天灾。"]},{"t":"喜晴再用前韵","f":"七言律诗","c":["天闵斯民意已回，群阴不扫自应开。","扶桑晓日曈曈出，玉宇清风习习来。","水绿渔翁声欸乃，月明诗客手敲推。","秧针刺水麦摇浪，定有丰年无后灾。"]},{"t":"数日天气朝阴莫晴复用前韵","f":"七言律诗","c":["忍饥面目类颜回，仅得青天半日开。","且愿催诗无雨至，只宜送月有风来。","出游偶以文昌霁，待满当为桀溺推。","曰雨曰旸皆帝力，麦苗无害免书灾。"]},{"t":"哭何子应 其一","f":"五言律诗","c":["籍甚何夫子，文章擅美名。","金华传语宝，鄱水主诗盟。","心印横渠学，相门无尽甥。","人间一梦觉，卿月堕台城。"]},{"t":"哭何子应 其二","f":"五言律诗","c":["肮脏宜三黜，飘零到九疑。","忠膺黄屋眷，音遇紫岩知。","共理符频绾，明刑节屡持。","青天万里蜀，无复话归期。"]},{"t":"哭何子应 其三","f":"五言律诗","c":["公作皇华使，予乘郡守轓。","江湖吴芮国，襟抱杜陵尊。","翰墨频挥染，诗文细讨论。","新编刊未就，楚些已招魂。"]},{"t":"同官会饮鄱江楼送谷帘泉二尊戏成小诗","f":"七言绝句","c":["闻说楼中会八仙，郡斋分送谷帘泉。","好将投向鄱江水，共作长鲸吸百川。"]},{"t":"名郡之东门曰永平书一绝","f":"七言绝句","c":["鄱水新门号永平，永平何止一鄱城。","愿言广此平天下，黎庶长无愁叹声。"]},{"t":"主簿程同年和永平门诗再赋四绝因以赠别 其一","f":"七言绝句","c":["迂儒政事只平平，滥守鄱阳十里城。","赖有同年更同事，公馀时作苦吟声。"]},{"t":"主簿程同年和永平门诗再赋四绝因以赠别 其二","f":"七言绝句","c":["高唱犹嫌二谢平，偏师能破五言城。","鄱人口诵新门记，已作雷门振大声。"]},{"t":"主簿程同年和永平门诗再赋四绝因以赠别 其三","f":"七言绝句","c":["才知端如杜下平，异时何止任专城。","三年俛首栖榛棘，行作冲霄鸾凤声。"]},{"t":"主簿程同年和永平门诗再赋四绝因以赠别 其四","f":"七言绝句","c":["春尽湖如镜面平，扁舟送别古鄱城。","相将我亦为行客，征雁来时好寄声。"]},{"t":"送春","f":"七言绝句","c":["杨花榆荚满天飞，九十风光别我时。","凫鹜成行报公事，簿书中作送春诗。"]},{"t":"州院狱空赠知录孙听","f":"七言绝句","c":["把麾承乏楚邦东，狱及期年始报空。","顾我自惭无德政，同僚深喜有于公。"]},{"t":"鄱江楼分韵得月字","f":"七言绝句","c":["尊酒相逢人二八，年少壮夫予白发。","明年何处更登楼，遥望鄱阳江上月。"]},{"t":"前端午一日会饮鄱江楼十有六人既分韵赋诗又戏成短篇","f":"五言律诗","c":["佳节江楼上，同僚共把杯。","人如舜才子，名半汉云台。","诗占城南首，音参古磬枚。","宜添两学士，相约访蓬莱。"]},{"t":"五月二十日闵雨","f":"五言律诗","c":["仲夏百谷长，中沐群龙分。","此邦得何龙，行天莫辞勤。","愿于呼吸间，山川走风云。","亟下霈然泽，救我心如焚。"]},{"t":"次韵叶枢密言别","f":"七言律诗","c":["流落江湖岁月侵，九重侧席念公深。","汉庭宽大颁纶綍，楚阁清和襆枕衾。","大壑巨鱼欣复纵，虚舟积羽可能沉。","乾坤整顿须元老，芝岭柯山未许寻。"]},{"t":"洪景卢以郡酿饮客于野处园赋诗见寄次韵","f":"五言古诗","c":["老境厌吏事，归心绕丘园。","日月忽有夏，炎蒸变春温。","芝堂孰新酿，谁共论文尊。","缅怀蓬山旧，情好素所敦。","殷勤十从事，往扫东坡轩。","深杯滑琉璃，不比田家盆。","醉吟到高处，舞月成清欢。","我独坐空斋，静对忘忧萱。","萱多忧未忘，香清思犹昏。","怀君不成寐，两处一声猿。"]},{"t":"剡纸赠嘉叟以诗为谢次韵","f":"七言绝句","c":["仁义知君学子舆，岂惟词赋似相如。","剡溪百幅敲冰纸，换得临池小草书。"]},{"t":"伏日四望亭分韵得月字","f":"五言律诗","c":["伏日何处游，危亭阴清樾。","十客同我登，诗兴浩然发。","四檐山在眼，奚用更拄笏。","小饮未成醺，天边见新月。"]},{"t":"次韵赵通判喜雨","f":"七言绝句","c":["政拙时时费祷求，心忧赤子饿填沟。","一声霹雳中宵雨，洗出江湖万里秋。"]},{"t":"徐孺子亭","f":"五言古诗","c":["一室不暇扫，心期扫天下。","一榻不妄设，所待必贤者。","南州杰出士，林泉事潇洒。","闭门谢弓招，道合不吾舍。","谁云性少通，得一不为寡。","豫章岂私交，端欲重宗社。","汉廷无此贤，忍使遗在野。","交章荐天阙，聘礼备车马。","高人竟不屈，清风凛华夏。","寄声郭有道，一木难支厦。","肯同樊处士，声名祇虚假。","鸡酒吊知音，韬光老松槚。","倘令居孔门，行藏似回也。","江西今仲举，吏事饰儒雅。","神交千载友，丹青妙摹写。","作亭古东湖，鳞鳞万椽瓦。","序嗤滕阁王，词偪长沙贾。","佳客从公游，湖光瑩尊斝。","孺子真可师，世途何土苴。","行矣浙东西，锄犁各归把。"]},{"t":"张安国舍人以南陵鄱阳雨旸不同示诗次韵","f":"七言古诗","c":["春水平原天可拍，夏日如焚天可拆。","哀哉农民亦良苦，厌见常旸与常雨。","去秋鄱阳偶中熟，巨室犹言廪无谷。","万亩家输数千斛，路旁安得黔敖粥。","吾君罪己同禹汤，思起傅岩调雨旸。","暂勤千骑作南伯，要使炎峤无馀殃。"]},{"t":"又次韵闵雨","f":"七言古诗","c":["长夏蚊蝇倦驱拍，忽得缄封手亲拆。","新诗首及民疾苦，更闵鄱阳境无雨。","鄱阳假守仁不熟，作郡端如种焦谷。","匈中剩有愁千斛，阖门百指颜公粥。","紫微好善嗤弘汤，眉间和气如时旸。","行归廊庙赞化育，善人宜赏淫人殃。"]},{"t":"次韵安国读楚东酬唱集","f":"七言律诗","c":["麾把江湖遇列仙，赓酬篇什满鄱川。","窦家兄弟联珠日，庐阜峰峦夕照天。","三郡美名俱赫赫，一台遗墨尚鲜鲜。","紫微妙语题诗后，光艳真能照简编。"]}]};